INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C1','kor',4,1,'u1',2,'이 단원에서 배울 세 가지 — 인물들의 관계 파악하기 · 이야기의 흐름 파악하기 · 질문을 만들어 내용 짐작하기',ARRAY['단원 배울 내용 살펴보기(성취기준 번호 확인 필요)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C2','kor',4,1,'u1',2,'인물들의 관계 — 이야기에 나오는 인물과 인물 사이 — 대표적으로 도와주는 관계와 갈등하는 관계가 있음',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C3','kor',4,1,'u1',2,'도와주는 관계 — 힘들 때 나서서 일을 거들어 준 인물과의 사이(콩쥐와 황소·두꺼비·새들)',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C4','kor',4,1,'u1',2,'갈등하는 관계 — 서로 부딪히거나 괴롭히고 밀어내는 인물과의 사이(콩쥐와 팥쥐·새어머니)',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C5','kor',4,1,'u1',2,'우리는 이미 짐작하며 읽음 — 제목으로 내용을 · 말과 행동으로 성격을 · 앞뒤로 낱말 뜻을 짐작해 본 적이 있음',ARRAY['단원 배울 내용 살펴보기(성취기준 번호 확인 필요)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C6','kor',4,1,'u1',2,'이어질 일은 앞 내용으로 짐작 — 그늘의 주인이 바뀌었으니 그늘이 옮겨 가는 곳까지 사람들이 따라간다 — 앞에 나온 일에서 실마리를 찾음',ARRAY['단원 배울 내용 살펴보기(성취기준 번호 확인 필요)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C7','kor',4,1,'u1',2,'성격과 역할은 말과 행동에 — 인물의 성격과 역할은 인물이 한 말과 행동, 특히 결정적인 장면에 드러남',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C8','kor',4,1,'u1',2,'단서는 그 인물이 한 말과 행동 — 하준이의 성격은 하준이가 한 말과 행동에서 찾음 — 다른 인물이 하준이에 대해 한 말은 말한 사람의 단서',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C9','kor',4,1,'u1',2,'겉으로 드러난 것만 보고 한 판단 — 태오는 하준이가 그림을 못 그린다는 겉모습만 보고 색칠만 하라고 함',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C10','kor',4,1,'u1',2,'관계는 흐름에 따라 바뀜 — 같은 두 인물도 처음과 끝의 관계가 다를 수 있음 — 하준이와 태오는 갈등하다가 서로 인정하게 됨',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C11','kor',4,1,'u1',2,'관계를 파악하면 좋은 점 — 인물을 깊이 이해하고 이야기의 흐름을 잘 파악할 수 있음 — 빨리 읽기 · 낱말 외우기 ✗',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C12','kor',4,1,'u1',2,'관계를 파악하는 방법 — 주요 장면 떠올리기 → 말과 행동으로 성격과 역할 살피기 → 도와주는 관계인지 갈등하는 관계인지 정리하기',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C13','kor',4,1,'u1',2,'인물의 마음은 겪은 일에서 — 콩쥐는 황소에게 도움을 받았으니 고마운 마음 — 인물이 겪은 일을 보고 마음을 짐작함',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C14','kor',4,1,'u1',3,'이야기의 흐름 — 이야기가 진행되는 과정 — 흐름을 따라가며 읽으면 내용을 훨씬 잘 이해함',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C15','kor',4,1,'u1',3,'중요한 일만 차례대로 — 있었던 일을 하나도 빠짐없이 말하면 듣는 사람이 오히려 헷갈림 — 중요한 일만 차례대로 전함',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C16','kor',4,1,'u1',3,'잘 정리한 흐름의 모습 — 너무 짧아 내용을 알 수 없지도, 너무 자세해 원래 이야기와 다를 바 없지도 않게 — 중요한 일을 차례대로 담음',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C17','kor',4,1,'u1',3,'흐름을 정리하는 기준 — 인물에게 일어난 중요한 일을 중심으로, 시간과 장소의 변화에 따라 정리함',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C18','kor',4,1,'u1',3,'중요한 일 가려내기 — 그 일이 빠지면 이야기가 이어지지 않는 일만 고름 — 날씨 · 집 앞 모습처럼 빠져도 이어지는 일 ✗',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C19','kor',4,1,'u1',3,'어머니가 낸 시험 — 어머니는 호롱불을 끄고 어둠 속에서 석봉은 글씨를 쓰고 어머니는 떡을 썰게 함',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C20','kor',4,1,'u1',3,'인물마다 일어난 일 — 어둠 속에서 어머니는 떡을 고르게 썰었고, 석봉은 글씨를 크기도 모양도 제각각으로 씀',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C21','kor',4,1,'u1',3,'일어난 차례 — 고향집으로 돌아옴 → 불을 끄고 글씨를 쓰게 함 → 떡은 고르고 글씨는 제각각 → 한양으로 돌아가 공부함',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C22','kor',4,1,'u1',3,'흐름을 파악하는 방법 — 인물 · 장소 · 일어난 일 찾기 / 시간이나 장소의 변화 살피기 / 일이 일어난 차례 정리하기',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C23','kor',4,1,'u1',3,'명필 — 글씨를 잘 쓰기로 이름난 사람',ARRAY['앞뒤 문장으로 낱말 뜻 짐작하기(성취기준 번호 확인 필요)']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C24','kor',4,1,'u1',3,'석봉의 마음 변화 — 명필이 되었다고 자만했다가, 떡과 글씨를 견주어 본 뒤 부끄러워하며 다시 공부에 힘씀',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C25','kor',4,1,'u1',5,'관계를 중심으로 흐름 파악 — 인물들의 관계가 바뀌는 곳이 이야기 흐름의 마디 — 관계를 따라가면 이야기가 한눈에 보임',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C26','kor',4,1,'u1',5,'무루가 위험을 알아챈 방법 — 눈 대신 앞발 끝으로 흙이 잘게 떨리는 것을 느껴 굴이 무너지는 것을 먼저 알아챔',ARRAY['이야기의 흐름 파악하기(성취기준 번호 확인 필요)']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C27','kor',4,1,'u1',5,'마음을 나타내는 표현의 뜻 — 하늘이 노래지도록(충격으로 정신이 아찔하게) · 호들갑을 떨다(가볍고 야단스럽게 굴다) · 가슴이 찢어질 듯(큰 고통) — 앞뒤 문장으로 짐작',ARRAY['앞뒤 문장으로 낱말 뜻 짐작하기(성취기준 번호 확인 필요)']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C28','kor',4,1,'u1',5,'인물의 성격과 역할 — 무루 = 포기하지 않음 · 마을을 구함 / 마루 = 따뜻하고 한결같음 · 보살핌 / 또래 두더지들 = 겉만 보고 판단 · 힘들게 함',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C29','kor',4,1,'u1',5,'갈등이 드러난 장면 — 서로 돕는 장면이 아니라 부딪히거나 밀어내는 말과 행동이 나온 장면',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C30','kor',4,1,'u1',5,'관계를 중심으로 흐름 정리 — 두더지들이 무루를 따돌림 → 마루가 굴 파는 법을 알려 줌 → 큰비 온 밤 → 무루가 앞장서 모두를 구함',ARRAY['인물들의 관계 파악하기(성취기준 번호 확인 필요)']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
