INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-1-u1-C59','kor',4,1,'u1',11,'상황에 맞는 마음 낱말 — 인물이 겪은 일에 맞는 마음 낱말을 고르면 마음을 더 또렷하게 말할 수 있음',ARRAY['마음을 나타내는 낱말(성취기준 번호 확인 필요)']::text[],59) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X01','kor',4,'u1',ARRAY['K4-1-u1-C1','K4-1-u1-C53']::text[],'이 단원에서 배울 것을 인물·흐름·질문이 아닌 것(빨리 읽기·낱말 외우기·셈하기)으로 여긴다','인물 · 흐름 · 질문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X02','kor',4,'u1',ARRAY['K4-1-u1-C2','K4-1-u1-C3','K4-1-u1-C4']::text[],'도와주는 관계와 갈등하는 관계를 엇갈리게 고른다','거들었나, 부딪혔나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X03','kor',4,'u1',ARRAY['K4-1-u1-C13','K4-1-u1-C59']::text[],'인물의 마음을 그 인물이 겪은 일과 상관없이 짐작한다','무슨 일을 겪었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X04','kor',4,'u1',ARRAY['K4-1-u1-C6','K4-1-u1-C42']::text[],'이어질 일을 앞 내용·제목과 상관없이 짐작한다','앞에 나온 실마리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X05','kor',4,'u1',ARRAY['K4-1-u1-C6']::text[],'앞 내용은 보지 않고 겉으로 좋아 보이는 쪽으로만 이어질 일을 짐작한다','그늘은 어디로 가나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X06','kor',4,'u1',ARRAY['K4-1-u1-C7','K4-1-u1-C28']::text[],'성격을 말과 행동이 아닌 겉모습이나 이름으로 판단한다','무슨 말, 무슨 행동?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X07','kor',4,'u1',ARRAY['K4-1-u1-C8']::text[],'다른 인물이 그 인물에 대해 한 말을 그 인물의 성격 단서로 모은다','누가 한 말인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X08','kor',4,'u1',ARRAY['K4-1-u1-C10','K4-1-u1-C25']::text[],'인물들의 관계는 처음 그대로 끝까지 바뀌지 않는다고 여긴다','처음과 끝을 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X09','kor',4,'u1',ARRAY['K4-1-u1-C11']::text[],'관계를 파악하면 좋은 점을 빨리 읽기나 낱말 외우기에서 찾는다','인물과 흐름이 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X10','kor',4,'u1',ARRAY['K4-1-u1-C9','K4-1-u1-C26']::text[],'인물이 한 행동의 까닭을 이야기에 나오지 않은 데서 찾는다','이야기에 나왔나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X11','kor',4,'u1',ARRAY['K4-1-u1-C12','K4-1-u1-C2']::text[],'관계를 두 인물 사이가 아니라 한 인물만 보고 정하거나 장면을 떠올리지 않고 정한다','둘 사이를 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X12','kor',4,'u1',ARRAY['K4-1-u1-C15','K4-1-u1-C16']::text[],'있었던 일을 하나도 빠짐없이 모두 옮겨야 흐름을 잘 정리한 것이라 여긴다','다 옮기면 헷갈려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X13','kor',4,'u1',ARRAY['K4-1-u1-C16']::text[],'한 문장으로 짧게 줄일수록 흐름을 잘 정리한 것이라 여긴다','내용이 보이나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X14','kor',4,'u1',ARRAY['K4-1-u1-C18']::text[],'흐름에 꼭 필요하지 않은 일(날씨·집 앞 모습)을 중요한 일로 고른다','빠지면 끊기나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X15','kor',4,'u1',ARRAY['K4-1-u1-C21','K4-1-u1-C50']::text[],'일이 일어난 차례를 뒤섞는다','무엇이 먼저?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X16','kor',4,'u1',ARRAY['K4-1-u1-C20']::text[],'인물과 그 인물에게 일어난 일을 엇갈리게 잇거나 이야기에 없는 인물의 일을 끌어온다','누가 무엇을?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X17','kor',4,'u1',ARRAY['K4-1-u1-C17','K4-1-u1-C22']::text[],'시간과 장소의 변화를 살피지 않고 마음에 드는 장면만 골라 흐름을 정리한다','언제 · 어디가 바뀌었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X18','kor',4,'u1',ARRAY['K4-1-u1-C19']::text[],'어머니가 석봉을 시험한 방법을 이야기에 없는 것으로 여긴다','방 안에서 먼저 한 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X19','kor',4,'u1',ARRAY['K4-1-u1-C24']::text[],'석봉이 끝까지 자만했다고 여기거나 마음이 바뀐 까닭을 엉뚱한 데서 찾는다','떡과 글씨를 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X20','kor',4,'u1',ARRAY['K4-1-u1-C23','K4-1-u1-C37','K4-1-u1-C46']::text[],'낱말이 나온 앞뒤 문장을 살피지 않고 뜻을 엇갈리게 짐작한다','그 문장을 다시 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X21','kor',4,'u1',ARRAY['K4-1-u1-C27']::text[],'마음을 나타내는 표현을 글자 그대로의 뜻(하늘 색이 바뀜)으로 받아들인다','어떤 느낌인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X22','kor',4,'u1',ARRAY['K4-1-u1-C27']::text[],'마음을 나타내는 표현들의 뜻을 서로 엇갈리게 안다','그 장면의 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X23','kor',4,'u1',ARRAY['K4-1-u1-C29']::text[],'갈등이 드러난 장면을 고를 때 도와주는 장면을 섞는다','밀어내는 장면만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X24','kor',4,'u1',ARRAY['K4-1-u1-C28']::text[],'인물과 그 인물의 성격·역할을 엇갈리게 잇는다','누구에게 무엇을 했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X25','kor',4,'u1',ARRAY['K4-1-u1-C31']::text[],'글쓴이가 전하고 싶은 생각을 이야기 속 작은 사실에서 찾는다','흐름 전체를 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X26','kor',4,'u1',ARRAY['K4-1-u1-C31']::text[],'나와 다른 것을 틀린 것이나 모자란 것으로 여긴다','다름 ≠ 틀림') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X27','kor',4,'u1',ARRAY['K4-1-u1-C30','K4-1-u1-C25']::text[],'관계를 중심으로 흐름을 정리하며 관계가 바뀐 마디를 빠뜨린다','어디서 바뀌었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X28','kor',4,'u1',ARRAY['K4-1-u1-C32']::text[],'이야기 속 관계는 내 생활과 상관없다고 여긴다','내 주변에도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X29','kor',4,'u1',ARRAY['K4-1-u1-C33']::text[],'질문은 글을 다 읽고 난 뒤에만 만드는 것이라 여긴다','읽기 전 · 읽는 중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X30','kor',4,'u1',ARRAY['K4-1-u1-C34']::text[],'읽기 전에도 글 속 낱말이 들어간 질문을 만들 수 있다고 여긴다','아직 안 읽었어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X31','kor',4,'u1',ARRAY['K4-1-u1-C35']::text[],'옹기를 숨 쉬는 그릇이라 부르는 까닭을 글에 없는 데서 찾는다','작은 구멍') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X32','kor',4,'u1',ARRAY['K4-1-u1-C36']::text[],'옹기 허리가 불룩한 까닭을 보기 좋은 모양에서 찾는다','틈과 바람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X33','kor',4,'u1',ARRAY['K4-1-u1-C38','K4-1-u1-C39']::text[],'질문과 그 질문을 만든 갈래를 엇갈리게 잇는다','무엇이 담겼나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X34','kor',4,'u1',ARRAY['K4-1-u1-C40']::text[],'글자 수·쪽수·줄 수를 세는 질문을 내용을 짐작하는 질문으로 고른다','세는 질문 ✗') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X35','kor',4,'u1',ARRAY['K4-1-u1-C41']::text[],'답이 글에 그대로 나와 있는 질문이 가장 좋은 질문이라 여긴다','빈 곳을 메워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X36','kor',4,'u1',ARRAY['K4-1-u1-C41','K4-1-u1-C47']::text[],'질문은 많이 만들수록 좋은 질문이라 여긴다','개수보다 내용') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X37','kor',4,'u1',ARRAY['K4-1-u1-C42','K4-1-u1-C43']::text[],'제목과 차례는 건너뛰고 본문부터 읽어 실마리를 놓친다','제목 · 차례부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X38','kor',4,'u1',ARRAY['K4-1-u1-C45']::text[],'씨앗을 되살리는 길을 냉동실에 두기만 하거나 새로 사 오는 데서 찾는다','나누고 심고 거두기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X39','kor',4,'u1',ARRAY['K4-1-u1-C44']::text[],'조상들이 씨앗을 남긴 까닭을 글에 없는 데서 찾는다','씨앗에 담긴 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X40','kor',4,'u1',ARRAY['K4-1-u1-C49']::text[],'짐작한 내용과 글이 다르면 잘못 읽은 것이라 여겨 짐작을 고쳐 쓴다','다른 점 = 새로 안 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X41','kor',4,'u1',ARRAY['K4-1-u1-C48']::text[],'짐작과 글을 견줄 때 내용이 아닌 것(그림 수·글자 크기)을 견준다','내용끼리 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X42','kor',4,'u1',ARRAY['K4-1-u1-C47']::text[],'읽는 중에 떠오른 질문을 글에서 답을 찾아보지 않고 넘긴다','글에서 찾아봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X43','kor',4,'u1',ARRAY['K4-1-u1-C51']::text[],'이야기를 만들 때 차례만 늘어놓고 인물의 말과 행동은 넣지 않는다','말과 행동을 넣어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X44','kor',4,'u1',ARRAY['K4-1-u1-C52']::text[],'누구일까 놀이에서 정답을 미리 알려 주거나 이름을 가리지 않는다','□로 가려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X45','kor',4,'u1',ARRAY['K4-1-u1-C54']::text[],'받침 ㄷ·ㅌ 뒤에 ㅣ가 와도 글자 그대로 소리 낸다','[ㅈ] · [ㅊ]으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X46','kor',4,'u1',ARRAY['K4-1-u1-C56']::text[],'바뀐 소리대로 적는다(해도지 · 가치)','쓸 때는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X47','kor',4,'u1',ARRAY['K4-1-u1-C55']::text[],'받침 ㄷ 뒤에 히가 올 때 [ㅈ]이나 [ㄷ]으로 소리 낸다','ㄷ + 히 → [ㅊ]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X48','kor',4,'u1',ARRAY['K4-1-u1-C57']::text[],'받침이 아닌 ㄷ·ㅌ(어디·잔디·마디)도 소리가 바뀐다고 여긴다','받침인가요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-1-u1-X49','kor',4,'u1',ARRAY['K4-1-u1-C58']::text[],'뜻이 비슷한 마음 낱말을 엇갈리게 잇는다','기쁨 · 외로움 · 서운함') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_basic#1','kor',4,1,'u1','L02','g4_1_kor_u1_L02_basic','lesson_basic','K4-1-u1-C2',1,'mc','auto','이야기에 나오는 인물과 인물 사이를 무엇이라고 하나요?',ARRAY['K4-1-u1-X06','K4-1-u1-X01']::text[],false,'{"seq":1,"concept":"K4-1-u1-C2","difficulty":1,"kind":"mc","stem":"이야기에 나오는 인물과 인물 사이를 무엇이라고 하나요?","options":[{"t":"인물들의 관계","correct":true},{"t":"인물의 생김새","mis":"K4-1-u1-X06"},{"t":"이야기의 제목","mis":"K4-1-u1-X01"},{"t":"인물의 이름","mis":"K4-1-u1-X06"}],"explanation":["인물 「사이」를 말해요.","도와주거나 갈등하기도 해요.","인물들의 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_basic#2','kor',4,1,'u1','L02','g4_1_kor_u1_L02_basic','lesson_basic','K4-1-u1-C4',1,'mc','auto','「콩쥐팥쥐」에서 콩쥐와 갈등하는 관계인 인물은 누구인가요?',ARRAY['K4-1-u1-X02']::text[],false,'{"seq":2,"concept":"K4-1-u1-C4","difficulty":1,"kind":"mc","stem":"「콩쥐팥쥐」에서 콩쥐와 갈등하는 관계인 인물은 누구인가요?","options":[{"t":"팥쥐","correct":true},{"t":"황소","mis":"K4-1-u1-X02"},{"t":"두꺼비","mis":"K4-1-u1-X02"},{"t":"새들","mis":"K4-1-u1-X02"}],"explanation":["콩쥐를 괴롭힌 인물은?","도와준 인물과 가려요.","팥쥐예요."],"asset":{"type":"passage","lines":["호미가 부러져 울고 있던 콩쥐에게 황소가 다가와 밭의 풀을 뽑아 주었다.","깨진 독에 물을 채워야 할 때는 두꺼비가 구멍을 막아 주었다.","새들은 벼를 대신 찧어 주었다.","팥쥐는 콩쥐를 괴롭혔고, 새어머니는 어려운 일만 시켰다."],"title":"콩쥐팥쥐"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_basic#3','kor',4,1,'u1','L02','g4_1_kor_u1_L02_basic','lesson_basic','K4-1-u1-C13',1,'mc','auto','콩쥐는 밭의 풀을 뽑아 준 황소에게 어떤 마음이 들었을까요?',ARRAY['K4-1-u1-X03']::text[],false,'{"seq":3,"concept":"K4-1-u1-C13","difficulty":1,"kind":"mc","stem":"콩쥐는 밭의 풀을 뽑아 준 황소에게 어떤 마음이 들었을까요?","options":[{"t":"도움을 받아 고마운 마음","correct":true},{"t":"일을 방해해서 미운 마음","mis":"K4-1-u1-X03"},{"t":"아무 생각이 없는 마음","mis":"K4-1-u1-X03"},{"t":"황소가 무서워 겁나는 마음","mis":"K4-1-u1-X03"}],"explanation":["황소가 무엇을 해 주었나요?","풀을 뽑아 주었어요.","고마운 마음이에요."],"asset":{"type":"passage","lines":["호미가 부러져 울고 있던 콩쥐에게 황소가 다가와 밭의 풀을 뽑아 주었다.","깨진 독에 물을 채워야 할 때는 두꺼비가 구멍을 막아 주었다.","새들은 벼를 대신 찧어 주었다.","팥쥐는 콩쥐를 괴롭혔고, 새어머니는 어려운 일만 시켰다."],"title":"콩쥐팥쥐"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_basic#4','kor',4,1,'u1','L02','g4_1_kor_u1_L02_basic','lesson_basic','K4-1-u1-C1',1,'mc','auto','「깊이 있게 읽어요」 단원에서 배울 세 가지로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X01']::text[],false,'{"seq":4,"concept":"K4-1-u1-C1","difficulty":1,"kind":"mc","stem":"「깊이 있게 읽어요」 단원에서 배울 세 가지로 알맞은 것은 무엇인가요?","options":[{"t":"인물들의 관계 · 이야기의 흐름 · 질문을 만들어 내용 짐작하기","correct":true},{"t":"빨리 읽기 · 소리 내어 읽기 · 받아쓰기","mis":"K4-1-u1-X01"},{"t":"낱말 외우기 · 글자 세기 · 쪽수 세기","mis":"K4-1-u1-X01"},{"t":"인물 그리기 · 노래 부르기 · 춤추기","mis":"K4-1-u1-X01"}],"explanation":["인물 → 흐름 → 질문","세 가지를 차례로 배워요.","깊이 읽는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_basic#5','kor',4,1,'u1','L02','g4_1_kor_u1_L02_basic','lesson_basic','K4-1-u1-C6',2,'mc','auto','책 광고를 읽고 그늘을 판 영감에게 이어질 일을 짐작했어요. 가장 그럴듯한 것은 무엇인가요?',ARRAY['K4-1-u1-X05','K4-1-u1-X04']::text[],false,'{"seq":5,"concept":"K4-1-u1-C6","difficulty":2,"kind":"mc","stem":"책 광고를 읽고 그늘을 판 영감에게 이어질 일을 짐작했어요. 가장 그럴듯한 것은 무엇인가요?","options":[{"t":"그늘이 옮겨 가는 곳마다 사람들이 따라와 영감이 곤란해진다","correct":true},{"t":"그늘을 판 돈으로 더 편하게 지낸다","mis":"K4-1-u1-X05"},{"t":"나무를 한 그루 더 심는다","mis":"K4-1-u1-X04"},{"t":"총각과 함께 먼 마을로 이사한다","mis":"K4-1-u1-X04"}],"explanation":["그늘의 주인이 바뀌었어요.","그늘은 해를 따라 옮겨 가요.","앞 내용에서 짐작해요."],"asset":{"type":"passage","lines":["① 어느 마을에, 집 앞 나무 그늘은 자기만 쓸 수 있다고 우기는 영감이 살았어요.","② 한 총각이 영감에게 돈을 주고 그 나무 그늘을 사겠다고 했어요.","③ 욕심 많은 영감은 얼른 그늘을 팔았지요.","④ 총각은 그 그늘을 마을 사람들과 함께 사용했어요."],"title":"책 광고 — 나무 그늘을 산 총각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_basic#6','kor',4,1,'u1','L02','g4_1_kor_u1_L02_basic','lesson_basic','K4-1-u1-C5',2,'match','auto','우리가 이미 해 본 짐작과 무엇을 보고 짐작했는지를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-1-u1-C5","difficulty":2,"kind":"match","stem":"우리가 이미 해 본 짐작과 무엇을 보고 짐작했는지를 알맞게 이으세요.","pairs":[{"l":"어떤 내용일지","r":"책의 제목"},{"l":"인물의 성격","r":"인물의 말과 행동"},{"l":"모르는 낱말의 뜻","r":"낱말의 앞뒤 문장"}],"mis":"K4-1-u1-X04","explanation":["제목은 내용의 실마리","말과 행동에 성격","앞뒤 문장에 뜻"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_basic#7','kor',4,1,'u1','L02','g4_1_kor_u1_L02_basic','lesson_basic','K4-1-u1-C7',2,'mc','auto','인물의 성격과 역할은 주로 무엇에 드러나나요?',ARRAY['K4-1-u1-X06','K4-1-u1-X07']::text[],false,'{"seq":7,"concept":"K4-1-u1-C7","difficulty":2,"kind":"mc","stem":"인물의 성격과 역할은 주로 무엇에 드러나나요?","options":[{"t":"인물이 한 말과 행동","correct":true},{"t":"인물의 이름","mis":"K4-1-u1-X06"},{"t":"인물의 옷차림과 생김새","mis":"K4-1-u1-X06"},{"t":"다른 인물이 붙인 별명","mis":"K4-1-u1-X07"}],"explanation":["결정적인 장면을 봐요.","무슨 말을 하고 무엇을 했나요?","말과 행동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_basic#8','kor',4,1,'u1','L02','g4_1_kor_u1_L02_basic','lesson_basic','K4-1-u1-C9',2,'mc','auto','태오가 하준이에게 「색칠만 해」라고 한 까닭은 무엇인가요?',ARRAY['K4-1-u1-X10']::text[],false,'{"seq":8,"concept":"K4-1-u1-C9","difficulty":2,"kind":"mc","stem":"태오가 하준이에게 「색칠만 해」라고 한 까닭은 무엇인가요?","options":[{"t":"하준이가 그림을 잘 못 그린다고 여겨서","correct":true},{"t":"미술 시간이 모자랐기 때문에","mis":"K4-1-u1-X10"},{"t":"색칠이 가장 어려운 일이어서","mis":"K4-1-u1-X10"},{"t":"서아가 그렇게 하자고 해서","mis":"K4-1-u1-X10"}],"explanation":["①을 다시 봐요.","태오는 무엇만 보았나요?","겉으로 드러난 모습이에요."],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_basic#9','kor',4,1,'u1','L02','g4_1_kor_u1_L02_basic','lesson_basic','K4-1-u1-C10',2,'match','auto','「미술 시간에 생긴 일」에서 인물들의 관계를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u1-C10","difficulty":2,"kind":"match","stem":"「미술 시간에 생긴 일」에서 인물들의 관계를 알맞게 이으세요.","pairs":[{"l":"하준이와 서아","r":"도와주는 관계"},{"l":"하준이와 태오(처음)","r":"갈등하는 관계"},{"l":"하준이와 태오(끝)","r":"서로 인정하는 관계"}],"mis":"K4-1-u1-X08","explanation":["처음과 끝을 견줘요.","같은 두 인물도 달라져요.","관계는 바뀌기도 해요."],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_basic#10','kor',4,1,'u1','L02','g4_1_kor_u1_L02_basic','lesson_basic','K4-1-u1-C8',3,'mc','auto','하준이의 성격을 알아보려고 해요. 하준이의 단서로 모아야 할 것은 무엇인가요?',ARRAY['K4-1-u1-X07']::text[],false,'{"seq":10,"concept":"K4-1-u1-C8","difficulty":3,"kind":"mc","stem":"하준이의 성격을 알아보려고 해요. 하준이의 단서로 모아야 할 것은 무엇인가요?","options":[{"t":"③ 아무 말도 못 하고 붓만 만지작거렸다","correct":true},{"t":"② \"그림은 우리가 그릴게.\"","mis":"K4-1-u1-X07"},{"t":"④ \"네가 고른 색이 늘 예쁘던데.\"","mis":"K4-1-u1-X07"},{"t":"⑤ 못마땅한 얼굴로 팔짱을 꼈다","mis":"K4-1-u1-X07"}],"explanation":["누가 한 말과 행동인가요?","하준이가 한 것만 모아요.","③이에요."],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_challenge#1','kor',4,1,'u1','L02','g4_1_kor_u1_L02_challenge','lesson_challenge','K4-1-u1-C11',2,'mc','auto','인물들의 관계를 파악하면 좋은 점은 무엇인가요?',ARRAY['K4-1-u1-X09']::text[],false,'{"seq":1,"concept":"K4-1-u1-C11","difficulty":2,"kind":"mc","stem":"인물들의 관계를 파악하면 좋은 점은 무엇인가요?","options":[{"t":"인물을 깊이 이해하고 이야기의 흐름을 잘 파악할 수 있다","correct":true},{"t":"이야기를 더 빨리 읽을 수 있다","mis":"K4-1-u1-X09"},{"t":"어려운 낱말을 모두 외울 수 있다","mis":"K4-1-u1-X09"},{"t":"인물이 모두 몇 명인지 셀 수 있다","mis":"K4-1-u1-X09"}],"explanation":["관계를 알면 무엇이 보이나요?","인물과 이야기가 보여요.","깊이 이해하게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_challenge#2','kor',4,1,'u1','L02','g4_1_kor_u1_L02_challenge','lesson_challenge','K4-1-u1-C12',2,'mc','auto','인물들의 관계를 파악하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X11','K4-1-u1-X06']::text[],false,'{"seq":2,"concept":"K4-1-u1-C12","difficulty":2,"kind":"mc","stem":"인물들의 관계를 파악하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"주요 장면 떠올리기 → 말과 행동 살피기 → 관계 정리하기","correct":true},{"t":"관계 먼저 정하기 → 장면 찾기 → 말과 행동 살피기","mis":"K4-1-u1-X11"},{"t":"인물 한 명의 성격만 정하고 끝내기","mis":"K4-1-u1-X11"},{"t":"생김새 살피기 → 이름 외우기 → 관계 정리하기","mis":"K4-1-u1-X06"}],"explanation":["장면부터 떠올려요.","말과 행동으로 성격을","그다음 관계를 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_challenge#3','kor',4,1,'u1','L02','g4_1_kor_u1_L02_challenge','lesson_challenge','K4-1-u1-C10',3,'mc','auto','「긴 줄넘기 연습」에서 민호와 수아의 관계를 바르게 말한 것은 무엇인가요?',ARRAY['K4-1-u1-X08','K4-1-u1-X11']::text[],false,'{"seq":3,"concept":"K4-1-u1-C10","difficulty":3,"kind":"mc","stem":"「긴 줄넘기 연습」에서 민호와 수아의 관계를 바르게 말한 것은 무엇인가요?","options":[{"t":"처음에는 갈등하다가 끝에는 수아가 민호를 인정한다","correct":true},{"t":"처음부터 끝까지 갈등하는 관계이다","mis":"K4-1-u1-X08"},{"t":"처음부터 끝까지 도와주는 관계이다","mis":"K4-1-u1-X08"},{"t":"두 사람은 서로 상관없는 사이이다","mis":"K4-1-u1-X11"}],"explanation":["③과 ⑧을 견줘요.","수아의 말이 달라졌어요.","관계가 바뀌었어요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_challenge#4','kor',4,1,'u1','L02','g4_1_kor_u1_L02_challenge','lesson_challenge','K4-1-u1-C3',3,'mc','auto','「긴 줄넘기 연습」에서 민호와 도와주는 관계인 인물과 그 까닭을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-1-u1-X02','K4-1-u1-X10']::text[],false,'{"seq":4,"concept":"K4-1-u1-C3","difficulty":3,"kind":"mc","stem":"「긴 줄넘기 연습」에서 민호와 도와주는 관계인 인물과 그 까닭을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"은채 — 민호가 할 수 있는 일을 찾아 주었다","correct":true},{"t":"수아 — 민호에게 빠지라고 말했다","mis":"K4-1-u1-X02"},{"t":"은채 — 민호를 줄 밖으로 내보냈다","mis":"K4-1-u1-X10"},{"t":"수아 — 민호 대신 구령을 붙였다","mis":"K4-1-u1-X10"}],"explanation":["⑤를 봐요.","구령을 붙이자고 했어요.","은채예요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_challenge#5','kor',4,1,'u1','L02','g4_1_kor_u1_L02_challenge','lesson_challenge','K4-1-u1-C8',3,'mc','auto','민호의 성격과 역할을 살필 때 민호의 단서로 모아야 할 문장은 무엇인가요?',ARRAY['K4-1-u1-X07']::text[],false,'{"seq":5,"concept":"K4-1-u1-C8","difficulty":3,"kind":"mc","stem":"민호의 성격과 역할을 살필 때 민호의 단서로 모아야 할 문장은 무엇인가요?","options":[{"t":"④ 고개를 숙이고 줄 밖으로 걸어 나갔다","correct":true},{"t":"③ \"민호 너는 빠지는 게 낫겠어.\"","mis":"K4-1-u1-X07"},{"t":"⑤ \"네가 구령을 붙여 주면 어때?\"","mis":"K4-1-u1-X07"},{"t":"⑧ \"네 구령 덕분이야.\"","mis":"K4-1-u1-X07"}],"explanation":["누가 한 말인가요?","민호가 한 행동만","④예요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_challenge#6','kor',4,1,'u1','L02','g4_1_kor_u1_L02_challenge','lesson_challenge','K4-1-u1-C9',3,'mc','auto','수아가 ③처럼 말한 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X10','K4-1-u1-X15']::text[],false,'{"seq":6,"concept":"K4-1-u1-C9","difficulty":3,"kind":"mc","stem":"수아가 ③처럼 말한 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"민호가 줄에 자꾸 걸리는 모습만 보고 판단해서","correct":true},{"t":"민호의 목소리가 너무 커서","mis":"K4-1-u1-X10"},{"t":"은채가 민호를 빼자고 해서","mis":"K4-1-u1-X10"},{"t":"대회가 이미 끝나서","mis":"K4-1-u1-X15"}],"explanation":["②를 봐요.","수아는 무엇만 보았나요?","겉으로 드러난 모습이에요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_challenge#7','kor',4,1,'u1','L02','g4_1_kor_u1_L02_challenge','lesson_challenge','K4-1-u1-C13',3,'mc','auto','⑧에서 수아는 민호에게 어떤 마음이었을까요?',ARRAY['K4-1-u1-X08','K4-1-u1-X03']::text[],false,'{"seq":7,"concept":"K4-1-u1-C13","difficulty":3,"kind":"mc","stem":"⑧에서 수아는 민호에게 어떤 마음이었을까요?","options":[{"t":"고맙고, 아까 한 말이 미안한 마음","correct":true},{"t":"여전히 민호가 못마땅한 마음","mis":"K4-1-u1-X08"},{"t":"대회에서 져서 속상한 마음","mis":"K4-1-u1-X03"},{"t":"아무 생각이 없는 마음","mis":"K4-1-u1-X03"}],"explanation":["대회에서 어떻게 되었나요?","「덕분이야」, 「미안해」","고맙고 미안해요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_challenge#8','kor',4,1,'u1','L02','g4_1_kor_u1_L02_challenge','lesson_challenge','K4-1-u1-C10',4,'essay','teacher','「미술 시간에 생긴 일」에서 하준이와 태오의 관계가 처음과 끝에 어떻게 달라졌는지 쓰고, 그렇게 생각한 문장 번호를 하나씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u1-C10","difficulty":4,"kind":"essay","stem":"「미술 시간에 생긴 일」에서 하준이와 태오의 관계가 처음과 끝에 어떻게 달라졌는지 쓰고, 그렇게 생각한 문장 번호를 하나씩 쓰세요.","answer_guide":{"answer":"예: 처음에는 태오가 하준이를 그림을 못 그린다고 여겨 색칠만 하라고 해서 갈등하는 관계였다(②). 끝에는 하준이가 고른 색을 보고 태오가 「네 눈이 나보다 낫네」라고 해서 서로 인정하는 관계가 되었다(⑧).","scoring_points":["처음의 관계(갈등)를 썼는가","끝의 관계(인정)를 썼는가","처음과 끝의 근거 문장 번호를 썼는가"]},"explanation":["처음 장면","끝 장면","번호도 함께"],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_challenge#9','kor',4,1,'u1','L02','g4_1_kor_u1_L02_challenge','lesson_challenge','K4-1-u1-C12',4,'essay','teacher','「긴 줄넘기 연습」에서 인물들의 관계를 파악하는 방법(장면 떠올리기 → 말과 행동 살피기 → 관계 정리하기)에 따라 은채와 민호의 관계를 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u1-C12","difficulty":4,"kind":"essay","stem":"「긴 줄넘기 연습」에서 인물들의 관계를 파악하는 방법(장면 떠올리기 → 말과 행동 살피기 → 관계 정리하기)에 따라 은채와 민호의 관계를 정리해 쓰세요.","answer_guide":{"answer":"예: 장면 — 민호가 줄 밖으로 나갔을 때 은채가 말을 건넨 장면(⑤). 말과 행동 — 은채는 「네가 구령을 붙여 주면 어때?」 하며 민호가 잘하는 것을 찾아 주었다. 관계 — 은채와 민호는 도와주는 관계이다.","scoring_points":["떠올린 장면을 썼는가","은채의 말이나 행동을 근거로 썼는가","도와주는 관계라고 정리했는가"]},"explanation":["장면 → 말과 행동 → 관계","은채가 한 말","도와주는 관계"],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L02_challenge#10','kor',4,1,'u1','L02','g4_1_kor_u1_L02_challenge','lesson_challenge','K4-1-u1-C8',4,'essay','teacher','하준이가 한 행동 두 가지를 들어 하준이가 어떤 아이인지 쓰고, ②의 말을 하준이의 단서로 쓰면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u1-C8","difficulty":4,"kind":"essay","stem":"하준이가 한 행동 두 가지를 들어 하준이가 어떤 아이인지 쓰고, ②의 말을 하준이의 단서로 쓰면 안 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 하준이는 늘 뒤로 물러서고(①) 아무 말도 못 하고 붓만 만지작거렸다(③). 하지만 색을 맡자 하늘색에 노란색을 섞어 바탕을 칠했다(⑥). 하준이는 자신이 없어 보이지만 색을 고르는 눈이 좋은 아이이다. ②는 태오가 한 말이라서 하준이가 아니라 태오의 생각을 알려 주기 때문이다.","scoring_points":["하준이가 한 행동 두 가지를 썼는가","행동을 근거로 하준이의 성격을 썼는가","②가 태오의 말이라 하준이의 단서가 아닌 까닭을 썼는가"]},"explanation":["하준이가 한 것","어떤 아이인가요?","누가 한 말인가요?"],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_basic#1','kor',4,1,'u1','L03','g4_1_kor_u1_L03_basic','lesson_basic','K4-1-u1-C14',1,'mc','auto','「이야기의 흐름」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X16','K4-1-u1-X01','K4-1-u1-X17']::text[],false,'{"seq":1,"concept":"K4-1-u1-C14","difficulty":1,"kind":"mc","stem":"「이야기의 흐름」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"이야기가 진행되는 과정","correct":true},{"t":"이야기에 나오는 인물들의 이름","mis":"K4-1-u1-X16"},{"t":"이야기를 읽는 데 걸린 시간","mis":"K4-1-u1-X01"},{"t":"이야기에서 가장 재미있는 한 장면","mis":"K4-1-u1-X17"}],"explanation":["흐른다는 것은?","이야기가 나아가는 길이에요.","진행되는 과정이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_basic#2','kor',4,1,'u1','L03','g4_1_kor_u1_L03_basic','lesson_basic','K4-1-u1-C19',1,'mc','auto','「석봉과 어머니」에서 어머니는 석봉을 어떻게 시험했나요?',ARRAY['K4-1-u1-X18']::text[],false,'{"seq":2,"concept":"K4-1-u1-C19","difficulty":1,"kind":"mc","stem":"「석봉과 어머니」에서 어머니는 석봉을 어떻게 시험했나요?","options":[{"t":"호롱불을 끄고 어둠 속에서 글씨를 쓰게 했다","correct":true},{"t":"글씨의 길이를 자로 재어 보았다","mis":"K4-1-u1-X18"},{"t":"마을 사람들에게 글씨를 보여 주었다","mis":"K4-1-u1-X18"},{"t":"스승에게 편지를 보내 물어보았다","mis":"K4-1-u1-X18"}],"explanation":["③을 봐요.","어머니가 먼저 한 일은?","불을 껐어요."],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_basic#3','kor',4,1,'u1','L03','g4_1_kor_u1_L03_basic','lesson_basic','K4-1-u1-C23',1,'mc','auto','「명필」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X20']::text[],false,'{"seq":3,"concept":"K4-1-u1-C23","difficulty":1,"kind":"mc","stem":"「명필」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"글씨를 잘 쓰기로 이름난 사람","correct":true},{"t":"붓을 만드는 사람","mis":"K4-1-u1-X20"},{"t":"이름을 잘 짓는 사람","mis":"K4-1-u1-X20"},{"t":"글을 빨리 읽는 사람","mis":"K4-1-u1-X20"}],"explanation":["석봉이 무엇을 공부했나요?","글씨 공부예요.","글씨를 잘 쓰는 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_basic#4','kor',4,1,'u1','L03','g4_1_kor_u1_L03_basic','lesson_basic','K4-1-u1-C15',1,'mc','auto','일주일 동안 있었던 일을 친구에게 전하려고 해요. 가장 알맞은 방법은 무엇인가요?',ARRAY['K4-1-u1-X12','K4-1-u1-X13','K4-1-u1-X15']::text[],false,'{"seq":4,"concept":"K4-1-u1-C15","difficulty":1,"kind":"mc","stem":"일주일 동안 있었던 일을 친구에게 전하려고 해요. 가장 알맞은 방법은 무엇인가요?","options":[{"t":"중요한 일만 차례대로 전한다","correct":true},{"t":"있었던 일을 하나도 빠짐없이 모두 전한다","mis":"K4-1-u1-X12"},{"t":"한 낱말로 줄여 전한다","mis":"K4-1-u1-X13"},{"t":"생각나는 대로 뒤섞어 전한다","mis":"K4-1-u1-X15"}],"explanation":["다 말하면 헷갈려요.","중요한 일만","차례대로 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_basic#5','kor',4,1,'u1','L03','g4_1_kor_u1_L03_basic','lesson_basic','K4-1-u1-C20',2,'mc','auto','어둠 속에서 어머니에게 일어난 일은 무엇인가요?',ARRAY['K4-1-u1-X16']::text[],false,'{"seq":5,"concept":"K4-1-u1-C20","difficulty":2,"kind":"mc","stem":"어둠 속에서 어머니에게 일어난 일은 무엇인가요?","options":[{"t":"떡을 고르게 썰었다","correct":true},{"t":"글씨를 크기도 모양도 제각각으로 썼다","mis":"K4-1-u1-X16"},{"t":"돌아온 제자를 따뜻하게 맞아 주었다","mis":"K4-1-u1-X16"},{"t":"호롱불을 다시 켜지 못했다","mis":"K4-1-u1-X16"}],"explanation":["누가 무엇을 했나요?","어머니는 떡을 썰었어요.","고르게 썰었어요."],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_basic#6','kor',4,1,'u1','L03','g4_1_kor_u1_L03_basic','lesson_basic','K4-1-u1-C16',2,'mc','auto','「개미와 비둘기」를 가장 잘 정리한 것은 무엇인가요?',ARRAY['K4-1-u1-X13','K4-1-u1-X12','K4-1-u1-X17']::text[],false,'{"seq":6,"concept":"K4-1-u1-C16","difficulty":2,"kind":"mc","stem":"「개미와 비둘기」를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"물에 빠진 개미를 비둘기가 나뭇잎으로 구해 주었고, 얼마 뒤 개미가 사냥꾼의 발을 물어 비둘기를 구해 주었다.","correct":true},{"t":"개미와 비둘기가 서로 도와주었다.","mis":"K4-1-u1-X13"},{"t":"어느 날 개미가 물을 마시러 갔다가 발을 헛디뎠고, 허우적거리는 것을 나무 위의 비둘기가 보고⋯⋯","mis":"K4-1-u1-X12"},{"t":"사냥꾼이 비둘기를 잡으려고 그물을 던졌다.","mis":"K4-1-u1-X17"}],"explanation":["너무 짧아도 안 돼요.","너무 자세해도 안 돼요.","중요한 일을 차례대로"],"asset":{"type":"passage","lines":["① 어느 날, 개미가 물을 마시러 갔다가 발을 헛디뎌 물에 빠졌다.","② 나무 위에 있던 비둘기가 이를 보고 나뭇잎 하나를 떨어뜨려 개미를 구해 주었다.","③ 며칠 뒤, 사냥꾼이 비둘기를 잡으려고 그물을 던졌다.","④ 그 순간 개미가 사냥꾼의 발을 물어 비둘기를 구해 주었다."],"title":"개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_basic#7','kor',4,1,'u1','L03','g4_1_kor_u1_L03_basic','lesson_basic','K4-1-u1-C18',2,'mc','auto','「석봉과 어머니」의 흐름에 꼭 필요한 일은 무엇인가요?',ARRAY['K4-1-u1-X14']::text[],false,'{"seq":7,"concept":"K4-1-u1-C18","difficulty":2,"kind":"mc","stem":"「석봉과 어머니」의 흐름에 꼭 필요한 일은 무엇인가요?","options":[{"t":"어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다","correct":true},{"t":"그날 밤 날씨가 몹시 추웠다","mis":"K4-1-u1-X14"},{"t":"고향집 앞에는 사립문이 있었다","mis":"K4-1-u1-X14"},{"t":"석봉의 붓이 무슨 색이었는지","mis":"K4-1-u1-X14"}],"explanation":["그 일이 빠지면 어떻게 되나요?","이야기가 끊겨요.","④가 꼭 필요해요."],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_basic#8','kor',4,1,'u1','L03','g4_1_kor_u1_L03_basic','lesson_basic','K4-1-u1-C21',2,'mc','auto','「석봉과 어머니」의 일을 일어난 차례대로 놓은 것은 무엇인가요?',ARRAY['K4-1-u1-X15']::text[],false,'{"seq":8,"concept":"K4-1-u1-C21","difficulty":2,"kind":"mc","stem":"「석봉과 어머니」의 일을 일어난 차례대로 놓은 것은 무엇인가요?","options":[{"t":"고향집으로 돌아옴 → 불을 끄고 글씨를 쓰게 함 → 떡은 고르고 글씨는 제각각 → 한양으로 돌아가 공부함","correct":true},{"t":"불을 끄고 글씨를 쓰게 함 → 고향집으로 돌아옴 → 떡은 고르고 글씨는 제각각 → 한양으로 돌아가 공부함","mis":"K4-1-u1-X15"},{"t":"고향집으로 돌아옴 → 한양으로 돌아가 공부함 → 불을 끄고 글씨를 쓰게 함 → 떡은 고르고 글씨는 제각각","mis":"K4-1-u1-X15"},{"t":"떡은 고르고 글씨는 제각각 → 고향집으로 돌아옴 → 불을 끄고 글씨를 쓰게 함 → 한양으로 돌아가 공부함","mis":"K4-1-u1-X15"}],"explanation":["무엇이 먼저였나요?","돌아와야 시험을 봐요.","①부터 차례대로"],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_basic#9','kor',4,1,'u1','L03','g4_1_kor_u1_L03_basic','lesson_basic','K4-1-u1-C17',2,'mc','auto','이야기의 흐름을 정리하는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X17','K4-1-u1-X12','K4-1-u1-X13']::text[],false,'{"seq":9,"concept":"K4-1-u1-C17","difficulty":2,"kind":"mc","stem":"이야기의 흐름을 정리하는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"인물에게 일어난 중요한 일을 시간과 장소의 변화에 따라 정리한다","correct":true},{"t":"내가 가장 좋아하는 장면부터 정리한다","mis":"K4-1-u1-X17"},{"t":"있었던 일을 문장마다 빠짐없이 옮긴다","mis":"K4-1-u1-X12"},{"t":"가장 짧은 한 문장으로만 줄인다","mis":"K4-1-u1-X13"}],"explanation":["누구에게 일어난 일?","언제 · 어디가 바뀌었나요?","중요한 일을 차례대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_basic#10','kor',4,1,'u1','L03','g4_1_kor_u1_L03_basic','lesson_basic','K4-1-u1-C24',3,'mc','auto','「석봉과 어머니」에서 석봉의 마음은 어떻게 바뀌었나요?',ARRAY['K4-1-u1-X19']::text[],false,'{"seq":10,"concept":"K4-1-u1-C24","difficulty":3,"kind":"mc","stem":"「석봉과 어머니」에서 석봉의 마음은 어떻게 바뀌었나요?","options":[{"t":"명필이 되었다고 자만했다가 떡과 글씨를 견주어 보고 부끄러워졌다","correct":true},{"t":"처음부터 끝까지 자기 글씨를 자랑스러워했다","mis":"K4-1-u1-X19"},{"t":"어머니가 반가워하지 않아 화가 나서 한양으로 가 버렸다","mis":"K4-1-u1-X19"},{"t":"떡이 먹고 싶어 고향에 더 머물고 싶어졌다","mis":"K4-1-u1-X19"}],"explanation":["②에서 석봉은?","⑤에서 무엇을 보았나요?","⑦에서 부끄러워했어요."],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_challenge#1','kor',4,1,'u1','L03','g4_1_kor_u1_L03_challenge','lesson_challenge','K4-1-u1-C22',2,'mc','auto','이야기의 흐름을 파악하는 방법을 바르게 모은 것은 무엇인가요?',ARRAY['K4-1-u1-X12','K4-1-u1-X17','K4-1-u1-X13']::text[],false,'{"seq":1,"concept":"K4-1-u1-C22","difficulty":2,"kind":"mc","stem":"이야기의 흐름을 파악하는 방법을 바르게 모은 것은 무엇인가요?","options":[{"t":"인물·장소·일어난 일 찾기 / 시간과 장소의 변화 살피기 / 차례 정리하기","correct":true},{"t":"있었던 일 모두 적기 / 차례 정리하기 / 가장 짧게 줄이기","mis":"K4-1-u1-X12"},{"t":"좋아하는 장면 고르기 / 인물 그리기 / 차례 정리하기","mis":"K4-1-u1-X17"},{"t":"인물과 장소 찾기 / 한 문장으로 줄이기 / 끝 장면만 보기","mis":"K4-1-u1-X13"}],"explanation":["세 가지 방법이에요.","찾기 · 살피기 · 정리하기","다 적거나 줄이기는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_challenge#2','kor',4,1,'u1','L03','g4_1_kor_u1_L03_challenge','lesson_challenge','K4-1-u1-C23',2,'sa','auto','「석봉은 3년 동안 글씨 공부를 하고 ( ㉠ )이 되어 돌아왔다고 했다.」에서 ㉠은 글씨를 잘 쓰기로 이름난 사람이라는 뜻이에요. 알맞은 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K4-1-u1-C23","difficulty":2,"kind":"sa","stem":"「석봉은 3년 동안 글씨 공부를 하고 ( ㉠ )이 되어 돌아왔다고 했다.」에서 ㉠은 글씨를 잘 쓰기로 이름난 사람이라는 뜻이에요. 알맞은 낱말을 쓰세요.","answer":["명필"],"explanation":["②를 다시 봐요.","글씨를 잘 쓰는 사람","명필이에요."],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"},"mis":"K4-1-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_challenge#3','kor',4,1,'u1','L03','g4_1_kor_u1_L03_challenge','lesson_challenge','K4-1-u1-C18',3,'mc','auto','「돌다리를 놓은 아이」의 흐름에 꼭 필요한 일은 무엇인가요?',ARRAY['K4-1-u1-X14']::text[],false,'{"seq":3,"concept":"K4-1-u1-C18","difficulty":3,"kind":"mc","stem":"「돌다리를 놓은 아이」의 흐름에 꼭 필요한 일은 무엇인가요?","options":[{"t":"③ 동이는 날마다 개울에서 넓적한 돌을 하나씩 날라 놓았어요.","correct":true},{"t":"⑤ 동이네 집 마당에는 감나무가 한 그루 서 있었어요.","mis":"K4-1-u1-X14"},{"t":"동이가 돌을 나를 때 입은 옷의 색깔","mis":"K4-1-u1-X14"},{"t":"장터에서 파는 물건의 이름","mis":"K4-1-u1-X14"}],"explanation":["빠지면 다리가 어떻게 생기나요?","돌을 날랐기 때문에","③이 꼭 필요해요."],"asset":{"type":"passage","lines":["① 옛날 어느 산골 마을 사람들은 개울을 건너야 장터에 갈 수 있었어요.","② 비가 오면 개울물이 불어 사람들은 며칠씩 장에 가지 못했어요.","③ 동이는 날마다 개울에서 넓적한 돌을 하나씩 날라 놓았어요.","④ \"그걸로 언제 다리를 만드니?\" 마을 사람들은 웃었어요.","⑤ 동이네 집 마당에는 감나무가 한 그루 서 있었어요.","⑥ 여름이 가고 겨울이 오도록 동이는 돌 나르기를 멈추지 않았어요.","⑦ 이듬해 봄, 개울에 튼튼한 돌다리가 놓였어요.","⑧ 그 뒤로는 비가 와도 마을 사람들이 장에 갈 수 있었어요."],"title":"돌다리를 놓은 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_challenge#4','kor',4,1,'u1','L03','g4_1_kor_u1_L03_challenge','lesson_challenge','K4-1-u1-C16',3,'mc','auto','「돌다리를 놓은 아이」를 가장 잘 정리한 것은 무엇인가요?',ARRAY['K4-1-u1-X13','K4-1-u1-X12','K4-1-u1-X17']::text[],false,'{"seq":4,"concept":"K4-1-u1-C16","difficulty":3,"kind":"mc","stem":"「돌다리를 놓은 아이」를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"비가 오면 장에 못 가던 마을에서 동이가 날마다 돌을 날라, 이듬해 봄 돌다리가 놓였다.","correct":true},{"t":"동이가 다리를 놓았다.","mis":"K4-1-u1-X13"},{"t":"옛날 어느 산골 마을에 개울이 있었고, 비가 오면 물이 불었고, 동이네 마당에는 감나무가 있었고⋯⋯","mis":"K4-1-u1-X12"},{"t":"마을 사람들이 동이를 보고 웃었다.","mis":"K4-1-u1-X17"}],"explanation":["너무 짧지 않게","너무 자세하지 않게","중요한 일을 차례대로"],"asset":{"type":"passage","lines":["① 옛날 어느 산골 마을 사람들은 개울을 건너야 장터에 갈 수 있었어요.","② 비가 오면 개울물이 불어 사람들은 며칠씩 장에 가지 못했어요.","③ 동이는 날마다 개울에서 넓적한 돌을 하나씩 날라 놓았어요.","④ \"그걸로 언제 다리를 만드니?\" 마을 사람들은 웃었어요.","⑤ 동이네 집 마당에는 감나무가 한 그루 서 있었어요.","⑥ 여름이 가고 겨울이 오도록 동이는 돌 나르기를 멈추지 않았어요.","⑦ 이듬해 봄, 개울에 튼튼한 돌다리가 놓였어요.","⑧ 그 뒤로는 비가 와도 마을 사람들이 장에 갈 수 있었어요."],"title":"돌다리를 놓은 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_challenge#5','kor',4,1,'u1','L03','g4_1_kor_u1_L03_challenge','lesson_challenge','K4-1-u1-C17',3,'mc','auto','「돌다리를 놓은 아이」에서 시간의 변화를 알려 주는 말을 바르게 모은 것은 무엇인가요?',ARRAY['K4-1-u1-X17']::text[],false,'{"seq":5,"concept":"K4-1-u1-C17","difficulty":3,"kind":"mc","stem":"「돌다리를 놓은 아이」에서 시간의 변화를 알려 주는 말을 바르게 모은 것은 무엇인가요?","options":[{"t":"날마다 · 여름이 가고 겨울이 오도록 · 이듬해 봄","correct":true},{"t":"개울 · 장터 · 마당","mis":"K4-1-u1-X17"},{"t":"넓적한 · 튼튼한 · 한 그루","mis":"K4-1-u1-X17"},{"t":"웃었어요 · 놓였어요 · 갈 수 있었어요","mis":"K4-1-u1-X17"}],"explanation":["「언제」를 알려 주는 말","개울·장터는 장소예요.","시간이 흘렀어요."],"asset":{"type":"passage","lines":["① 옛날 어느 산골 마을 사람들은 개울을 건너야 장터에 갈 수 있었어요.","② 비가 오면 개울물이 불어 사람들은 며칠씩 장에 가지 못했어요.","③ 동이는 날마다 개울에서 넓적한 돌을 하나씩 날라 놓았어요.","④ \"그걸로 언제 다리를 만드니?\" 마을 사람들은 웃었어요.","⑤ 동이네 집 마당에는 감나무가 한 그루 서 있었어요.","⑥ 여름이 가고 겨울이 오도록 동이는 돌 나르기를 멈추지 않았어요.","⑦ 이듬해 봄, 개울에 튼튼한 돌다리가 놓였어요.","⑧ 그 뒤로는 비가 와도 마을 사람들이 장에 갈 수 있었어요."],"title":"돌다리를 놓은 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_challenge#6','kor',4,1,'u1','L03','g4_1_kor_u1_L03_challenge','lesson_challenge','K4-1-u1-C21',3,'mc','auto','「돌다리를 놓은 아이」의 일을 일어난 차례대로 놓은 것은 무엇인가요?',ARRAY['K4-1-u1-X15','K4-1-u1-X14']::text[],false,'{"seq":6,"concept":"K4-1-u1-C21","difficulty":3,"kind":"mc","stem":"「돌다리를 놓은 아이」의 일을 일어난 차례대로 놓은 것은 무엇인가요?","options":[{"t":"비가 오면 장에 못 감 → 동이가 날마다 돌을 나름 → 사람들이 웃음 → 돌다리가 놓임","correct":true},{"t":"동이가 날마다 돌을 나름 → 비가 오면 장에 못 감 → 돌다리가 놓임 → 사람들이 웃음","mis":"K4-1-u1-X15"},{"t":"비가 오면 장에 못 감 → 돌다리가 놓임 → 동이가 날마다 돌을 나름 → 사람들이 웃음","mis":"K4-1-u1-X15"},{"t":"비가 오면 장에 못 감 → 마당에 감나무가 있음 → 동이가 날마다 돌을 나름 → 돌다리가 놓임","mis":"K4-1-u1-X14"}],"explanation":["까닭이 먼저 와요.","나르고 나서 다리가 놓여요.","감나무는 필요 없어요."],"asset":{"type":"passage","lines":["① 옛날 어느 산골 마을 사람들은 개울을 건너야 장터에 갈 수 있었어요.","② 비가 오면 개울물이 불어 사람들은 며칠씩 장에 가지 못했어요.","③ 동이는 날마다 개울에서 넓적한 돌을 하나씩 날라 놓았어요.","④ \"그걸로 언제 다리를 만드니?\" 마을 사람들은 웃었어요.","⑤ 동이네 집 마당에는 감나무가 한 그루 서 있었어요.","⑥ 여름이 가고 겨울이 오도록 동이는 돌 나르기를 멈추지 않았어요.","⑦ 이듬해 봄, 개울에 튼튼한 돌다리가 놓였어요.","⑧ 그 뒤로는 비가 와도 마을 사람들이 장에 갈 수 있었어요."],"title":"돌다리를 놓은 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_challenge#7','kor',4,1,'u1','L03','g4_1_kor_u1_L03_challenge','lesson_challenge','K4-1-u1-C20',3,'mc','auto','「개미와 비둘기」에서 인물과 그 인물에게 일어난 일을 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-1-u1-X16']::text[],false,'{"seq":7,"concept":"K4-1-u1-C20","difficulty":3,"kind":"mc","stem":"「개미와 비둘기」에서 인물과 그 인물에게 일어난 일을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"비둘기 — 나뭇잎을 떨어뜨려 개미를 구했다","correct":true},{"t":"개미 — 나뭇잎을 떨어뜨려 비둘기를 구했다","mis":"K4-1-u1-X16"},{"t":"사냥꾼 — 물에 빠진 개미를 건져 주었다","mis":"K4-1-u1-X16"},{"t":"비둘기 — 사냥꾼의 발을 물었다","mis":"K4-1-u1-X16"}],"explanation":["누가 무엇을 했나요?","②를 봐요.","비둘기가 나뭇잎을"],"asset":{"type":"passage","lines":["① 어느 날, 개미가 물을 마시러 갔다가 발을 헛디뎌 물에 빠졌다.","② 나무 위에 있던 비둘기가 이를 보고 나뭇잎 하나를 떨어뜨려 개미를 구해 주었다.","③ 며칠 뒤, 사냥꾼이 비둘기를 잡으려고 그물을 던졌다.","④ 그 순간 개미가 사냥꾼의 발을 물어 비둘기를 구해 주었다."],"title":"개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_challenge#8','kor',4,1,'u1','L03','g4_1_kor_u1_L03_challenge','lesson_challenge','K4-1-u1-C16',4,'essay','teacher','「돌다리를 놓은 아이」의 흐름을 중요한 일만 차례대로 두세 문장으로 정리하고, ⑤를 넣지 않은 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u1-C16","difficulty":4,"kind":"essay","stem":"「돌다리를 놓은 아이」의 흐름을 중요한 일만 차례대로 두세 문장으로 정리하고, ⑤를 넣지 않은 까닭을 쓰세요.","answer_guide":{"answer":"예: 비가 오면 개울물이 불어 마을 사람들은 장에 가지 못했다. 동이는 사람들이 웃어도 날마다 돌을 날라 놓았다. 이듬해 봄 돌다리가 놓여 비가 와도 장에 갈 수 있게 되었다. ⑤는 빠져도 이야기가 이어지는 일이라서 넣지 않았다.","scoring_points":["중요한 일만 골라 썼는가","일이 일어난 차례대로 썼는가","⑤가 빠져도 이야기가 이어진다는 까닭을 썼는가"]},"explanation":["중요한 일만","차례대로","빠져도 이어지나요?"],"asset":{"type":"passage","lines":["① 옛날 어느 산골 마을 사람들은 개울을 건너야 장터에 갈 수 있었어요.","② 비가 오면 개울물이 불어 사람들은 며칠씩 장에 가지 못했어요.","③ 동이는 날마다 개울에서 넓적한 돌을 하나씩 날라 놓았어요.","④ \"그걸로 언제 다리를 만드니?\" 마을 사람들은 웃었어요.","⑤ 동이네 집 마당에는 감나무가 한 그루 서 있었어요.","⑥ 여름이 가고 겨울이 오도록 동이는 돌 나르기를 멈추지 않았어요.","⑦ 이듬해 봄, 개울에 튼튼한 돌다리가 놓였어요.","⑧ 그 뒤로는 비가 와도 마을 사람들이 장에 갈 수 있었어요."],"title":"돌다리를 놓은 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_challenge#9','kor',4,1,'u1','L03','g4_1_kor_u1_L03_challenge','lesson_challenge','K4-1-u1-C24',4,'essay','teacher','석봉의 마음이 자만에서 부끄러움으로 바뀐 까닭을 일어난 일을 들어 쓰고, 마음이 바뀐 뒤 석봉이 한 일을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u1-C24","difficulty":4,"kind":"essay","stem":"석봉의 마음이 자만에서 부끄러움으로 바뀐 까닭을 일어난 일을 들어 쓰고, 마음이 바뀐 뒤 석봉이 한 일을 쓰세요.","answer_guide":{"answer":"예: 석봉은 명필이 되었다고 자만했지만, 어둠 속에서 어머니가 썬 떡은 고른데 자기 글씨는 크기도 모양도 제각각인 것을 보고 아직 모자라다는 것을 알았다. 그래서 부끄러워하며 한양으로 돌아가 다시 공부에 힘썼다.","scoring_points":["처음의 마음(자만)을 썼는가","마음이 바뀐 까닭(떡과 글씨를 견줌)을 썼는가","바뀐 뒤 한 일을 썼는가"]},"explanation":["②의 석봉","⑤에서 본 것","⑦에서 한 일"],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L03_challenge#10','kor',4,1,'u1','L03','g4_1_kor_u1_L03_challenge','lesson_challenge','K4-1-u1-C15',4,'essay','teacher','어제 학교에서 있었던 일을 친구에게 전한다고 생각하고, 중요한 일만 골라 차례대로 두세 문장으로 쓰세요. 그리고 있었던 일을 빠짐없이 다 말하면 안 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u1-C15","difficulty":4,"kind":"essay","stem":"어제 학교에서 있었던 일을 친구에게 전한다고 생각하고, 중요한 일만 골라 차례대로 두세 문장으로 쓰세요. 그리고 있었던 일을 빠짐없이 다 말하면 안 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 어제 체육 시간에 우리 반이 피구를 했다. 처음에는 우리 편이 지고 있었는데 마지막에 서윤이가 공을 잡아서 이겼다. 있었던 일을 빠짐없이 다 말하면 듣는 사람이 무엇이 중요한지 몰라 오히려 헷갈리기 때문이다.","scoring_points":["중요한 일만 골라 썼는가","일이 일어난 차례대로 썼는가","빠짐없이 다 말하면 헷갈린다는 까닭을 썼는가"]},"explanation":["무엇이 중요했나요?","먼저 · 나중","다 말하면 헷갈려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_basic#1','kor',4,1,'u1','L05','g4_1_kor_u1_L05_basic','lesson_basic','K4-1-u1-C26',1,'mc','auto','무루는 굴이 무너지는 것을 어떻게 먼저 알아챘나요?',ARRAY['K4-1-u1-X10']::text[],false,'{"seq":1,"concept":"K4-1-u1-C26","difficulty":1,"kind":"mc","stem":"무루는 굴이 무너지는 것을 어떻게 먼저 알아챘나요?","options":[{"t":"앞발 끝으로 흙이 잘게 떨리는 것을 느껴서","correct":true},{"t":"굴 입구에서 바깥을 내다보아서","mis":"K4-1-u1-X10"},{"t":"다른 두더지가 알려 주어서","mis":"K4-1-u1-X10"},{"t":"굴이 무너지는 것을 눈으로 똑똑히 보아서","mis":"K4-1-u1-X10"}],"explanation":["무루는 눈이 어두워요.","⑤를 봐요.","앞발 끝으로 느꼈어요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_basic#2','kor',4,1,'u1','L05','g4_1_kor_u1_L05_basic','lesson_basic','K4-1-u1-C27',1,'mc','auto','⑥의 「하늘이 노래지도록」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X21','K4-1-u1-X22']::text[],false,'{"seq":2,"concept":"K4-1-u1-C27","difficulty":1,"kind":"mc","stem":"⑥의 「하늘이 노래지도록」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"큰 충격으로 정신이 아찔하도록","correct":true},{"t":"하늘 빛깔이 노랗게 바뀌도록","mis":"K4-1-u1-X21"},{"t":"조심성 없이 가볍고 야단스럽게","mis":"K4-1-u1-X22"},{"t":"슬픔 때문에 큰 고통을 받아","mis":"K4-1-u1-X22"}],"explanation":["하늘 색 이야기일까요?","굴이 무너지는 순간이에요.","정신이 아찔해요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_basic#3','kor',4,1,'u1','L05','g4_1_kor_u1_L05_basic','lesson_basic','K4-1-u1-C29',1,'mc','auto','「눈이 어두운 두더지 무루」에서 갈등하는 관계가 드러난 장면은 무엇인가요?',ARRAY['K4-1-u1-X23']::text[],false,'{"seq":3,"concept":"K4-1-u1-C29","difficulty":1,"kind":"mc","stem":"「눈이 어두운 두더지 무루」에서 갈등하는 관계가 드러난 장면은 무엇인가요?","options":[{"t":"③ \"넌 앞도 못 보잖아. 저리 가!\"","correct":true},{"t":"④ 마루가 굴 파는 법을 알려 주었다","mis":"K4-1-u1-X23"},{"t":"⑦ 무루가 모두를 언덕 위로 이끌었다","mis":"K4-1-u1-X23"},{"t":"⑧ 서로 다른 재주를 귀하게 여겼다","mis":"K4-1-u1-X23"}],"explanation":["밀어내는 장면을 찾아요.","돕는 장면은 빼요.","③이에요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_basic#4','kor',4,1,'u1','L05','g4_1_kor_u1_L05_basic','lesson_basic','K4-1-u1-C31',1,'mc','auto','「눈이 어두운 두더지 무루」에서 글쓴이가 전하고 싶은 생각은 무엇인가요?',ARRAY['K4-1-u1-X25','K4-1-u1-X26']::text[],false,'{"seq":4,"concept":"K4-1-u1-C31","difficulty":1,"kind":"mc","stem":"「눈이 어두운 두더지 무루」에서 글쓴이가 전하고 싶은 생각은 무엇인가요?","options":[{"t":"겉모습으로 판단하지 말고 서로 존중하자","correct":true},{"t":"누구보다 빠르게 움직여야 한다","mis":"K4-1-u1-X25"},{"t":"비 오는 날에는 굴 밖으로 나가면 안 된다","mis":"K4-1-u1-X25"},{"t":"눈이 어두우면 아무것도 할 수 없다","mis":"K4-1-u1-X26"}],"explanation":["무루의 다른 점이 어떤 힘이 되었나요?","마을을 구했어요.","다른 것은 틀린 것이 아니에요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_basic#5','kor',4,1,'u1','L05','g4_1_kor_u1_L05_basic','lesson_basic','K4-1-u1-C28',2,'match','auto','인물과 성격·역할을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-1-u1-C28","difficulty":2,"kind":"match","stem":"인물과 성격·역할을 알맞게 이으세요.","pairs":[{"l":"무루","r":"포기하지 않음 · 마을을 구함"},{"l":"마루","r":"따뜻하고 한결같음 · 무루를 보살핌"},{"l":"또래 두더지들","r":"겉만 보고 판단함 · 무루를 힘들게 함"}],"mis":"K4-1-u1-X24","explanation":["누구에게 무엇을 했나요?","말과 행동을 떠올려요.","역할이 달라요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_basic#6','kor',4,1,'u1','L05','g4_1_kor_u1_L05_basic','lesson_basic','K4-1-u1-C27',2,'match','auto','마음을 나타내는 표현과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K4-1-u1-C27","difficulty":2,"kind":"match","stem":"마음을 나타내는 표현과 뜻을 알맞게 이으세요.","pairs":[{"l":"호들갑을 떨다","r":"가볍고 야단스럽게 굴다"},{"l":"가슴이 찢어질 듯","r":"슬픔 때문에 큰 고통을 받다"},{"l":"하늘이 노래지도록","r":"큰 충격으로 정신이 아찔하게"}],"mis":"K4-1-u1-X22","explanation":["그 말이 나온 문장을 봐요.","어떤 느낌인가요?","앞뒤가 뜻을 알려 줘요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_basic#7','kor',4,1,'u1','L05','g4_1_kor_u1_L05_basic','lesson_basic','K4-1-u1-C25',2,'mc','auto','인물들의 관계를 중심으로 흐름을 파악할 때 흐름의 마디가 되는 곳은 어디인가요?',ARRAY['K4-1-u1-X08','K4-1-u1-X17']::text[],false,'{"seq":7,"concept":"K4-1-u1-C25","difficulty":2,"kind":"mc","stem":"인물들의 관계를 중심으로 흐름을 파악할 때 흐름의 마디가 되는 곳은 어디인가요?","options":[{"t":"인물들의 관계가 바뀌는 곳","correct":true},{"t":"관계는 바뀌지 않으니 처음 장면만 보면 된다","mis":"K4-1-u1-X08"},{"t":"가장 긴 문장이 나오는 곳","mis":"K4-1-u1-X17"},{"t":"문단이 끝나는 곳마다","mis":"K4-1-u1-X17"}],"explanation":["관계를 따라가요.","어디서 달라졌나요?","바뀌는 곳이 마디예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_basic#8','kor',4,1,'u1','L05','g4_1_kor_u1_L05_basic','lesson_basic','K4-1-u1-C30',2,'blank','auto','관계를 중심으로 흐름을 정리했어요. 「두더지들이 무루를 따돌림 → 마루가 굴 파는 법을 알려 줌 → 큰비가 온 밤 → (   )」의 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X27','K4-1-u1-X16','K4-1-u1-X10']::text[],false,'{"seq":8,"concept":"K4-1-u1-C30","difficulty":2,"kind":"blank","stem":"관계를 중심으로 흐름을 정리했어요. 「두더지들이 무루를 따돌림 → 마루가 굴 파는 법을 알려 줌 → 큰비가 온 밤 → (   )」의 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"무루가 앞장서서 모두를 구함","correct":true},{"t":"두더지들이 계속 무루를 밀어냄","mis":"K4-1-u1-X27"},{"t":"마루가 무루 대신 모두를 구함","mis":"K4-1-u1-X16"},{"t":"무루의 눈이 갑자기 밝아짐","mis":"K4-1-u1-X10"}],"explanation":["⑦을 봐요.","관계가 바뀌었어요.","무루가 모두를 구했어요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_basic#9','kor',4,1,'u1','L05','g4_1_kor_u1_L05_basic','lesson_basic','K4-1-u1-C28',2,'mc','auto','마루의 성격이 드러난 행동은 무엇인가요?',ARRAY['K4-1-u1-X24','K4-1-u1-X06']::text[],false,'{"seq":9,"concept":"K4-1-u1-C28","difficulty":2,"kind":"mc","stem":"마루의 성격이 드러난 행동은 무엇인가요?","options":[{"t":"가슴이 아팠지만 무루에게 굴 파는 법을 알려 주었다","correct":true},{"t":"무루에게 「저리 가!」 하며 밀어냈다","mis":"K4-1-u1-X24"},{"t":"굴 입구에서 바깥만 내다보았다","mis":"K4-1-u1-X24"},{"t":"엄마이니까 따뜻할 것이라고 짐작했다","mis":"K4-1-u1-X06"}],"explanation":["마루가 한 행동이에요.","④를 봐요.","한결같이 보살폈어요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_basic#10','kor',4,1,'u1','L05','g4_1_kor_u1_L05_basic','lesson_basic','K4-1-u1-C31',3,'ox','auto','무루는 다른 두더지들과 달라서 틀린 두더지예요.',ARRAY['K4-1-u1-X26']::text[],false,'{"seq":10,"concept":"K4-1-u1-C31","difficulty":3,"kind":"ox","stem":"무루는 다른 두더지들과 달라서 틀린 두더지예요.","answer":"X","reason_options":[{"t":"앞발로 흙의 떨림을 느끼는 재주로 마을을 구했기 때문에","correct":true},{"t":"눈이 어두운 것은 모자란 것이기 때문에","mis":"K4-1-u1-X26"}],"mis":"K4-1-u1-X26","explanation":["무루가 무엇을 했나요?","다른 재주가 있었어요.","다른 것은 틀린 것이 아니에요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_challenge#1','kor',4,1,'u1','L05','g4_1_kor_u1_L05_challenge','lesson_challenge','K4-1-u1-C32',2,'mc','auto','「눈이 어두운 두더지 무루」를 읽고 이야기 속 관계를 내 생활과 이어 보려고 해요. 알맞은 생각은 무엇인가요?',ARRAY['K4-1-u1-X28','K4-1-u1-X34','K4-1-u1-X06']::text[],false,'{"seq":1,"concept":"K4-1-u1-C32","difficulty":2,"kind":"mc","stem":"「눈이 어두운 두더지 무루」를 읽고 이야기 속 관계를 내 생활과 이어 보려고 해요. 알맞은 생각은 무엇인가요?","options":[{"t":"마루처럼 나를 믿어 준 사람은 누구였는지 떠올려 본다","correct":true},{"t":"이야기는 꾸며 낸 것이니 내 생활과 견줄 필요가 없다","mis":"K4-1-u1-X28"},{"t":"두더지가 사는 굴이 모두 몇 개인지 세어 본다","mis":"K4-1-u1-X34"},{"t":"친구 가운데 두더지를 닮은 사람을 찾아본다","mis":"K4-1-u1-X06"}],"explanation":["이야기 속 관계를","내 주변에서 찾아봐요.","나를 믿어 준 사람"],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_challenge#2','kor',4,1,'u1','L05','g4_1_kor_u1_L05_challenge','lesson_challenge','K4-1-u1-C26',2,'mc','auto','무루가 앞장서서 모두를 언덕 위로 이끌 수 있었던 까닭은 무엇인가요?',ARRAY['K4-1-u1-X10']::text[],false,'{"seq":2,"concept":"K4-1-u1-C26","difficulty":2,"kind":"mc","stem":"무루가 앞장서서 모두를 언덕 위로 이끌 수 있었던 까닭은 무엇인가요?","options":[{"t":"앞이 보이지 않는 굴길에서도 흙의 떨림을 따라갈 수 있어서","correct":true},{"t":"다른 두더지들보다 힘이 세서","mis":"K4-1-u1-X10"},{"t":"마루가 굴 밖에서 길을 알려 주어서","mis":"K4-1-u1-X10"},{"t":"비가 그쳐 굴길이 밝아져서","mis":"K4-1-u1-X10"}],"explanation":["다른 두더지들은 왜 못 걸었나요?","앞이 보이지 않았어요.","무루는 떨림을 따라갔어요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_challenge#3','kor',4,1,'u1','L05','g4_1_kor_u1_L05_challenge','lesson_challenge','K4-1-u1-C25',3,'mc','auto','「긴 줄넘기 연습」에서 민호와 수아의 관계가 바뀌는 마디는 어디인가요?',ARRAY['K4-1-u1-X27']::text[],false,'{"seq":3,"concept":"K4-1-u1-C25","difficulty":3,"kind":"mc","stem":"「긴 줄넘기 연습」에서 민호와 수아의 관계가 바뀌는 마디는 어디인가요?","options":[{"t":"⑥ 민호가 구령을 붙이자 모두의 발이 맞았다","correct":true},{"t":"① 우리 반이 날마다 연습했다","mis":"K4-1-u1-X27"},{"t":"② 민호가 줄에 자꾸 걸렸다","mis":"K4-1-u1-X27"},{"t":"④ 민호가 줄 밖으로 걸어 나갔다","mis":"K4-1-u1-X27"}],"explanation":["수아의 마음이 언제 달라졌나요?","구령 덕분이라고 했어요.","⑥이 마디예요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_challenge#4','kor',4,1,'u1','L05','g4_1_kor_u1_L05_challenge','lesson_challenge','K4-1-u1-C30',3,'mc','auto','「긴 줄넘기 연습」의 흐름을 관계를 중심으로 바르게 정리한 것은 무엇인가요?',ARRAY['K4-1-u1-X27','K4-1-u1-X16','K4-1-u1-X15']::text[],false,'{"seq":4,"concept":"K4-1-u1-C30","difficulty":3,"kind":"mc","stem":"「긴 줄넘기 연습」의 흐름을 관계를 중심으로 바르게 정리한 것은 무엇인가요?","options":[{"t":"수아가 민호를 빼려 함 → 은채가 구령을 맡기자고 함 → 구령으로 발이 맞음 → 수아가 민호를 인정함","correct":true},{"t":"수아가 민호를 빼려 함 → 대회 날 끝까지 걸리지 않음","mis":"K4-1-u1-X27"},{"t":"민호가 줄에 걸림 → 민호가 줄 밖으로 나감 → 민호가 집으로 돌아감","mis":"K4-1-u1-X16"},{"t":"은채가 구령을 맡기자고 함 → 수아가 민호를 빼려 함 → 수아가 민호를 인정함 → 구령으로 발이 맞음","mis":"K4-1-u1-X15"}],"explanation":["관계가 바뀐 마디를 넣어요.","차례도 지켜요.","갈등 → 도움 → 인정"],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_challenge#5','kor',4,1,'u1','L05','g4_1_kor_u1_L05_challenge','lesson_challenge','K4-1-u1-C31',3,'mc','auto','「눈이 어두운 두더지 무루」와 「긴 줄넘기 연습」에 함께 담긴 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X25','K4-1-u1-X26']::text[],false,'{"seq":5,"concept":"K4-1-u1-C31","difficulty":3,"kind":"mc","stem":"「눈이 어두운 두더지 무루」와 「긴 줄넘기 연습」에 함께 담긴 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"잘하지 못하는 한 가지만 보고 그 사람을 판단하지 말자","correct":true},{"t":"줄넘기는 날마다 연습해야 한다","mis":"K4-1-u1-X25"},{"t":"목소리가 큰 사람이 언제나 이긴다","mis":"K4-1-u1-X25"},{"t":"남과 다르면 빠지는 것이 낫다","mis":"K4-1-u1-X26"}],"explanation":["무루와 민호의 같은 점","둘 다 다른 재주가 있었어요.","겉만 보고 판단하지 않아요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_challenge#6','kor',4,1,'u1','L05','g4_1_kor_u1_L05_challenge','lesson_challenge','K4-1-u1-C27',3,'mc','auto','②의 「호들갑을 떨었다」에서 마을 두더지들은 어떤 모습이었나요?',ARRAY['K4-1-u1-X22','K4-1-u1-X21']::text[],false,'{"seq":6,"concept":"K4-1-u1-C27","difficulty":3,"kind":"mc","stem":"②의 「호들갑을 떨었다」에서 마을 두더지들은 어떤 모습이었나요?","options":[{"t":"무루를 두고 가볍고 야단스럽게 걱정했다","correct":true},{"t":"무루를 조용히 지켜보기만 했다","mis":"K4-1-u1-X22"},{"t":"무루가 걱정되어 몹시 괴로워했다","mis":"K4-1-u1-X22"},{"t":"몸에 붙은 흙을 털어 냈다","mis":"K4-1-u1-X21"}],"explanation":["무엇을 말했나요?","「저래서야⋯⋯」","야단스럽게 굴었어요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_challenge#7','kor',4,1,'u1','L05','g4_1_kor_u1_L05_challenge','lesson_challenge','K4-1-u1-C29',3,'mc','auto','「긴 줄넘기 연습」에서 갈등하는 관계가 드러난 장면은 무엇인가요?',ARRAY['K4-1-u1-X23']::text[],false,'{"seq":7,"concept":"K4-1-u1-C29","difficulty":3,"kind":"mc","stem":"「긴 줄넘기 연습」에서 갈등하는 관계가 드러난 장면은 무엇인가요?","options":[{"t":"③ \"민호 너는 빠지는 게 낫겠어.\"","correct":true},{"t":"⑤ 은채가 구령을 붙이자고 했다","mis":"K4-1-u1-X23"},{"t":"⑧ \"네 구령 덕분이야.\"","mis":"K4-1-u1-X23"},{"t":"⑥ 모두의 발이 착착 맞았다","mis":"K4-1-u1-X23"}],"explanation":["밀어내는 말을 찾아요.","돕거나 인정하는 장면은 빼요.","③이에요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_challenge#8','kor',4,1,'u1','L05','g4_1_kor_u1_L05_challenge','lesson_challenge','K4-1-u1-C30',4,'essay','teacher','「눈이 어두운 두더지 무루」의 흐름을 인물들의 관계를 중심으로 네 마디로 정리하세요. 마디마다 누구와 누구의 관계인지 밝혀 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u1-C30","difficulty":4,"kind":"essay","stem":"「눈이 어두운 두더지 무루」의 흐름을 인물들의 관계를 중심으로 네 마디로 정리하세요. 마디마다 누구와 누구의 관계인지 밝혀 쓰세요.","answer_guide":{"answer":"예: ① 또래 두더지들과 무루 — 눈이 어둡다고 무루를 밀어냈다(갈등). ② 마루와 무루 — 마루가 굴 파는 법을 하나하나 알려 주었다(도와줌). ③ 큰비가 온 밤 — 두더지들은 굴이 무너지는 것을 알지 못했다. ④ 무루와 두더지들 — 무루가 앞장서서 모두를 구해 서로 다른 재주를 귀하게 여기게 되었다.","scoring_points":["네 마디를 일어난 차례대로 썼는가","마디마다 누구와 누구의 관계인지 밝혔는가","관계가 바뀐 마디(무루가 모두를 구함)를 넣었는가"]},"explanation":["누구와 누구?","어디서 바뀌었나요?","차례대로 네 마디"],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_challenge#9','kor',4,1,'u1','L05','g4_1_kor_u1_L05_challenge','lesson_challenge','K4-1-u1-C31',4,'essay','teacher','「눈이 어두운 두더지 무루」에서 글쓴이가 전하고 싶은 생각을 쓰고, 그렇게 생각한 까닭이 되는 장면을 두 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u1-C31","difficulty":4,"kind":"essay","stem":"「눈이 어두운 두더지 무루」에서 글쓴이가 전하고 싶은 생각을 쓰고, 그렇게 생각한 까닭이 되는 장면을 두 가지 쓰세요.","answer_guide":{"answer":"예: 겉모습으로 판단하지 말고 서로 다른 점을 존중하자는 생각이다. 첫째, 두더지들은 눈이 어둡다고 무루를 밀어냈다(③). 둘째, 그 무루가 앞발로 흙의 떨림을 느껴 모두를 구했고, 그 뒤로 마을에서 서로 다른 재주를 귀하게 여기게 되었다(⑦·⑧).","scoring_points":["글쓴이가 전하고 싶은 생각을 썼는가","까닭이 되는 장면을 두 가지 썼는가","이야기의 흐름 전체에서 생각을 찾았는가"]},"explanation":["처음과 끝을 견줘요.","무엇이 힘이 되었나요?","장면 두 가지"],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L05_challenge#10','kor',4,1,'u1','L05','g4_1_kor_u1_L05_challenge','lesson_challenge','K4-1-u1-C32',4,'essay','teacher','마루처럼 나를 믿어 준 사람이나, 내가 누군가에게 그런 사람이 되어 준 일을 하나 떠올려 쓰고, 그 사람과 나는 어떤 관계였는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u1-C32","difficulty":4,"kind":"essay","stem":"마루처럼 나를 믿어 준 사람이나, 내가 누군가에게 그런 사람이 되어 준 일을 하나 떠올려 쓰고, 그 사람과 나는 어떤 관계였는지 쓰세요.","answer_guide":{"answer":"예: 줄넘기를 못해 속상했을 때 짝이 날마다 쉬는 시간에 줄을 돌려 주며 「넌 할 수 있어」라고 말해 주었다. 짝과 나는 서로 도와주는 관계였다.","scoring_points":["있었던 일을 구체적으로 썼는가","그 사람의 말이나 행동을 넣었는가","어떤 관계였는지 썼는가"]},"explanation":["내 주변의 마루","무슨 말, 무슨 행동?","어떤 관계였나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_basic#1','kor',4,1,'u1','L07','g4_1_kor_u1_L07_basic','lesson_basic','K4-1-u1-C38',1,'mc','auto','내용을 짐작하는 질문을 만드는 네 갈래에 들어가는 것은 무엇인가요?',ARRAY['K4-1-u1-X34']::text[],false,'{"seq":1,"concept":"K4-1-u1-C38","difficulty":1,"kind":"mc","stem":"내용을 짐작하는 질문을 만드는 네 갈래에 들어가는 것은 무엇인가요?","options":[{"t":"자신의 경험과 관련지은 질문","correct":true},{"t":"글자 수를 세는 질문","mis":"K4-1-u1-X34"},{"t":"쪽수를 묻는 질문","mis":"K4-1-u1-X34"},{"t":"글이 몇 줄인지 묻는 질문","mis":"K4-1-u1-X34"}],"explanation":["낱말 · 이어질 내용","경험 · 궁금한 점","네 갈래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_basic#2','kor',4,1,'u1','L07','g4_1_kor_u1_L07_basic','lesson_basic','K4-1-u1-C35',1,'mc','auto','옹기를 「숨 쉬는 그릇」이라고 부르는 까닭은 무엇인가요?',ARRAY['K4-1-u1-X31']::text[],false,'{"seq":2,"concept":"K4-1-u1-C35","difficulty":1,"kind":"mc","stem":"옹기를 「숨 쉬는 그릇」이라고 부르는 까닭은 무엇인가요?","options":[{"t":"아주 작은 구멍으로 공기가 드나들어서","correct":true},{"t":"뚜껑을 열어 두고 쓰는 그릇이어서","mis":"K4-1-u1-X31"},{"t":"물을 담아 두는 그릇이어서","mis":"K4-1-u1-X31"},{"t":"흙냄새가 나는 그릇이어서","mis":"K4-1-u1-X31"}],"explanation":["②를 봐요.","작은 구멍이 있어요.","공기가 드나들어요."],"asset":{"type":"passage","lines":["① 옹기는 흙으로 만든 우리나라 고유의 그릇이다.","② 옹기에는 아주 작은 구멍이 촘촘히 나 있어 공기가 드나든다.","③ 그래서 음식을 오래 보관할 수 있어 「숨 쉬는 그릇」이라고 부른다.","④ 옹기는 허리가 불룩해 여러 개를 모아 두면 옹기 사이에 틈이 생긴다.","⑤ 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지한다.","⑥ 우리나라는 옹기를 만드는 기술자인 옹기장을 무형유산으로 지정했다."],"title":"숨 쉬는 그릇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_basic#3','kor',4,1,'u1','L07','g4_1_kor_u1_L07_basic','lesson_basic','K4-1-u1-C34',1,'mc','auto','「숨 쉬는 그릇」이라는 제목과 항아리 그림만 보았어요. 아직 글을 읽지 않았을 때 만들 수 있는 질문은 무엇인가요?',ARRAY['K4-1-u1-X30','K4-1-u1-X34']::text[],false,'{"seq":3,"concept":"K4-1-u1-C34","difficulty":1,"kind":"mc","stem":"「숨 쉬는 그릇」이라는 제목과 항아리 그림만 보았어요. 아직 글을 읽지 않았을 때 만들 수 있는 질문은 무엇인가요?","options":[{"t":"숨 쉬는 그릇은 어떤 그릇일까?","correct":true},{"t":"글에 나온 「무형유산」의 뜻은 무엇일까?","mis":"K4-1-u1-X30"},{"t":"⑤에 나온 「틈」은 어디에 생길까?","mis":"K4-1-u1-X30"},{"t":"이 글의 셋째 문단은 몇 줄일까?","mis":"K4-1-u1-X34"}],"explanation":["아직 안 읽었어요.","제목과 그림만 있어요.","제목에서 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_basic#4','kor',4,1,'u1','L07','g4_1_kor_u1_L07_basic','lesson_basic','K4-1-u1-C37',1,'mc','auto','「보관하다」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X20']::text[],false,'{"seq":4,"concept":"K4-1-u1-C37","difficulty":1,"kind":"mc","stem":"「보관하다」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"간직하고 관리하다","correct":true},{"t":"어떤 것에 자격을 주다","mis":"K4-1-u1-X20"},{"t":"어떤 상태를 변함없이 이어 가다","mis":"K4-1-u1-X20"},{"t":"물건을 남에게 빌려주다","mis":"K4-1-u1-X20"}],"explanation":["③을 다시 봐요.","음식을 오래 두어요.","간직하고 관리해요."],"asset":{"type":"passage","lines":["① 옹기는 흙으로 만든 우리나라 고유의 그릇이다.","② 옹기에는 아주 작은 구멍이 촘촘히 나 있어 공기가 드나든다.","③ 그래서 음식을 오래 보관할 수 있어 「숨 쉬는 그릇」이라고 부른다.","④ 옹기는 허리가 불룩해 여러 개를 모아 두면 옹기 사이에 틈이 생긴다.","⑤ 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지한다.","⑥ 우리나라는 옹기를 만드는 기술자인 옹기장을 무형유산으로 지정했다."],"title":"숨 쉬는 그릇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_basic#5','kor',4,1,'u1','L07','g4_1_kor_u1_L07_basic','lesson_basic','K4-1-u1-C37',2,'match','auto','「숨 쉬는 그릇」에 나온 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-1-u1-C37","difficulty":2,"kind":"match","stem":"「숨 쉬는 그릇」에 나온 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"보관하다","r":"간직하고 관리하다"},{"l":"유지하다","r":"어떤 상태를 변함없이 이어 가다"},{"l":"지정하다","r":"어떤 것에 자격을 주다"}],"mis":"K4-1-u1-X20","explanation":["그 낱말이 나온 문장을 봐요.","③ · ⑤ · ⑥","앞뒤가 뜻을 알려 줘요."],"asset":{"type":"passage","lines":["① 옹기는 흙으로 만든 우리나라 고유의 그릇이다.","② 옹기에는 아주 작은 구멍이 촘촘히 나 있어 공기가 드나든다.","③ 그래서 음식을 오래 보관할 수 있어 「숨 쉬는 그릇」이라고 부른다.","④ 옹기는 허리가 불룩해 여러 개를 모아 두면 옹기 사이에 틈이 생긴다.","⑤ 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지한다.","⑥ 우리나라는 옹기를 만드는 기술자인 옹기장을 무형유산으로 지정했다."],"title":"숨 쉬는 그릇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_basic#6','kor',4,1,'u1','L07','g4_1_kor_u1_L07_basic','lesson_basic','K4-1-u1-C36',2,'mc','auto','옹기의 허리가 불룩한 까닭은 무엇인가요?',ARRAY['K4-1-u1-X32']::text[],false,'{"seq":6,"concept":"K4-1-u1-C36","difficulty":2,"kind":"mc","stem":"옹기의 허리가 불룩한 까닭은 무엇인가요?","options":[{"t":"모아 두면 틈이 생겨 바람이 지나가 위와 아래의 온도가 비슷해지기 때문에","correct":true},{"t":"보기에 예뻐 보이려고","mis":"K4-1-u1-X32"},{"t":"음식을 더 많이 담으려고","mis":"K4-1-u1-X32"},{"t":"무거워서 잘 넘어지지 않게 하려고","mis":"K4-1-u1-X32"}],"explanation":["④ · ⑤를 봐요.","틈과 바람이에요.","온도를 유지해요."],"asset":{"type":"passage","lines":["① 옹기는 흙으로 만든 우리나라 고유의 그릇이다.","② 옹기에는 아주 작은 구멍이 촘촘히 나 있어 공기가 드나든다.","③ 그래서 음식을 오래 보관할 수 있어 「숨 쉬는 그릇」이라고 부른다.","④ 옹기는 허리가 불룩해 여러 개를 모아 두면 옹기 사이에 틈이 생긴다.","⑤ 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지한다.","⑥ 우리나라는 옹기를 만드는 기술자인 옹기장을 무형유산으로 지정했다."],"title":"숨 쉬는 그릇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_basic#7','kor',4,1,'u1','L07','g4_1_kor_u1_L07_basic','lesson_basic','K4-1-u1-C40',2,'mc','auto','「숨 쉬는 그릇」의 내용을 짐작하는 데 도움이 되는 질문은 무엇인가요?',ARRAY['K4-1-u1-X34']::text[],false,'{"seq":7,"concept":"K4-1-u1-C40","difficulty":2,"kind":"mc","stem":"「숨 쉬는 그릇」의 내용을 짐작하는 데 도움이 되는 질문은 무엇인가요?","options":[{"t":"옹기에 음식을 보관하면 어떤 점이 좋을까?","correct":true},{"t":"이 글에 글자가 모두 몇 개일까?","mis":"K4-1-u1-X34"},{"t":"이 책은 모두 몇 쪽일까?","mis":"K4-1-u1-X34"},{"t":"「옹기」가 몇 번 나오는지 세어 볼까?","mis":"K4-1-u1-X34"}],"explanation":["세는 질문은 아니에요.","내용을 물어요.","어떤 점이 좋을까?"],"asset":{"type":"passage","lines":["① 옹기는 흙으로 만든 우리나라 고유의 그릇이다.","② 옹기에는 아주 작은 구멍이 촘촘히 나 있어 공기가 드나든다.","③ 그래서 음식을 오래 보관할 수 있어 「숨 쉬는 그릇」이라고 부른다.","④ 옹기는 허리가 불룩해 여러 개를 모아 두면 옹기 사이에 틈이 생긴다.","⑤ 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지한다.","⑥ 우리나라는 옹기를 만드는 기술자인 옹기장을 무형유산으로 지정했다."],"title":"숨 쉬는 그릇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_basic#8','kor',4,1,'u1','L07','g4_1_kor_u1_L07_basic','lesson_basic','K4-1-u1-C39',2,'match','auto','질문과 그 질문을 만든 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u1-C39","difficulty":2,"kind":"match","stem":"질문과 그 질문을 만든 갈래를 알맞게 이으세요.","pairs":[{"l":"「무형유산」의 뜻은 무엇일까?","r":"낱말의 뜻을 짐작하는 질문"},{"l":"박물관에서 본 항아리도 옹기였을까?","r":"자신의 경험과 관련지은 질문"},{"l":"옹기 말고도 숨 쉬는 그릇이 또 있을까?","r":"더 궁금한 점을 묻는 질문"}],"mis":"K4-1-u1-X33","explanation":["질문에 무엇이 담겼나요?","낱말 · 경험 · 궁금한 점","같은 글, 여러 갈래"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_basic#9','kor',4,1,'u1','L07','g4_1_kor_u1_L07_basic','lesson_basic','K4-1-u1-C33',2,'mc','auto','글을 읽기 전과 읽는 중에 질문을 만들며 읽으면 좋은 점은 무엇인가요?',ARRAY['K4-1-u1-X29','K4-1-u1-X36','K4-1-u1-X04']::text[],false,'{"seq":9,"concept":"K4-1-u1-C33","difficulty":2,"kind":"mc","stem":"글을 읽기 전과 읽는 중에 질문을 만들며 읽으면 좋은 점은 무엇인가요?","options":[{"t":"내용을 미리 짐작하고 더 깊이 볼 수 있다","correct":true},{"t":"글을 다 읽은 뒤에 시험 문제를 풀 수 있다","mis":"K4-1-u1-X29"},{"t":"질문을 많이 만들어 친구를 이길 수 있다","mis":"K4-1-u1-X36"},{"t":"글을 읽지 않아도 내용을 다 알 수 있다","mis":"K4-1-u1-X04"}],"explanation":["스무고개를 떠올려요.","좋은 질문 하나가 길을 보여 줘요.","미리 짐작하고 깊이 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_basic#10','kor',4,1,'u1','L07','g4_1_kor_u1_L07_basic','lesson_basic','K4-1-u1-C41',3,'mc','auto','「숨 쉬는 그릇」을 더 깊이 보게 하는 질문은 무엇인가요?',ARRAY['K4-1-u1-X35','K4-1-u1-X36']::text[],false,'{"seq":10,"concept":"K4-1-u1-C41","difficulty":3,"kind":"mc","stem":"「숨 쉬는 그릇」을 더 깊이 보게 하는 질문은 무엇인가요?","options":[{"t":"옛날 사람들은 왜 옹기의 허리를 불룩하게 만들었을까?","correct":true},{"t":"옹기는 무엇으로 만드나요?","mis":"K4-1-u1-X35"},{"t":"옹기를 만드는 기술자를 무엇이라고 하나요?","mis":"K4-1-u1-X35"},{"t":"옹기에 대한 질문을 스무 개 만들어 볼까?","mis":"K4-1-u1-X36"}],"explanation":["답이 그대로 있으면?","빈 곳을 메우는 질문","「왜?」를 물어요."],"asset":{"type":"passage","lines":["① 옹기는 흙으로 만든 우리나라 고유의 그릇이다.","② 옹기에는 아주 작은 구멍이 촘촘히 나 있어 공기가 드나든다.","③ 그래서 음식을 오래 보관할 수 있어 「숨 쉬는 그릇」이라고 부른다.","④ 옹기는 허리가 불룩해 여러 개를 모아 두면 옹기 사이에 틈이 생긴다.","⑤ 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지한다.","⑥ 우리나라는 옹기를 만드는 기술자인 옹기장을 무형유산으로 지정했다."],"title":"숨 쉬는 그릇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_challenge#1','kor',4,1,'u1','L07','g4_1_kor_u1_L07_challenge','lesson_challenge','K4-1-u1-C33',2,'mc','auto','내용을 짐작하는 질문은 언제 만들 수 있나요?',ARRAY['K4-1-u1-X29']::text[],false,'{"seq":1,"concept":"K4-1-u1-C33","difficulty":2,"kind":"mc","stem":"내용을 짐작하는 질문은 언제 만들 수 있나요?","options":[{"t":"글을 읽기 전에도, 읽는 중에도 만든다","correct":true},{"t":"글을 다 읽은 뒤에만 만든다","mis":"K4-1-u1-X29"},{"t":"선생님이 시킬 때만 만든다","mis":"K4-1-u1-X29"},{"t":"읽기 전에만 만들고 읽는 중에는 만들지 않는다","mis":"K4-1-u1-X29"}],"explanation":["읽기 전 — 제목과 그림","읽는 중 — 낱말과 이어질 내용","둘 다 만들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_challenge#2','kor',4,1,'u1','L07','g4_1_kor_u1_L07_challenge','lesson_challenge','K4-1-u1-C38',2,'mc','auto','「바람이 드나드는 종이」를 읽고 「질기다는 말은 무슨 뜻일까?」라고 물었어요. 어떤 갈래의 질문인가요?',ARRAY['K4-1-u1-X33','K4-1-u1-X34']::text[],false,'{"seq":2,"concept":"K4-1-u1-C38","difficulty":2,"kind":"mc","stem":"「바람이 드나드는 종이」를 읽고 「질기다는 말은 무슨 뜻일까?」라고 물었어요. 어떤 갈래의 질문인가요?","options":[{"t":"낱말의 뜻을 짐작하는 질문","correct":true},{"t":"자신의 경험과 관련지은 질문","mis":"K4-1-u1-X33"},{"t":"이어질 내용을 짐작하는 질문","mis":"K4-1-u1-X33"},{"t":"글자 수를 세는 질문","mis":"K4-1-u1-X34"}],"explanation":["무엇을 묻나요?","「질기다」의 뜻이에요.","낱말의 뜻 질문이에요."],"asset":{"type":"passage","lines":["① 한지는 닥나무 껍질로 만든 우리 종이이다.","② 한지는 질겨서 잘 찢어지지 않는다.","③ 또 종이 사이로 바람이 잘 드나든다.","④ 그래서 옛날 사람들은 한지를 문에 발라 썼다."],"title":"바람이 드나드는 종이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_challenge#3','kor',4,1,'u1','L07','g4_1_kor_u1_L07_challenge','lesson_challenge','K4-1-u1-C34',3,'mc','auto','「바람이 드나드는 종이」라는 제목만 보았어요. 글을 읽기 전에 만들 수 있는 질문은 무엇인가요?',ARRAY['K4-1-u1-X30']::text[],false,'{"seq":3,"concept":"K4-1-u1-C34","difficulty":3,"kind":"mc","stem":"「바람이 드나드는 종이」라는 제목만 보았어요. 글을 읽기 전에 만들 수 있는 질문은 무엇인가요?","options":[{"t":"어떤 종이이기에 바람이 드나든다고 했을까?","correct":true},{"t":"「닥나무」는 어떤 나무일까?","mis":"K4-1-u1-X30"},{"t":"「질겨서」는 무슨 뜻일까?","mis":"K4-1-u1-X30"},{"t":"한지를 문에 바른 까닭은 무엇일까?","mis":"K4-1-u1-X30"}],"explanation":["아직 본문을 안 읽었어요.","닥나무 · 질겨서는 본문에 나와요.","제목에서 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_challenge#4','kor',4,1,'u1','L07','g4_1_kor_u1_L07_challenge','lesson_challenge','K4-1-u1-C41',3,'mc','auto','「바람이 드나드는 종이」의 빈 곳을 메우는 질문은 무엇인가요?',ARRAY['K4-1-u1-X35','K4-1-u1-X36']::text[],false,'{"seq":4,"concept":"K4-1-u1-C41","difficulty":3,"kind":"mc","stem":"「바람이 드나드는 종이」의 빈 곳을 메우는 질문은 무엇인가요?","options":[{"t":"바람이 잘 드나드는 종이를 문에 바르면 무엇이 좋았을까?","correct":true},{"t":"한지는 무엇으로 만드나요?","mis":"K4-1-u1-X35"},{"t":"한지는 질긴가요?","mis":"K4-1-u1-X35"},{"t":"한지에 대한 질문을 열 개 넘게 써 볼까?","mis":"K4-1-u1-X36"}],"explanation":["답이 글에 그대로 있나요?","글에 없는 까닭을 물어요.","깊이 보게 해요."],"asset":{"type":"passage","lines":["① 한지는 닥나무 껍질로 만든 우리 종이이다.","② 한지는 질겨서 잘 찢어지지 않는다.","③ 또 종이 사이로 바람이 잘 드나든다.","④ 그래서 옛날 사람들은 한지를 문에 발라 썼다."],"title":"바람이 드나드는 종이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_challenge#5','kor',4,1,'u1','L07','g4_1_kor_u1_L07_challenge','lesson_challenge','K4-1-u1-C39',3,'mc','auto','「바람이 드나드는 종이」를 읽고 자신의 경험과 관련지어 만든 질문은 무엇인가요?',ARRAY['K4-1-u1-X33','K4-1-u1-X34']::text[],false,'{"seq":5,"concept":"K4-1-u1-C39","difficulty":3,"kind":"mc","stem":"「바람이 드나드는 종이」를 읽고 자신의 경험과 관련지어 만든 질문은 무엇인가요?","options":[{"t":"할머니 댁 문에 붙은 하얀 종이도 한지일까?","correct":true},{"t":"「닥나무」는 어떤 나무일까?","mis":"K4-1-u1-X33"},{"t":"한지 말고 바람이 드나드는 물건이 또 있을까?","mis":"K4-1-u1-X33"},{"t":"「한지」라는 낱말은 몇 글자일까?","mis":"K4-1-u1-X34"}],"explanation":["내가 겪은 일이 담겼나요?","할머니 댁 문","경험과 관련지었어요."],"asset":{"type":"passage","lines":["① 한지는 닥나무 껍질로 만든 우리 종이이다.","② 한지는 질겨서 잘 찢어지지 않는다.","③ 또 종이 사이로 바람이 잘 드나든다.","④ 그래서 옛날 사람들은 한지를 문에 발라 썼다."],"title":"바람이 드나드는 종이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_challenge#6','kor',4,1,'u1','L07','g4_1_kor_u1_L07_challenge','lesson_challenge','K4-1-u1-C40',3,'mc','auto','「바람이 드나드는 종이」의 내용을 짐작하는 데 도움이 되는 질문만 모은 것은 무엇인가요?',ARRAY['K4-1-u1-X34','K4-1-u1-X35']::text[],false,'{"seq":6,"concept":"K4-1-u1-C40","difficulty":3,"kind":"mc","stem":"「바람이 드나드는 종이」의 내용을 짐작하는 데 도움이 되는 질문만 모은 것은 무엇인가요?","options":[{"t":"왜 문에 발랐을까? / 질기다는 무슨 뜻일까?","correct":true},{"t":"이 글은 몇 줄일까? / 왜 문에 발랐을까?","mis":"K4-1-u1-X34"},{"t":"글자는 몇 개일까? / 이 책은 몇 쪽일까?","mis":"K4-1-u1-X34"},{"t":"한지는 무엇으로 만들까? / 한지는 질길까?","mis":"K4-1-u1-X35"}],"explanation":["세는 질문은 빼요.","답이 그대로 있는 질문보다","까닭 · 뜻을 물어요."],"asset":{"type":"passage","lines":["① 한지는 닥나무 껍질로 만든 우리 종이이다.","② 한지는 질겨서 잘 찢어지지 않는다.","③ 또 종이 사이로 바람이 잘 드나든다.","④ 그래서 옛날 사람들은 한지를 문에 발라 썼다."],"title":"바람이 드나드는 종이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_challenge#7','kor',4,1,'u1','L07','g4_1_kor_u1_L07_challenge','lesson_challenge','K4-1-u1-C36',3,'mc','auto','⑤를 읽고 「옹기를 틈 없이 딱 붙여 두면 어떻게 될까?」라고 물었어요. 글을 바탕으로 한 가장 알맞은 짐작은 무엇인가요?',ARRAY['K4-1-u1-X32','K4-1-u1-X31','K4-1-u1-X04']::text[],false,'{"seq":7,"concept":"K4-1-u1-C36","difficulty":3,"kind":"mc","stem":"⑤를 읽고 「옹기를 틈 없이 딱 붙여 두면 어떻게 될까?」라고 물었어요. 글을 바탕으로 한 가장 알맞은 짐작은 무엇인가요?","options":[{"t":"바람이 지나가지 못해 위와 아래의 온도가 달라질 것이다","correct":true},{"t":"옹기가 더 예뻐 보일 것이다","mis":"K4-1-u1-X32"},{"t":"옹기의 구멍이 더 커질 것이다","mis":"K4-1-u1-X31"},{"t":"아무 일도 일어나지 않을 것이다","mis":"K4-1-u1-X04"}],"explanation":["틈은 무엇을 지나가게 하나요?","바람이에요.","틈이 없으면 온도가⋯⋯"],"asset":{"type":"passage","lines":["① 옹기는 흙으로 만든 우리나라 고유의 그릇이다.","② 옹기에는 아주 작은 구멍이 촘촘히 나 있어 공기가 드나든다.","③ 그래서 음식을 오래 보관할 수 있어 「숨 쉬는 그릇」이라고 부른다.","④ 옹기는 허리가 불룩해 여러 개를 모아 두면 옹기 사이에 틈이 생긴다.","⑤ 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지한다.","⑥ 우리나라는 옹기를 만드는 기술자인 옹기장을 무형유산으로 지정했다."],"title":"숨 쉬는 그릇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_challenge#8','kor',4,1,'u1','L07','g4_1_kor_u1_L07_challenge','lesson_challenge','K4-1-u1-C38',4,'essay','teacher','「바람이 드나드는 종이」를 읽고 서로 다른 갈래의 질문을 두 개 만들고, 각 질문이 어떤 갈래인지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u1-C38","difficulty":4,"kind":"essay","stem":"「바람이 드나드는 종이」를 읽고 서로 다른 갈래의 질문을 두 개 만들고, 각 질문이 어떤 갈래인지 쓰세요.","answer_guide":{"answer":"예: 「질기다는 말은 무슨 뜻일까?」 — 낱말의 뜻을 짐작하는 질문. 「우리 집 창문에도 한지를 붙이면 바람이 잘 통할까?」 — 자신의 경험과 관련지은 질문.","scoring_points":["질문을 두 개 만들었는가","두 질문의 갈래가 서로 다른가","각 질문의 갈래를 바르게 썼는가"]},"explanation":["네 갈래를 떠올려요.","서로 다른 갈래로","갈래 이름도 써요."],"asset":{"type":"passage","lines":["① 한지는 닥나무 껍질로 만든 우리 종이이다.","② 한지는 질겨서 잘 찢어지지 않는다.","③ 또 종이 사이로 바람이 잘 드나든다.","④ 그래서 옛날 사람들은 한지를 문에 발라 썼다."],"title":"바람이 드나드는 종이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_challenge#9','kor',4,1,'u1','L07','g4_1_kor_u1_L07_challenge','lesson_challenge','K4-1-u1-C41',4,'essay','teacher','「숨 쉬는 그릇」을 읽고 답이 글에 그대로 있는 질문 하나와 글의 빈 곳을 메우는 질문 하나를 만들어 쓰고, 어느 질문이 글을 더 깊이 보게 하는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u1-C41","difficulty":4,"kind":"essay","stem":"「숨 쉬는 그릇」을 읽고 답이 글에 그대로 있는 질문 하나와 글의 빈 곳을 메우는 질문 하나를 만들어 쓰고, 어느 질문이 글을 더 깊이 보게 하는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 답이 그대로 있는 질문 — 「옹기는 무엇으로 만드나요?」 빈 곳을 메우는 질문 — 「옛날 사람들은 왜 옹기를 여러 개 모아 장독대에 두었을까?」 빈 곳을 메우는 질문이 글에 없는 까닭을 생각하게 해서 더 깊이 보게 한다.","scoring_points":["답이 글에 그대로 있는 질문을 만들었는가","빈 곳을 메우는 질문을 만들었는가","어느 질문이 더 깊이 보게 하는지 까닭을 썼는가"]},"explanation":["글에 답이 있나요?","「왜?」를 물어요.","까닭도 써요."],"asset":{"type":"passage","lines":["① 옹기는 흙으로 만든 우리나라 고유의 그릇이다.","② 옹기에는 아주 작은 구멍이 촘촘히 나 있어 공기가 드나든다.","③ 그래서 음식을 오래 보관할 수 있어 「숨 쉬는 그릇」이라고 부른다.","④ 옹기는 허리가 불룩해 여러 개를 모아 두면 옹기 사이에 틈이 생긴다.","⑤ 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지한다.","⑥ 우리나라는 옹기를 만드는 기술자인 옹기장을 무형유산으로 지정했다."],"title":"숨 쉬는 그릇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L07_challenge#10','kor',4,1,'u1','L07','g4_1_kor_u1_L07_challenge','lesson_challenge','K4-1-u1-C35',4,'essay','teacher','「숨 쉬는 그릇」을 바탕으로 옹기에 담은 음식이 오래 알맞게 보관되는 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u1-C35","difficulty":4,"kind":"essay","stem":"「숨 쉬는 그릇」을 바탕으로 옹기에 담은 음식이 오래 알맞게 보관되는 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 첫째, 옹기에 난 아주 작은 구멍으로 공기가 드나들기 때문이다. 둘째, 허리가 불룩해 모아 두면 틈이 생기고 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지하기 때문이다.","scoring_points":["작은 구멍으로 공기가 드나든다는 까닭을 썼는가","불룩한 허리 사이의 틈과 바람·온도를 썼는가","글에 나온 내용을 바탕으로 썼는가"]},"explanation":["②를 봐요.","④ · ⑤를 봐요.","두 가지예요."],"asset":{"type":"passage","lines":["① 옹기는 흙으로 만든 우리나라 고유의 그릇이다.","② 옹기에는 아주 작은 구멍이 촘촘히 나 있어 공기가 드나든다.","③ 그래서 음식을 오래 보관할 수 있어 「숨 쉬는 그릇」이라고 부른다.","④ 옹기는 허리가 불룩해 여러 개를 모아 두면 옹기 사이에 틈이 생긴다.","⑤ 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지한다.","⑥ 우리나라는 옹기를 만드는 기술자인 옹기장을 무형유산으로 지정했다."],"title":"숨 쉬는 그릇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_basic#1','kor',4,1,'u1','L09','g4_1_kor_u1_L09_basic','lesson_basic','K4-1-u1-C42',1,'mc','auto','「씨앗을 지키는 사람들」이라는 제목을 보고 짐작한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X04','K4-1-u1-X37']::text[],false,'{"seq":1,"concept":"K4-1-u1-C42","difficulty":1,"kind":"mc","stem":"「씨앗을 지키는 사람들」이라는 제목을 보고 짐작한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리 씨앗을 지키려고 애쓰는 사람들의 이야기일 것이다","correct":true},{"t":"씨앗을 파는 가게를 소개하는 글일 것이다","mis":"K4-1-u1-X04"},{"t":"씨앗의 이름을 모두 늘어놓은 글일 것이다","mis":"K4-1-u1-X04"},{"t":"제목은 보지 않고 바로 본문을 읽으면 된다","mis":"K4-1-u1-X37"}],"explanation":["「지키는 사람들」","제목에 글쓴이의 뜻이 있어요.","지키는 사람들의 이야기예요."],"asset":{"type":"passage","lines":["제목: 씨앗을 지키는 사람들","차례 1. 굶어도 씨앗은 남긴다","차례 2. 사라져 가는 우리 씨앗","차례 3. 씨앗은 살아 있다","차례 4. 씨앗을 나누는 모임"],"title":"읽기 전 — 제목과 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_basic#2','kor',4,1,'u1','L09','g4_1_kor_u1_L09_basic','lesson_basic','K4-1-u1-C46',1,'mc','auto','「재배하다」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X20']::text[],false,'{"seq":2,"concept":"K4-1-u1-C46","difficulty":1,"kind":"mc","stem":"「재배하다」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"식물을 심어 가꾸다","correct":true},{"t":"어떤 일을 자꾸 되풀이하다","mis":"K4-1-u1-X20"},{"t":"도구나 물건을 충분히 잘 이용하다","mis":"K4-1-u1-X20"},{"t":"씨앗을 돈을 내고 사 오다","mis":"K4-1-u1-X20"}],"explanation":["③을 봐요.","농가에서 채소를⋯⋯","심어 가꿔요."],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_basic#3','kor',4,1,'u1','L09','g4_1_kor_u1_L09_basic','lesson_basic','K4-1-u1-C45',1,'mc','auto','글에서 말한 씨앗을 되살리는 길은 무엇인가요?',ARRAY['K4-1-u1-X38']::text[],false,'{"seq":3,"concept":"K4-1-u1-C45","difficulty":1,"kind":"mc","stem":"글에서 말한 씨앗을 되살리는 길은 무엇인가요?","options":[{"t":"여러 사람과 나누고 심고 거두기를 거듭한다","correct":true},{"t":"냉동실에 넣어 오래 두기만 한다","mis":"K4-1-u1-X38"},{"t":"해마다 밖에서 새 씨앗을 사 온다","mis":"K4-1-u1-X38"},{"t":"씨앗을 땅에 묻고 그대로 둔다","mis":"K4-1-u1-X38"}],"explanation":["⑤ · ⑥을 봐요.","냉동실만으로는 모자라요.","⑦이 답이에요."],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_basic#4','kor',4,1,'u1','L09','g4_1_kor_u1_L09_basic','lesson_basic','K4-1-u1-C48',1,'mc','auto','읽기 전에 짐작한 내용과 실제 글을 견주어 보면 좋은 점은 무엇인가요?',ARRAY['K4-1-u1-X40','K4-1-u1-X41']::text[],false,'{"seq":4,"concept":"K4-1-u1-C48","difficulty":1,"kind":"mc","stem":"읽기 전에 짐작한 내용과 실제 글을 견주어 보면 좋은 점은 무엇인가요?","options":[{"t":"같은 점과 다른 점을 찾아 내 읽기를 스스로 점검할 수 있다","correct":true},{"t":"짐작이 맞았는지 점수를 매길 수 있다","mis":"K4-1-u1-X40"},{"t":"글에 그림이 몇 장인지 견줄 수 있다","mis":"K4-1-u1-X41"},{"t":"짐작과 다르면 짐작을 지울 수 있다","mis":"K4-1-u1-X40"}],"explanation":["나란히 놓아 봐요.","같은 점 · 다른 점","내 읽기를 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_basic#5','kor',4,1,'u1','L09','g4_1_kor_u1_L09_basic','lesson_basic','K4-1-u1-C43',2,'mc','auto','차례 「굶어도 씨앗은 남긴다」를 보고 짐작할 수 있는 것은 무엇인가요?',ARRAY['K4-1-u1-X04','K4-1-u1-X37']::text[],false,'{"seq":5,"concept":"K4-1-u1-C43","difficulty":2,"kind":"mc","stem":"차례 「굶어도 씨앗은 남긴다」를 보고 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"씨앗을 남기는 일이 아주 중요한 일이었다","correct":true},{"t":"옛날에는 씨앗을 밥 대신 먹었다","mis":"K4-1-u1-X04"},{"t":"차례는 내용과 상관이 없다","mis":"K4-1-u1-X37"},{"t":"씨앗을 남기면 반드시 굶게 된다","mis":"K4-1-u1-X04"}],"explanation":["굶어도 남긴다면?","그만큼 소중했어요.","차례도 질문거리예요."],"asset":{"type":"passage","lines":["제목: 씨앗을 지키는 사람들","차례 1. 굶어도 씨앗은 남긴다","차례 2. 사라져 가는 우리 씨앗","차례 3. 씨앗은 살아 있다","차례 4. 씨앗을 나누는 모임"],"title":"읽기 전 — 제목과 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
