INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_basic#7','kor',4,1,'u1','L09','g4_1_kor_u1_L09_basic','lesson_basic','K4-1-u1-C44',2,'mc','auto','조상들이 아무리 어려워도 씨앗만은 남긴 까닭은 무엇인가요?',ARRAY['K4-1-u1-X39','K4-1-u1-X38']::text[],false,'{"seq":7,"concept":"K4-1-u1-C44","difficulty":2,"kind":"mc","stem":"조상들이 아무리 어려워도 씨앗만은 남긴 까닭은 무엇인가요?","options":[{"t":"씨앗에 농사의 지혜가 담겨 있어서","correct":true},{"t":"씨앗을 팔아 돈을 벌려고","mis":"K4-1-u1-X39"},{"t":"씨앗이 보기 좋아서","mis":"K4-1-u1-X39"},{"t":"냉동실에 넣어 두려고","mis":"K4-1-u1-X38"}],"explanation":["②를 봐요.","「때문이다」 앞을 봐요.","농사의 지혜예요."],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_basic#8','kor',4,1,'u1','L09','g4_1_kor_u1_L09_basic','lesson_basic','K4-1-u1-C47',2,'mc','auto','읽다가 「토종이라는 말은 무슨 뜻일까?」라는 질문이 떠올랐어요. 알맞게 한 것은 무엇인가요?',ARRAY['K4-1-u1-X42','K4-1-u1-X36','K4-1-u1-X34']::text[],false,'{"seq":8,"concept":"K4-1-u1-C47","difficulty":2,"kind":"mc","stem":"읽다가 「토종이라는 말은 무슨 뜻일까?」라는 질문이 떠올랐어요. 알맞게 한 것은 무엇인가요?","options":[{"t":"글에서 토종 씨앗을 설명한 문장을 찾아 답해 본다","correct":true},{"t":"답을 찾지 않고 다음 문장으로 넘어간다","mis":"K4-1-u1-X42"},{"t":"질문을 더 많이 만들어 공책을 채운다","mis":"K4-1-u1-X36"},{"t":"「토종」이 몇 번 나오는지 센다","mis":"K4-1-u1-X34"}],"explanation":["①을 봐요.","질문에 답해 봐요.","글에서 찾아요."],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_basic#9','kor',4,1,'u1','L09','g4_1_kor_u1_L09_basic','lesson_basic','K4-1-u1-C49',2,'mc','auto','짐작한 내용과 글의 내용이 달랐어요. 어떻게 하는 것이 알맞나요?',ARRAY['K4-1-u1-X40']::text[],false,'{"seq":9,"concept":"K4-1-u1-C49","difficulty":2,"kind":"mc","stem":"짐작한 내용과 글의 내용이 달랐어요. 어떻게 하는 것이 알맞나요?","options":[{"t":"다른 점은 미처 몰랐던 새로 안 것으로 정리한다","correct":true},{"t":"잘못 읽었으니 처음부터 다시 읽는다","mis":"K4-1-u1-X40"},{"t":"짐작한 내용을 글에 맞게 고쳐 쓴다","mis":"K4-1-u1-X40"},{"t":"다른 점은 틀린 것이니 지운다","mis":"K4-1-u1-X40"}],"explanation":["짐작은 틀려도 괜찮아요.","다른 점 = 새로 안 것","정리해 두어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_basic#10','kor',4,1,'u1','L09','g4_1_kor_u1_L09_basic','lesson_basic','K4-1-u1-C49',3,'mc','auto','「씨앗을 지키는 사람들」을 읽기 전 짐작과 견주어, 새로 안 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X41','K4-1-u1-X40']::text[],false,'{"seq":10,"concept":"K4-1-u1-C49","difficulty":3,"kind":"mc","stem":"「씨앗을 지키는 사람들」을 읽기 전 짐작과 견주어, 새로 안 것으로 알맞은 것은 무엇인가요?","options":[{"t":"채소 씨앗도 밖에서 사 오는 일이 많다는 것은 짐작하지 못했다","correct":true},{"t":"씨앗이 흙에서 자란다는 것을 새로 알았다","mis":"K4-1-u1-X41"},{"t":"글에 그림이 몇 장 있는지 알게 되었다","mis":"K4-1-u1-X41"},{"t":"짐작과 달랐으니 내 짐작은 틀린 것이다","mis":"K4-1-u1-X40"}],"explanation":["뜻밖의 내용인가요?","③을 봐요.","짐작하지 못한 것이에요."],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_challenge#1','kor',4,1,'u1','L09','g4_1_kor_u1_L09_challenge','lesson_challenge','K4-1-u1-C43',2,'mc','auto','「우리 반 텃밭 일기」의 차례 「싹이 나지 않는 두 줄」을 보고 만든 질문으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X34','K4-1-u1-X37']::text[],false,'{"seq":1,"concept":"K4-1-u1-C43","difficulty":2,"kind":"mc","stem":"「우리 반 텃밭 일기」의 차례 「싹이 나지 않는 두 줄」을 보고 만든 질문으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"왜 두 줄에만 싹이 나지 않았을까?","correct":true},{"t":"이 책은 모두 몇 쪽일까?","mis":"K4-1-u1-X34"},{"t":"차례는 건너뛰고 바로 첫 쪽을 읽을까?","mis":"K4-1-u1-X37"},{"t":"「상추」는 몇 글자일까?","mis":"K4-1-u1-X34"}],"explanation":["차례 하나하나가 질문거리","무엇이 궁금한가요?","까닭을 물어요."],"asset":{"type":"passage","lines":["제목: 우리 반 텃밭 일기","차례 1. 빈 땅을 고른 날","차례 2. 싹이 나지 않는 두 줄","차례 3. 물을 나누어 주기로 한 약속","차례 4. 함께 거둔 상추"],"title":"읽기 전 — 우리 반이 만든 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_challenge#2','kor',4,1,'u1','L09','g4_1_kor_u1_L09_challenge','lesson_challenge','K4-1-u1-C42',2,'mc','auto','「우리 반 텃밭 일기」라는 제목을 보고 짐작한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X04','K4-1-u1-X37']::text[],false,'{"seq":2,"concept":"K4-1-u1-C42","difficulty":2,"kind":"mc","stem":"「우리 반 텃밭 일기」라는 제목을 보고 짐작한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"우리 반이 텃밭을 가꾸며 겪은 일을 적은 글일 것이다","correct":true},{"t":"채소 이름만 모두 늘어놓은 글일 것이다","mis":"K4-1-u1-X04"},{"t":"일기 쓰는 방법을 알려 주는 글일 것이다","mis":"K4-1-u1-X04"},{"t":"제목은 내용과 상관이 없을 것이다","mis":"K4-1-u1-X37"}],"explanation":["「우리 반」 · 「텃밭」 · 「일기」","세 낱말을 합쳐 봐요.","겪은 일을 적었어요."],"asset":{"type":"passage","lines":["제목: 우리 반 텃밭 일기","차례 1. 빈 땅을 고른 날","차례 2. 싹이 나지 않는 두 줄","차례 3. 물을 나누어 주기로 한 약속","차례 4. 함께 거둔 상추"],"title":"읽기 전 — 우리 반이 만든 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_challenge#3','kor',4,1,'u1','L09','g4_1_kor_u1_L09_challenge','lesson_challenge','K4-1-u1-C43',3,'mc','auto','차례 2와 3을 이어서 짐작한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X04','K4-1-u1-X37']::text[],false,'{"seq":3,"concept":"K4-1-u1-C43","difficulty":3,"kind":"mc","stem":"차례 2와 3을 이어서 짐작한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"싹이 나지 않은 두 줄에 물이 모자라서 물을 나누어 주기로 약속했을 것이다","correct":true},{"t":"차례 3은 텃밭과 상관없는 다른 이야기일 것이다","mis":"K4-1-u1-X04"},{"t":"차례만으로는 아무것도 짐작할 수 없다","mis":"K4-1-u1-X37"},{"t":"물을 아끼려고 아무 데도 물을 주지 않기로 했을 것이다","mis":"K4-1-u1-X04"}],"explanation":["차례 2에서 무슨 일이?","차례 3은 그다음이에요.","앞뒤를 이어요."],"asset":{"type":"passage","lines":["제목: 우리 반 텃밭 일기","차례 1. 빈 땅을 고른 날","차례 2. 싹이 나지 않는 두 줄","차례 3. 물을 나누어 주기로 한 약속","차례 4. 함께 거둔 상추"],"title":"읽기 전 — 우리 반이 만든 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_challenge#4','kor',4,1,'u1','L09','g4_1_kor_u1_L09_challenge','lesson_challenge','K4-1-u1-C47',3,'mc','auto','「씨앗이 힘을 잃는다는 것은 무슨 뜻일까?」라는 질문에 글에서 찾은 답으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X42','K4-1-u1-X38']::text[],false,'{"seq":4,"concept":"K4-1-u1-C47","difficulty":3,"kind":"mc","stem":"「씨앗이 힘을 잃는다는 것은 무슨 뜻일까?」라는 질문에 글에서 찾은 답으로 알맞은 것은 무엇인가요?","options":[{"t":"심고 거두기를 거듭하지 않으면 씨앗이 제대로 자라지 못하게 된다는 뜻","correct":true},{"t":"씨앗이 무거워진다는 뜻","mis":"K4-1-u1-X42"},{"t":"글에 답이 없으니 넘어간다","mis":"K4-1-u1-X42"},{"t":"냉동실에 두면 씨앗이 더 힘이 세진다는 뜻","mis":"K4-1-u1-X38"}],"explanation":["⑥을 봐요.","「거듭하지 않으면」","글에서 답을 찾아요."],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_challenge#5','kor',4,1,'u1','L09','g4_1_kor_u1_L09_challenge','lesson_challenge','K4-1-u1-C48',3,'mc','auto','짐작 「씨앗을 지키려고 애쓰는 사람들 이야기」와 글을 견주었어요. 같은 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X41','K4-1-u1-X42']::text[],false,'{"seq":5,"concept":"K4-1-u1-C48","difficulty":3,"kind":"mc","stem":"짐작 「씨앗을 지키려고 애쓰는 사람들 이야기」와 글을 견주었어요. 같은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"씨앗을 지키려는 사람들의 이야기라는 점이 같았다","correct":true},{"t":"짐작과 글의 글자 크기가 같았다","mis":"K4-1-u1-X41"},{"t":"짐작과 글에 나온 그림 수가 같았다","mis":"K4-1-u1-X41"},{"t":"짐작이 맞았으니 글은 끝까지 읽지 않아도 되었다","mis":"K4-1-u1-X42"}],"explanation":["내용끼리 견줘요.","⑦ · ⑧을 봐요.","지키려는 사람들"],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_challenge#6','kor',4,1,'u1','L09','g4_1_kor_u1_L09_challenge','lesson_challenge','K4-1-u1-C45',3,'mc','auto','씨앗을 냉동실에 넣어 두는 것만으로는 모자란 까닭은 무엇인가요?',ARRAY['K4-1-u1-X39','K4-1-u1-X38']::text[],false,'{"seq":6,"concept":"K4-1-u1-C45","difficulty":3,"kind":"mc","stem":"씨앗을 냉동실에 넣어 두는 것만으로는 모자란 까닭은 무엇인가요?","options":[{"t":"얼마 동안은 지키지만 심고 거두기를 거듭하지 않으면 끝내 힘을 잃어서","correct":true},{"t":"냉동실은 전기가 많이 들어서","mis":"K4-1-u1-X39"},{"t":"씨앗은 밖에서 사 오면 되니까","mis":"K4-1-u1-X38"},{"t":"냉동실에 넣으면 씨앗이 바로 죽어서","mis":"K4-1-u1-X39"}],"explanation":["⑤와 ⑥을 이어 봐요.","「그러나」 뒤를 봐요.","거듭해야 살아요."],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_challenge#7','kor',4,1,'u1','L09','g4_1_kor_u1_L09_challenge','lesson_challenge','K4-1-u1-C44',3,'mc','auto','글에 따르면 씨앗이 사라지면 함께 사라지는 것은 무엇인가요?',ARRAY['K4-1-u1-X39']::text[],false,'{"seq":7,"concept":"K4-1-u1-C44","difficulty":3,"kind":"mc","stem":"글에 따르면 씨앗이 사라지면 함께 사라지는 것은 무엇인가요?","options":[{"t":"그 씨앗에 담긴 우리의 역사","correct":true},{"t":"냉동실","mis":"K4-1-u1-X39"},{"t":"씨앗을 파는 가게","mis":"K4-1-u1-X39"},{"t":"아무것도 함께 사라지지 않는다","mis":"K4-1-u1-X39"}],"explanation":["④를 봐요.","씨앗에 무엇이 담겼나요?","우리의 역사예요."],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_challenge#8','kor',4,1,'u1','L09','g4_1_kor_u1_L09_challenge','lesson_challenge','K4-1-u1-C42',4,'essay','teacher','「우리 반 텃밭 일기」의 제목과 차례를 보고 내용을 짐작하는 질문을 두 개 만들고, 그 질문으로 짐작한 내용을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u1-C42","difficulty":4,"kind":"essay","stem":"「우리 반 텃밭 일기」의 제목과 차례를 보고 내용을 짐작하는 질문을 두 개 만들고, 그 질문으로 짐작한 내용을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 질문 — 「싹이 나지 않은 두 줄에는 무슨 일이 있었을까?」 「물을 나누어 주기로 한 약속은 누가 했을까?」 짐작 — 우리 반 아이들이 싹이 안 난 줄에 물이 모자란 것을 알고 물을 나누어 주기로 약속해서 마지막에 함께 상추를 거두었을 것이다.","scoring_points":["제목이나 차례에서 질문을 두 개 만들었는가","세는 질문이 아니라 내용을 묻는 질문인가","질문을 바탕으로 짐작한 내용을 썼는가"]},"explanation":["제목과 차례를 봐요.","내용을 물어요.","짐작까지 써요."],"asset":{"type":"passage","lines":["제목: 우리 반 텃밭 일기","차례 1. 빈 땅을 고른 날","차례 2. 싹이 나지 않는 두 줄","차례 3. 물을 나누어 주기로 한 약속","차례 4. 함께 거둔 상추"],"title":"읽기 전 — 우리 반이 만든 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_challenge#9','kor',4,1,'u1','L09','g4_1_kor_u1_L09_challenge','lesson_challenge','K4-1-u1-C48',4,'essay','teacher','「씨앗을 지키는 사람들」의 제목과 차례로 짐작한 내용과 실제 글을 견주어 같은 점 하나, 다른 점 하나를 쓰고, 다른 점을 어떻게 받아들이면 좋을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u1-C48","difficulty":4,"kind":"essay","stem":"「씨앗을 지키는 사람들」의 제목과 차례로 짐작한 내용과 실제 글을 견주어 같은 점 하나, 다른 점 하나를 쓰고, 다른 점을 어떻게 받아들이면 좋을지 쓰세요.","answer_guide":{"answer":"예: 같은 점 — 씨앗을 지키려는 사람들의 이야기라는 점. 다른 점 — 씨앗을 냉동실에 넣어 두기만 하면 안 되고 심고 거두기를 거듭해야 한다는 것은 짐작하지 못했다. 다른 점은 내가 잘못 읽은 것이 아니라 글을 읽고 새로 안 것으로 받아들이면 된다.","scoring_points":["같은 점을 내용으로 썼는가","다른 점을 내용으로 썼는가","다른 점을 새로 안 것으로 받아들였는가"]},"explanation":["나란히 놓아 봐요.","내용끼리 견줘요.","다른 점 = 새로 안 것"],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L09_challenge#10','kor',4,1,'u1','L09','g4_1_kor_u1_L09_challenge','lesson_challenge','K4-1-u1-C47',4,'essay','teacher','「씨앗을 지키는 사람들」을 읽으며 떠오른 질문을 하나 쓰고 글에서 찾은 답을 쓰세요. 그리고 글에서 답을 찾을 수 없는 질문이 생기면 어떻게 할지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u1-C47","difficulty":4,"kind":"essay","stem":"「씨앗을 지키는 사람들」을 읽으며 떠오른 질문을 하나 쓰고 글에서 찾은 답을 쓰세요. 그리고 글에서 답을 찾을 수 없는 질문이 생기면 어떻게 할지 쓰세요.","answer_guide":{"answer":"예: 질문 — 「조상들은 왜 어려워도 씨앗을 남겼을까?」 답 — 씨앗에 농사의 지혜가 담겨 있었기 때문이다(②). 글에 답이 없는 질문은 그냥 넘기지 않고 책이나 어른께 여쭈어 더 찾아볼 거리로 남겨 둔다.","scoring_points":["읽으며 떠오른 질문을 썼는가","글에서 찾은 답을 썼는가","답이 없는 질문을 더 찾아볼 거리로 남긴다고 썼는가"]},"explanation":["질문하고","글에서 답을 찾고","없으면 더 찾아봐요."],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
