INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_basic#2','kor',4,1,'u1','L11','g4_1_kor_u1_L11_basic','lesson_basic','K4-1-u1-C56',1,'mc','auto','바르게 쓴 문장은 무엇인가요?',ARRAY['K4-1-u1-X46']::text[],false,'{"seq":2,"concept":"K4-1-u1-C56","difficulty":1,"kind":"mc","stem":"바르게 쓴 문장은 무엇인가요?","options":[{"t":"우리는 같이 해돋이를 보았다.","correct":true},{"t":"우리는 가치 해돋이를 보았다.","mis":"K4-1-u1-X46"},{"t":"우리는 같이 해도지를 보았다.","mis":"K4-1-u1-X46"},{"t":"우리는 가치 해도지를 보았다.","mis":"K4-1-u1-X46"}],"explanation":["소리는 바뀌어도","쓸 때는 글자 그대로","같이 · 해돋이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_basic#3','kor',4,1,'u1','L11','g4_1_kor_u1_L11_basic','lesson_basic','K4-1-u1-C58',1,'mc','auto','「외롭다」와 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K4-1-u1-X49']::text[],false,'{"seq":3,"concept":"K4-1-u1-C58","difficulty":1,"kind":"mc","stem":"「외롭다」와 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"쓸쓸하다","correct":true},{"t":"즐겁다","mis":"K4-1-u1-X49"},{"t":"서운하다","mis":"K4-1-u1-X49"},{"t":"기쁘다","mis":"K4-1-u1-X49"}],"explanation":["혼자인 느낌이에요.","기쁨 · 외로움 · 서운함","쓸쓸하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_basic#4','kor',4,1,'u1','L11','g4_1_kor_u1_L11_basic','lesson_basic','K4-1-u1-C50',1,'mc','auto','장면 카드로 이야기를 만들 때 가장 먼저 놓으면 좋은 장면은 무엇인가요?',ARRAY['K4-1-u1-X15']::text[],false,'{"seq":4,"concept":"K4-1-u1-C50","difficulty":1,"kind":"mc","stem":"장면 카드로 이야기를 만들 때 가장 먼저 놓으면 좋은 장면은 무엇인가요?","options":[{"t":"㉰ 가방을 메고 집을 나선다","correct":true},{"t":"㉮ 웃으며 친구에게 이야기한다","mis":"K4-1-u1-X15"},{"t":"㉯ 교실에서 놀란 얼굴을 한다","mis":"K4-1-u1-X15"},{"t":"㉱ 책을 펼쳐 든다","mis":"K4-1-u1-X15"}],"explanation":["하루는 어디서 시작하나요?","시간의 흐름을 따라요.","집을 나서는 장면이에요."],"asset":{"type":"passage","lines":["㉮ 웃으며 친구에게 이야기한다","㉯ 교실에서 놀란 얼굴을 한다","㉰ 가방을 메고 집을 나선다","㉱ 책을 펼쳐 든다"],"title":"장면 카드 네 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
