INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_basic#6','kor',4,1,'u1','L11','g4_1_kor_u1_L11_basic','lesson_basic','K4-1-u1-C57',2,'mc','auto','「어디」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-1-u1-X48']::text[],false,'{"seq":6,"concept":"K4-1-u1-C57","difficulty":2,"kind":"mc","stem":"「어디」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[어디]","correct":true},{"t":"[어지]","mis":"K4-1-u1-X48"},{"t":"[어치]","mis":"K4-1-u1-X48"},{"t":"[얻이]","mis":"K4-1-u1-X48"}],"explanation":["ㄷ이 받침인가요?","받침이 아니에요.","그대로 [어디]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_basic#7','kor',4,1,'u1','L11','g4_1_kor_u1_L11_basic','lesson_basic','K4-1-u1-C52',2,'mc','auto','「누구일까 놀이」를 하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X44']::text[],false,'{"seq":7,"concept":"K4-1-u1-C52","difficulty":2,"kind":"mc","stem":"「누구일까 놀이」를 하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"차례에 인물의 이름이 나오면 □로 가린다","correct":true},{"t":"시작하기 전에 정답을 먼저 알려 준다","mis":"K4-1-u1-X44"},{"t":"책의 마지막 쪽을 펴서 보여 준다","mis":"K4-1-u1-X44"},{"t":"인물의 이름이 보이게 그대로 둔다","mis":"K4-1-u1-X44"}],"explanation":["짐작할 거리가 있어야 해요.","답을 미리 알려 주면?","이름은 □로 가려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_basic#8','kor',4,1,'u1','L11','g4_1_kor_u1_L11_basic','lesson_basic','K4-1-u1-C52',2,'mc','auto','이 차례는 누구에 대한 이야기일까요?',ARRAY['K4-1-u1-X04','K4-1-u1-X16']::text[],false,'{"seq":8,"concept":"K4-1-u1-C52","difficulty":2,"kind":"mc","stem":"이 차례는 누구에 대한 이야기일까요?","options":[{"t":"장영실","correct":true},{"t":"이순신","mis":"K4-1-u1-X04"},{"t":"김정호","mis":"K4-1-u1-X04"},{"t":"석봉","mis":"K4-1-u1-X16"}],"explanation":["물시계를 만들었어요.","비의 양을 재는 그릇도요.","조선의 과학자예요."],"asset":{"type":"passage","lines":["1. 궁궐에 불려 간 젊은이","2. 스스로 시간을 알리는 물시계","3. 하늘의 별을 살피는 기구","4. 비의 양을 재는 그릇"],"title":"누구일까 — 어느 책의 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_basic#9','kor',4,1,'u1','L11','g4_1_kor_u1_L11_basic','lesson_basic','K4-1-u1-C53',2,'mc','auto','「깊이 있게 읽어요」에서 배운 것을 바르게 정리한 것은 무엇인가요?',ARRAY['K4-1-u1-X01','K4-1-u1-X34']::text[],false,'{"seq":9,"concept":"K4-1-u1-C53","difficulty":2,"kind":"mc","stem":"「깊이 있게 읽어요」에서 배운 것을 바르게 정리한 것은 무엇인가요?","options":[{"t":"말과 행동 → 관계 / 일이 일어난 차례 → 흐름 / 질문 만들기 → 내용 짐작","correct":true},{"t":"말과 행동 → 흐름 / 일이 일어난 차례 → 관계 / 질문 만들기 → 내용 짐작","mis":"K4-1-u1-X01"},{"t":"글자 수 세기 → 관계 / 쪽수 세기 → 흐름 / 질문 만들기 → 내용 짐작","mis":"K4-1-u1-X34"},{"t":"자음자 외우기 → 관계 / 두 자리 수 더하기 → 흐름 / 받아쓰기 → 내용 짐작","mis":"K4-1-u1-X01"}],"explanation":["인물 · 흐름 · 질문","무엇으로 무엇을?","세 짝을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_basic#10','kor',4,1,'u1','L11','g4_1_kor_u1_L11_basic','lesson_basic','K4-1-u1-C51',3,'mc','auto','장면 카드 네 장으로 만든 이야기의 첫 부분으로 가장 잘 쓴 것은 무엇인가요?',ARRAY['K4-1-u1-X43','K4-1-u1-X15']::text[],false,'{"seq":10,"concept":"K4-1-u1-C51","difficulty":3,"kind":"mc","stem":"장면 카드 네 장으로 만든 이야기의 첫 부분으로 가장 잘 쓴 것은 무엇인가요?","options":[{"t":"아침에 가방을 메고 집을 나섰다. 교실에 들어서자 나는 깜짝 놀랐다. \"어? 내 자리에 웬 책이지?\"","correct":true},{"t":"집을 나섰다. 놀랐다. 책을 폈다. 이야기했다.","mis":"K4-1-u1-X43"},{"t":"친구에게 웃으며 이야기했다. 그다음에 집을 나섰다.","mis":"K4-1-u1-X15"},{"t":"교실에서 무슨 일이 있었는지는 아무도 모른다. 끝.","mis":"K4-1-u1-X43"}],"explanation":["차례를 지켜요.","말과 행동을 넣어요.","이야기가 살아나요."],"asset":{"type":"passage","lines":["㉮ 웃으며 친구에게 이야기한다","㉯ 교실에서 놀란 얼굴을 한다","㉰ 가방을 메고 집을 나선다","㉱ 책을 펼쳐 든다"],"title":"장면 카드 네 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
