INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_challenge#4','kor',4,1,'u1','L11','g4_1_kor_u1_L11_challenge','lesson_challenge','K4-1-u1-C50',3,'mc','auto','장면 카드 네 장을 가장 자연스러운 차례로 놓은 것은 무엇인가요?',ARRAY['K4-1-u1-X15']::text[],false,'{"seq":4,"concept":"K4-1-u1-C50","difficulty":3,"kind":"mc","stem":"장면 카드 네 장을 가장 자연스러운 차례로 놓은 것은 무엇인가요?","options":[{"t":"㉰ → ㉯ → ㉱ → ㉮","correct":true},{"t":"㉰ → ㉱ → ㉮ → ㉯","mis":"K4-1-u1-X15"},{"t":"㉮ → ㉯ → ㉰ → ㉱","mis":"K4-1-u1-X15"},{"t":"㉯ → ㉰ → ㉱ → ㉮","mis":"K4-1-u1-X15"}],"explanation":["집을 나서고","놀란 일 → 까닭 알아보기","그다음 이야기해요."],"asset":{"type":"passage","lines":["㉮ 웃으며 친구에게 이야기한다","㉯ 교실에서 놀란 얼굴을 한다","㉰ 가방을 메고 집을 나선다","㉱ 책을 펼쳐 든다"],"title":"장면 카드 네 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_challenge#5','kor',4,1,'u1','L11','g4_1_kor_u1_L11_challenge','lesson_challenge','K4-1-u1-C56',3,'mc','auto','받아쓰기를 모두 바르게 한 것은 무엇인가요?',ARRAY['K4-1-u1-X46']::text[],false,'{"seq":5,"concept":"K4-1-u1-C56","difficulty":3,"kind":"mc","stem":"받아쓰기를 모두 바르게 한 것은 무엇인가요?","options":[{"t":"해돋이 · 굳히다 · 끝이","correct":true},{"t":"해도지 · 굳히다 · 끝이","mis":"K4-1-u1-X46"},{"t":"해돋이 · 구치다 · 끄치","mis":"K4-1-u1-X46"},{"t":"해도지 · 구치다 · 끄치","mis":"K4-1-u1-X46"}],"explanation":["소리 나는 대로 쓰지 않아요.","글자 그대로 써요.","해돋이 · 굳히다 · 끝이"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_challenge#6','kor',4,1,'u1','L11','g4_1_kor_u1_L11_challenge','lesson_challenge','K4-1-u1-C59',3,'mc','auto','「긴 줄넘기 연습」의 ④에서 민호의 마음을 나타내기에 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X03']::text[],false,'{"seq":6,"concept":"K4-1-u1-C59","difficulty":3,"kind":"mc","stem":"「긴 줄넘기 연습」의 ④에서 민호의 마음을 나타내기에 가장 알맞은 것은 무엇인가요?","options":[{"t":"서운하고 속상했을 것이다","correct":true},{"t":"즐겁고 신났을 것이다","mis":"K4-1-u1-X03"},{"t":"자랑스러웠을 것이다","mis":"K4-1-u1-X03"},{"t":"반가웠을 것이다","mis":"K4-1-u1-X03"}],"explanation":["③에서 무슨 말을 들었나요?","고개를 숙였어요.","서운했어요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_challenge#7','kor',4,1,'u1','L11','g4_1_kor_u1_L11_challenge','lesson_challenge','K4-1-u1-C58',3,'mc','auto','뜻이 비슷한 낱말끼리 바르게 짝 지은 것은 무엇인가요?',ARRAY['K4-1-u1-X49']::text[],false,'{"seq":7,"concept":"K4-1-u1-C58","difficulty":3,"kind":"mc","stem":"뜻이 비슷한 낱말끼리 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"기쁘다 – 즐겁다 / 외롭다 – 쓸쓸하다 / 섭섭하다 – 서운하다","correct":true},{"t":"기쁘다 – 쓸쓸하다 / 외롭다 – 즐겁다 / 섭섭하다 – 서운하다","mis":"K4-1-u1-X49"},{"t":"기쁘다 – 서운하다 / 외롭다 – 쓸쓸하다 / 섭섭하다 – 즐겁다","mis":"K4-1-u1-X49"},{"t":"기쁘다 – 즐겁다 / 외롭다 – 서운하다 / 섭섭하다 – 쓸쓸하다","mis":"K4-1-u1-X49"}],"explanation":["기쁨끼리","외로움끼리","서운함끼리"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_challenge#8','kor',4,1,'u1','L11','g4_1_kor_u1_L11_challenge','lesson_challenge','K4-1-u1-C51',4,'essay','teacher','장면 카드 네 장을 자연스러운 차례로 놓고, 인물의 말과 행동을 넣어 네다섯 문장의 이야기를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-1-u1-C51","difficulty":4,"kind":"essay","stem":"장면 카드 네 장을 자연스러운 차례로 놓고, 인물의 말과 행동을 넣어 네다섯 문장의 이야기를 쓰세요.","answer_guide":{"answer":"예: 아침에 나는 가방을 메고 집을 나섰다. 교실에 들어서자 깜짝 놀랐다. 내 책상 위에 처음 보는 그림책이 놓여 있었기 때문이다. 책을 펼쳐 보니 「생일 축하해!」라고 쓴 쪽지가 끼워져 있었다. 나는 웃으며 짝에게 「네가 준 거지?」 하고 말했다.","scoring_points":["장면을 자연스러운 차례(㉰ → ㉯ → ㉱ → ㉮)로 놓았는가","인물의 말이나 행동을 넣었는가","먼저 일어난 일과 나중 일이 이어지는가"]},"explanation":["시간의 흐름","말과 행동","이어지게"],"asset":{"type":"passage","lines":["㉮ 웃으며 친구에게 이야기한다","㉯ 교실에서 놀란 얼굴을 한다","㉰ 가방을 메고 집을 나선다","㉱ 책을 펼쳐 든다"],"title":"장면 카드 네 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_challenge#9','kor',4,1,'u1','L11','g4_1_kor_u1_L11_challenge','lesson_challenge','K4-1-u1-C52',4,'essay','teacher','내가 아는 이야기의 주인공 한 명을 골라 「누구일까 놀이」 문제를 만드세요. 차례를 세 줄로 쓰되 이름은 □로 가리고, 정답과 그 인물을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-1-u1-C52","difficulty":4,"kind":"essay","stem":"내가 아는 이야기의 주인공 한 명을 골라 「누구일까 놀이」 문제를 만드세요. 차례를 세 줄로 쓰되 이름은 □로 가리고, 정답과 그 인물을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 차례 — 1. 어둠 속에서 떡을 썬 어머니 2. 크기도 모양도 제각각인 글씨 3. 다시 한양으로 떠난 □□. 정답 — 석봉. 「석봉과 어머니」에서 일어난 중요한 일을 차례대로 담으면 친구가 짐작할 수 있기 때문이다.","scoring_points":["차례를 세 줄로 썼는가","인물의 이름을 □로 가렸는가","정답과 고른 까닭을 썼는가"]},"explanation":["중요한 일을 차례로","이름은 □로","정답은 마지막에"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_L11_challenge#10','kor',4,1,'u1','L11','g4_1_kor_u1_L11_challenge','lesson_challenge','K4-1-u1-C54',4,'essay','teacher','「같이」와 「굳히다」가 어떻게 소리 나는지 쓰고, 왜 그렇게 소리 나는지 쓰세요. 그리고 「어디」는 왜 소리가 바뀌지 않는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-1-u1-C54","difficulty":4,"kind":"essay","stem":"「같이」와 「굳히다」가 어떻게 소리 나는지 쓰고, 왜 그렇게 소리 나는지 쓰세요. 그리고 「어디」는 왜 소리가 바뀌지 않는지 쓰세요.","answer_guide":{"answer":"예: 같이는 [가치], 굳히다는 [구치다]로 소리 난다. 받침 ㅌ 뒤에 ㅣ가 오면 [ㅊ]으로, 받침 ㄷ 뒤에 히가 오면 [ㅊ]으로 바뀌어 소리 나기 때문이다. 어디는 ㄷ이 받침이 아니라 뒤 글자의 첫소리여서 바뀌지 않는다.","scoring_points":["같이·굳히다의 소리를 바르게 썼는가","받침 ㄷ·ㅌ 뒤에 ㅣ(히)가 올 때 바뀐다고 썼는가","어디는 ㄷ이 받침이 아니라서 바뀌지 않는다고 썼는가"]},"explanation":["[가치] · [구치다]","받침 뒤의 ㅣ · 히","어디의 ㄷ은?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#1','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C53',1,'mc','auto','단원을 마무리하며 물어요. 인물의 말과 행동을 살펴보면 무엇을 알 수 있나요?',ARRAY['K4-1-u1-X34','K4-1-u1-X01','K4-1-u1-X41']::text[],false,'{"seq":1,"concept":"K4-1-u1-C53","difficulty":1,"kind":"mc","stem":"단원을 마무리하며 물어요. 인물의 말과 행동을 살펴보면 무엇을 알 수 있나요?","options":[{"t":"인물들의 관계","correct":true},{"t":"책의 쪽수","mis":"K4-1-u1-X34"},{"t":"글을 읽는 데 걸린 시간","mis":"K4-1-u1-X01"},{"t":"글자의 크기","mis":"K4-1-u1-X41"}],"explanation":["2차시를 떠올려요.","말과 행동에 드러나요.","인물들의 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#2','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C3',1,'mc','auto','「콩쥐팥쥐」에서 콩쥐와 도와주는 관계인 인물로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X02','K4-1-u1-X11']::text[],false,'{"seq":2,"concept":"K4-1-u1-C3","difficulty":1,"kind":"mc","stem":"「콩쥐팥쥐」에서 콩쥐와 도와주는 관계인 인물로 알맞은 것은 무엇인가요?","options":[{"t":"두꺼비","correct":true},{"t":"팥쥐","mis":"K4-1-u1-X02"},{"t":"새어머니","mis":"K4-1-u1-X02"},{"t":"아무도 없다","mis":"K4-1-u1-X11"}],"explanation":["깨진 독을 어떻게 했나요?","구멍을 막아 주었어요.","두꺼비예요."],"asset":{"type":"passage","lines":["호미가 부러져 울고 있던 콩쥐에게 황소가 다가와 밭의 풀을 뽑아 주었다.","깨진 독에 물을 채워야 할 때는 두꺼비가 구멍을 막아 주었다.","새들은 벼를 대신 찧어 주었다.","팥쥐는 콩쥐를 괴롭혔고, 새어머니는 어려운 일만 시켰다."],"title":"콩쥐팥쥐"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#3','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C17',1,'mc','auto','이야기의 흐름을 정리할 때 따라가면 좋은 변화는 무엇인가요?',ARRAY['K4-1-u1-X41','K4-1-u1-X34','K4-1-u1-X17']::text[],false,'{"seq":3,"concept":"K4-1-u1-C17","difficulty":1,"kind":"mc","stem":"이야기의 흐름을 정리할 때 따라가면 좋은 변화는 무엇인가요?","options":[{"t":"시간과 장소의 변화","correct":true},{"t":"글자 크기의 변화","mis":"K4-1-u1-X41"},{"t":"쪽수의 변화","mis":"K4-1-u1-X34"},{"t":"읽는 내 기분의 변화","mis":"K4-1-u1-X17"}],"explanation":["언제 · 어디","바뀌는 곳을 따라가요.","시간과 장소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#4','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C38',1,'mc','auto','「다음 장에는 어떤 일이 일어날까?」는 어떤 갈래의 질문인가요?',ARRAY['K4-1-u1-X33','K4-1-u1-X34']::text[],false,'{"seq":4,"concept":"K4-1-u1-C38","difficulty":1,"kind":"mc","stem":"「다음 장에는 어떤 일이 일어날까?」는 어떤 갈래의 질문인가요?","options":[{"t":"이어질 내용을 짐작하는 질문","correct":true},{"t":"낱말의 뜻을 짐작하는 질문","mis":"K4-1-u1-X33"},{"t":"자신의 경험과 관련지은 질문","mis":"K4-1-u1-X33"},{"t":"쪽수를 세는 질문","mis":"K4-1-u1-X34"}],"explanation":["「다음」을 물어요.","앞으로 일어날 일","이어질 내용 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#5','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C54',1,'mc','auto','「같이」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-1-u1-X45']::text[],false,'{"seq":5,"concept":"K4-1-u1-C54","difficulty":1,"kind":"mc","stem":"「같이」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[가치]","correct":true},{"t":"[가티]","mis":"K4-1-u1-X45"},{"t":"[가지]","mis":"K4-1-u1-X45"},{"t":"[갇이]","mis":"K4-1-u1-X45"}],"explanation":["받침 ㅌ 뒤에 ㅣ","ㅌ이 [ㅊ]으로","[가치]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#6','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C56',1,'mc','auto','[해도지]로 소리 나는 낱말을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-1-u1-X46']::text[],false,'{"seq":6,"concept":"K4-1-u1-C56","difficulty":1,"kind":"mc","stem":"[해도지]로 소리 나는 낱말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"해돋이","correct":true},{"t":"해도지","mis":"K4-1-u1-X46"},{"t":"해돗이","mis":"K4-1-u1-X46"},{"t":"해돈이","mis":"K4-1-u1-X46"}],"explanation":["해가 돋는 것","돋 + 이","해돋이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#7','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C58',1,'mc','auto','「기쁘다」와 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K4-1-u1-X49']::text[],false,'{"seq":7,"concept":"K4-1-u1-C58","difficulty":1,"kind":"mc","stem":"「기쁘다」와 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"즐겁다","correct":true},{"t":"쓸쓸하다","mis":"K4-1-u1-X49"},{"t":"서운하다","mis":"K4-1-u1-X49"},{"t":"외롭다","mis":"K4-1-u1-X49"}],"explanation":["좋은 마음이에요.","기쁨끼리","즐겁다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#8','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C37',1,'mc','auto','「유지하다」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X20']::text[],false,'{"seq":8,"concept":"K4-1-u1-C37","difficulty":1,"kind":"mc","stem":"「유지하다」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"어떤 상태를 변함없이 이어 가다","correct":true},{"t":"간직하고 관리하다","mis":"K4-1-u1-X20"},{"t":"어떤 것에 자격을 주다","mis":"K4-1-u1-X20"},{"t":"식물을 심어 가꾸다","mis":"K4-1-u1-X20"}],"explanation":["옹기의 위와 아래 온도","비슷하게 이어 가요.","변함없이 이어 가다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#9','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C8',2,'mc','auto','무루의 성격을 알아보려고 해요. 무루의 단서로 모아야 할 것은 무엇인가요?',ARRAY['K4-1-u1-X07','K4-1-u1-X06']::text[],false,'{"seq":9,"concept":"K4-1-u1-C8","difficulty":2,"kind":"mc","stem":"무루의 성격을 알아보려고 해요. 무루의 단서로 모아야 할 것은 무엇인가요?","options":[{"t":"⑦ 앞장서서 흙의 떨림을 따라 모두를 이끌었다","correct":true},{"t":"② \"저래서야 굴길을 어떻게 찾아다니겠어?\"","mis":"K4-1-u1-X07"},{"t":"③ \"넌 앞도 못 보잖아. 저리 가!\"","mis":"K4-1-u1-X07"},{"t":"① 무루는 다른 두더지보다 눈이 훨씬 어두웠다","mis":"K4-1-u1-X06"}],"explanation":["무루가 한 행동인가요?","눈이 어두운 것은 성격이 아니에요.","⑦이에요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#10','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C10',2,'ox','auto','하준이와 태오는 처음부터 끝까지 갈등하는 관계예요.',ARRAY['K4-1-u1-X08']::text[],false,'{"seq":10,"concept":"K4-1-u1-C10","difficulty":2,"kind":"ox","stem":"하준이와 태오는 처음부터 끝까지 갈등하는 관계예요.","answer":"X","reason_options":[{"t":"⑧에서 태오가 하준이의 눈을 인정했기 때문에","correct":true},{"t":"한 번 갈등한 관계는 바뀌지 않기 때문에","mis":"K4-1-u1-X08"}],"mis":"K4-1-u1-X08","explanation":["끝 장면을 봐요.","태오가 인정했어요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#11','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C18',2,'mc','auto','「개미와 비둘기」의 흐름에 꼭 필요한 일은 무엇인가요?',ARRAY['K4-1-u1-X14']::text[],false,'{"seq":11,"concept":"K4-1-u1-C18","difficulty":2,"kind":"mc","stem":"「개미와 비둘기」의 흐름에 꼭 필요한 일은 무엇인가요?","options":[{"t":"② 비둘기가 나뭇잎을 떨어뜨려 개미를 구해 주었다","correct":true},{"t":"개미가 마시려던 물의 맛","mis":"K4-1-u1-X14"},{"t":"비둘기가 앉아 있던 나무의 이름","mis":"K4-1-u1-X14"},{"t":"사냥꾼이 입은 옷의 색","mis":"K4-1-u1-X14"}],"explanation":["빠지면 이어지나요?","구해 준 일이 있어야","개미가 갚을 수 있어요."],"asset":{"type":"passage","lines":["① 어느 날, 개미가 물을 마시러 갔다가 발을 헛디뎌 물에 빠졌다.","② 나무 위에 있던 비둘기가 이를 보고 나뭇잎 하나를 떨어뜨려 개미를 구해 주었다.","③ 며칠 뒤, 사냥꾼이 비둘기를 잡으려고 그물을 던졌다.","④ 그 순간 개미가 사냥꾼의 발을 물어 비둘기를 구해 주었다."],"title":"개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#12','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C21',2,'mc','auto','「긴 줄넘기 연습」의 일을 일어난 차례대로 놓은 것은 무엇인가요?',ARRAY['K4-1-u1-X15']::text[],false,'{"seq":12,"concept":"K4-1-u1-C21","difficulty":2,"kind":"mc","stem":"「긴 줄넘기 연습」의 일을 일어난 차례대로 놓은 것은 무엇인가요?","options":[{"t":"민호가 줄에 걸림 → 수아가 빠지라고 함 → 은채가 구령을 맡기자고 함 → 대회 날 끝까지 넘음","correct":true},{"t":"수아가 빠지라고 함 → 민호가 줄에 걸림 → 은채가 구령을 맡기자고 함 → 대회 날 끝까지 넘음","mis":"K4-1-u1-X15"},{"t":"민호가 줄에 걸림 → 은채가 구령을 맡기자고 함 → 수아가 빠지라고 함 → 대회 날 끝까지 넘음","mis":"K4-1-u1-X15"},{"t":"민호가 줄에 걸림 → 대회 날 끝까지 넘음 → 수아가 빠지라고 함 → 은채가 구령을 맡기자고 함","mis":"K4-1-u1-X15"}],"explanation":["걸려야 빠지라고 해요.","빠진 뒤에 구령을","그다음 대회예요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#13','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C40',2,'mc','auto','「긴 줄넘기 연습」의 내용을 짐작하는 데 도움이 되는 질문은 무엇인가요?',ARRAY['K4-1-u1-X34','K4-1-u1-X36']::text[],false,'{"seq":13,"concept":"K4-1-u1-C40","difficulty":2,"kind":"mc","stem":"「긴 줄넘기 연습」의 내용을 짐작하는 데 도움이 되는 질문은 무엇인가요?","options":[{"t":"수아는 왜 마지막에 미안하다고 했을까?","correct":true},{"t":"이 글은 모두 몇 문장일까?","mis":"K4-1-u1-X34"},{"t":"「줄」이라는 글자가 몇 번 나올까?","mis":"K4-1-u1-X34"},{"t":"수아에 대한 질문을 스무 개 만들까?","mis":"K4-1-u1-X36"}],"explanation":["세는 질문은 빼요.","개수보다 내용","「왜?」를 물어요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#14','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C34',2,'mc','auto','「돌다리를 놓은 아이」라는 제목만 보았을 때 만들 수 있는 질문은 무엇인가요?',ARRAY['K4-1-u1-X30','K4-1-u1-X34']::text[],false,'{"seq":14,"concept":"K4-1-u1-C34","difficulty":2,"kind":"mc","stem":"「돌다리를 놓은 아이」라는 제목만 보았을 때 만들 수 있는 질문은 무엇인가요?","options":[{"t":"아이는 왜 돌다리를 놓았을까?","correct":true},{"t":"「넓적한」은 무슨 뜻일까?","mis":"K4-1-u1-X30"},{"t":"감나무는 어디에 서 있었을까?","mis":"K4-1-u1-X30"},{"t":"이 이야기는 몇 쪽일까?","mis":"K4-1-u1-X34"}],"explanation":["아직 본문을 안 읽었어요.","넓적한 · 감나무는 본문에 나와요.","제목에서 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#15','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C57',2,'mc','auto','「마디」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-1-u1-X48']::text[],false,'{"seq":15,"concept":"K4-1-u1-C57","difficulty":2,"kind":"mc","stem":"「마디」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[마디]","correct":true},{"t":"[마지]","mis":"K4-1-u1-X48"},{"t":"[마치]","mis":"K4-1-u1-X48"},{"t":"[맏이]","mis":"K4-1-u1-X48"}],"explanation":["ㄷ이 받침인가요?","첫소리예요.","그대로 [마디]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#16','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C59',2,'blank','auto','「오랜만에 할머니를 만나 마음이 (   ).」의 빈칸에 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X03']::text[],false,'{"seq":16,"concept":"K4-1-u1-C59","difficulty":2,"kind":"blank","stem":"「오랜만에 할머니를 만나 마음이 (   ).」의 빈칸에 가장 알맞은 것은 무엇인가요?","options":[{"t":"기뻤다","correct":true},{"t":"쓸쓸했다","mis":"K4-1-u1-X03"},{"t":"서운했다","mis":"K4-1-u1-X03"},{"t":"외로웠다","mis":"K4-1-u1-X03"}],"explanation":["무슨 일을 겪었나요?","반가운 만남","기뻤어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#17','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C16',3,'mc','auto','「눈이 어두운 두더지 무루」를 가장 잘 정리한 것은 무엇인가요?',ARRAY['K4-1-u1-X13','K4-1-u1-X12','K4-1-u1-X17']::text[],false,'{"seq":17,"concept":"K4-1-u1-C16","difficulty":3,"kind":"mc","stem":"「눈이 어두운 두더지 무루」를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"눈이 어두워 따돌림받던 무루가 큰비 온 밤 흙의 떨림을 느껴 모두를 구했다.","correct":true},{"t":"무루가 있었다.","mis":"K4-1-u1-X13"},{"t":"언덕 마을에 무루가 태어났는데 눈이 어두웠고, 두더지들이 호들갑을 떨었고, 또래 두더지들이⋯⋯","mis":"K4-1-u1-X12"},{"t":"마루가 가슴이 아팠다.","mis":"K4-1-u1-X17"}],"explanation":["너무 짧지 않게","너무 자세하지 않게","중요한 일을 차례대로"],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#18','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C31',3,'mc','auto','「긴 줄넘기 연습」에서 전하고 싶은 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X25','K4-1-u1-X26']::text[],false,'{"seq":18,"concept":"K4-1-u1-C31","difficulty":3,"kind":"mc","stem":"「긴 줄넘기 연습」에서 전하고 싶은 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"잘하지 못하는 것만 보지 말고 그 사람이 잘하는 것을 찾아 주자","correct":true},{"t":"줄넘기는 날마다 연습해야 한다","mis":"K4-1-u1-X25"},{"t":"목소리가 크면 대회에서 이긴다","mis":"K4-1-u1-X25"},{"t":"잘하지 못하는 사람은 빠지는 것이 낫다","mis":"K4-1-u1-X26"}],"explanation":["작은 사실에서 찾지 않아요.","흐름 전체를 봐요.","민호의 다른 재주"],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#19','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C49',3,'mc','auto','「바람이 드나드는 종이」를 읽기 전에 「한지는 얇아서 잘 찢어질 것이다」라고 짐작했어요. 글을 읽은 뒤 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X40','K4-1-u1-X41']::text[],false,'{"seq":19,"concept":"K4-1-u1-C49","difficulty":3,"kind":"mc","stem":"「바람이 드나드는 종이」를 읽기 전에 「한지는 얇아서 잘 찢어질 것이다」라고 짐작했어요. 글을 읽은 뒤 알맞은 것은 무엇인가요?","options":[{"t":"한지가 질겨서 잘 찢어지지 않는다는 것을 새로 알았다고 정리한다","correct":true},{"t":"짐작이 틀렸으니 처음부터 잘못 읽은 것이다","mis":"K4-1-u1-X40"},{"t":"짐작에 맞게 「잘 찢어진다」로 기억해 둔다","mis":"K4-1-u1-X40"},{"t":"짐작과 글의 글자 수를 견주어 본다","mis":"K4-1-u1-X41"}],"explanation":["②를 봐요.","짐작과 달라요.","다른 점 = 새로 안 것"],"asset":{"type":"passage","lines":["① 한지는 닥나무 껍질로 만든 우리 종이이다.","② 한지는 질겨서 잘 찢어지지 않는다.","③ 또 종이 사이로 바람이 잘 드나든다.","④ 그래서 옛날 사람들은 한지를 문에 발라 썼다."],"title":"바람이 드나드는 종이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#20','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C41',3,'mc','auto','「석봉과 어머니」를 더 깊이 보게 하는 질문은 무엇인가요?',ARRAY['K4-1-u1-X35','K4-1-u1-X36']::text[],false,'{"seq":20,"concept":"K4-1-u1-C41","difficulty":3,"kind":"mc","stem":"「석봉과 어머니」를 더 깊이 보게 하는 질문은 무엇인가요?","options":[{"t":"어머니는 왜 반가운 아들을 그날로 돌려보냈을까?","correct":true},{"t":"석봉은 어디에서 공부했나요?","mis":"K4-1-u1-X35"},{"t":"어머니는 어둠 속에서 무엇을 했나요?","mis":"K4-1-u1-X35"},{"t":"석봉 이야기로 질문을 서른 개 만들까?","mis":"K4-1-u1-X36"}],"explanation":["답이 그대로 있나요?","빈 곳을 메워요.","「왜?」를 물어요."],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#21','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C52',3,'mc','auto','「석봉과 어머니」로 누구일까 놀이 문제를 내려고 해요. 차례로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X44','K4-1-u1-X34']::text[],false,'{"seq":21,"concept":"K4-1-u1-C52","difficulty":3,"kind":"mc","stem":"「석봉과 어머니」로 누구일까 놀이 문제를 내려고 해요. 차례로 가장 알맞은 것은 무엇인가요?","options":[{"t":"1. 3년 만의 귀향 2. 꺼진 호롱불 3. 다시 한양으로 떠난 □□","correct":true},{"t":"1. 석봉의 귀향 2. 석봉과 호롱불 3. 석봉의 공부","mis":"K4-1-u1-X44"},{"t":"정답은 석봉입니다. 1. 귀향 2. 호롱불","mis":"K4-1-u1-X44"},{"t":"1. 이 책은 120쪽 2. 그림은 10장","mis":"K4-1-u1-X34"}],"explanation":["이름은 □로","정답은 미리 말하지 않아요.","중요한 일을 차례로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#22','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C30',3,'mc','auto','「미술 시간에 생긴 일」의 흐름을 관계를 중심으로 바르게 정리한 것은 무엇인가요?',ARRAY['K4-1-u1-X27','K4-1-u1-X15','K4-1-u1-X16']::text[],false,'{"seq":22,"concept":"K4-1-u1-C30","difficulty":3,"kind":"mc","stem":"「미술 시간에 생긴 일」의 흐름을 관계를 중심으로 바르게 정리한 것은 무엇인가요?","options":[{"t":"태오와 하준이의 갈등 → 서아의 도움 → 하준이가 바탕을 칠함 → 태오의 인정","correct":true},{"t":"태오와 하준이의 갈등 → 깃발 완성","mis":"K4-1-u1-X27"},{"t":"서아의 도움 → 태오와 하준이의 갈등 → 태오의 인정 → 하준이가 바탕을 칠함","mis":"K4-1-u1-X15"},{"t":"하준이가 깃발 그림을 그림 → 태오가 그림을 칭찬함","mis":"K4-1-u1-X16"}],"explanation":["관계가 바뀐 곳을 넣어요.","차례를 지켜요.","갈등 → 도움 → 인정"],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#23','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C12',4,'essay','teacher','「콩쥐팥쥐」에서 콩쥐와 도와주는 관계인 인물과 갈등하는 관계인 인물을 하나씩 골라 쓰고, 각각 그렇게 생각한 말이나 행동을 근거로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u1-C12","difficulty":4,"kind":"essay","stem":"「콩쥐팥쥐」에서 콩쥐와 도와주는 관계인 인물과 갈등하는 관계인 인물을 하나씩 골라 쓰고, 각각 그렇게 생각한 말이나 행동을 근거로 쓰세요.","answer_guide":{"answer":"예: 도와주는 관계 — 황소. 호미가 부러져 울고 있는 콩쥐에게 다가와 밭의 풀을 뽑아 주었기 때문이다. 갈등하는 관계 — 팥쥐. 콩쥐를 괴롭혔기 때문이다.","scoring_points":["도와주는 관계인 인물을 바르게 골랐는가","갈등하는 관계인 인물을 바르게 골랐는가","각각 말이나 행동을 근거로 썼는가"]},"explanation":["누가 거들었나요?","누가 괴롭혔나요?","근거도 함께"],"asset":{"type":"passage","lines":["호미가 부러져 울고 있던 콩쥐에게 황소가 다가와 밭의 풀을 뽑아 주었다.","깨진 독에 물을 채워야 할 때는 두꺼비가 구멍을 막아 주었다.","새들은 벼를 대신 찧어 주었다.","팥쥐는 콩쥐를 괴롭혔고, 새어머니는 어려운 일만 시켰다."],"title":"콩쥐팥쥐"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#24','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C16',4,'essay','teacher','「개미와 비둘기」의 흐름을 두 문장으로 정리하고, 「개미와 비둘기가 서로 도와주었다.」라고만 정리하면 부족한 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u1-C16","difficulty":4,"kind":"essay","stem":"「개미와 비둘기」의 흐름을 두 문장으로 정리하고, 「개미와 비둘기가 서로 도와주었다.」라고만 정리하면 부족한 까닭을 쓰세요.","answer_guide":{"answer":"예: 물에 빠진 개미를 비둘기가 나뭇잎을 떨어뜨려 구해 주었다. 며칠 뒤 사냥꾼이 비둘기에게 그물을 던지자 개미가 사냥꾼의 발을 물어 비둘기를 구해 주었다. 「서로 도와주었다」는 너무 짧아서 누가 어떻게 도왔는지, 어떤 차례로 일어났는지 알 수 없기 때문이다.","scoring_points":["중요한 일을 두 문장으로 정리했는가","일이 일어난 차례대로 썼는가","너무 짧으면 내용을 알 수 없다는 까닭을 썼는가"]},"explanation":["중요한 두 일","차례대로","너무 짧으면?"],"asset":{"type":"passage","lines":["① 어느 날, 개미가 물을 마시러 갔다가 발을 헛디뎌 물에 빠졌다.","② 나무 위에 있던 비둘기가 이를 보고 나뭇잎 하나를 떨어뜨려 개미를 구해 주었다.","③ 며칠 뒤, 사냥꾼이 비둘기를 잡으려고 그물을 던졌다.","④ 그 순간 개미가 사냥꾼의 발을 물어 비둘기를 구해 주었다."],"title":"개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_a#25','kor',4,1,'u1','','g4_1_kor_u1_review_a','unit_review','K4-1-u1-C47',4,'essay','teacher','「바람이 드나드는 종이」를 읽기 전에 제목을 보고 만든 질문 하나와, 읽는 중에 떠오른 질문 하나를 쓰고, 각 질문의 답을 글에서 찾아 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u1-C47","difficulty":4,"kind":"essay","stem":"「바람이 드나드는 종이」를 읽기 전에 제목을 보고 만든 질문 하나와, 읽는 중에 떠오른 질문 하나를 쓰고, 각 질문의 답을 글에서 찾아 쓰세요.","answer_guide":{"answer":"예: 읽기 전 — 「어떤 종이이기에 바람이 드나들까?」 → 종이 사이로 바람이 잘 드나드는 한지이다(③). 읽는 중 — 「한지를 왜 문에 발랐을까?」 → 질기고 바람이 잘 드나들기 때문이다(②·③·④).","scoring_points":["제목을 보고 만든 읽기 전 질문을 썼는가","읽는 중에 떠오른 질문을 썼는가","각 질문의 답을 글에서 찾아 썼는가"]},"explanation":["제목 → 질문","읽는 중 → 질문","글에서 답 찾기"],"asset":{"type":"passage","lines":["① 한지는 닥나무 껍질로 만든 우리 종이이다.","② 한지는 질겨서 잘 찢어지지 않는다.","③ 또 종이 사이로 바람이 잘 드나든다.","④ 그래서 옛날 사람들은 한지를 문에 발라 썼다."],"title":"바람이 드나드는 종이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#1','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C53',1,'mc','auto','일이 일어난 차례를 정리하면 무엇을 파악할 수 있나요?',ARRAY['K4-1-u1-X06','K4-1-u1-X34','K4-1-u1-X01']::text[],false,'{"seq":1,"concept":"K4-1-u1-C53","difficulty":1,"kind":"mc","stem":"일이 일어난 차례를 정리하면 무엇을 파악할 수 있나요?","options":[{"t":"이야기의 흐름","correct":true},{"t":"인물의 생김새","mis":"K4-1-u1-X06"},{"t":"이야기의 글자 수","mis":"K4-1-u1-X34"},{"t":"책의 값","mis":"K4-1-u1-X01"}],"explanation":["차례대로 흘러가요.","흐름을 따라가요.","이야기의 흐름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#2','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C4',1,'mc','auto','「미술 시간에 생긴 일」의 처음 장면에서 하준이와 갈등하는 관계인 인물은 누구인가요?',ARRAY['K4-1-u1-X02','K4-1-u1-X11']::text[],false,'{"seq":2,"concept":"K4-1-u1-C4","difficulty":1,"kind":"mc","stem":"「미술 시간에 생긴 일」의 처음 장면에서 하준이와 갈등하는 관계인 인물은 누구인가요?","options":[{"t":"태오","correct":true},{"t":"서아","mis":"K4-1-u1-X02"},{"t":"하준이 자신","mis":"K4-1-u1-X11"},{"t":"깃발을 본 아이들","mis":"K4-1-u1-X02"}],"explanation":["②와 ⑤를 봐요.","색칠만 하라고 했어요.","태오예요."],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#3','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C15',1,'mc','auto','읽은 이야기의 흐름을 친구에게 전할 때 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X12','K4-1-u1-X13','K4-1-u1-X15']::text[],false,'{"seq":3,"concept":"K4-1-u1-C15","difficulty":1,"kind":"mc","stem":"읽은 이야기의 흐름을 친구에게 전할 때 알맞은 것은 무엇인가요?","options":[{"t":"중요한 일만 차례대로 전한다","correct":true},{"t":"생각나는 일을 모두 전한다","mis":"K4-1-u1-X12"},{"t":"마지막 장면 하나만 전한다","mis":"K4-1-u1-X13"},{"t":"차례를 섞어 재미있게 전한다","mis":"K4-1-u1-X15"}],"explanation":["다 말하면 헷갈려요.","하나만 말하면 몰라요.","중요한 일을 차례대로"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#4','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C38',1,'mc','auto','「보관하다는 무슨 뜻일까?」는 어떤 갈래의 질문인가요?',ARRAY['K4-1-u1-X33','K4-1-u1-X34']::text[],false,'{"seq":4,"concept":"K4-1-u1-C38","difficulty":1,"kind":"mc","stem":"「보관하다는 무슨 뜻일까?」는 어떤 갈래의 질문인가요?","options":[{"t":"낱말의 뜻을 짐작하는 질문","correct":true},{"t":"자신의 경험과 관련지은 질문","mis":"K4-1-u1-X33"},{"t":"더 궁금한 점을 묻는 질문","mis":"K4-1-u1-X33"},{"t":"글자 수를 세는 질문","mis":"K4-1-u1-X34"}],"explanation":["「무슨 뜻」","낱말을 물어요.","낱말의 뜻 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#5','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C54',1,'mc','auto','「끝이」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-1-u1-X45']::text[],false,'{"seq":5,"concept":"K4-1-u1-C54","difficulty":1,"kind":"mc","stem":"「끝이」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[끄치]","correct":true},{"t":"[끄티]","mis":"K4-1-u1-X45"},{"t":"[끄지]","mis":"K4-1-u1-X45"},{"t":"[끝이]","mis":"K4-1-u1-X45"}],"explanation":["받침 ㅌ 뒤에 ㅣ","[ㅊ]으로 바뀌어요.","[끄치]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#6','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C56',1,'mc','auto','[가치]로 소리 나는 낱말을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-1-u1-X46']::text[],false,'{"seq":6,"concept":"K4-1-u1-C56","difficulty":1,"kind":"mc","stem":"[가치]로 소리 나는 낱말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"같이","correct":true},{"t":"가치","mis":"K4-1-u1-X46"},{"t":"갇이","mis":"K4-1-u1-X46"},{"t":"갓이","mis":"K4-1-u1-X46"}],"explanation":["「같다」에서 왔어요.","받침 ㅌ","같이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#7','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C58',1,'mc','auto','「섭섭하다」와 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K4-1-u1-X49']::text[],false,'{"seq":7,"concept":"K4-1-u1-C58","difficulty":1,"kind":"mc","stem":"「섭섭하다」와 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"서운하다","correct":true},{"t":"즐겁다","mis":"K4-1-u1-X49"},{"t":"쓸쓸하다","mis":"K4-1-u1-X49"},{"t":"기쁘다","mis":"K4-1-u1-X49"}],"explanation":["기대에 못 미친 마음","서운함끼리","서운하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#8','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C46',1,'mc','auto','「거듭하다」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X20']::text[],false,'{"seq":8,"concept":"K4-1-u1-C46","difficulty":1,"kind":"mc","stem":"「거듭하다」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"어떤 일을 자꾸 되풀이하다","correct":true},{"t":"충분히 잘 이용하다","mis":"K4-1-u1-X20"},{"t":"식물을 심어 가꾸다","mis":"K4-1-u1-X20"},{"t":"간직하고 관리하다","mis":"K4-1-u1-X20"}],"explanation":["심고 거두기를⋯⋯","한 번이 아니라 여러 번","되풀이하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#9','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C8',2,'mc','auto','은채의 성격을 알아보려고 해요. 은채의 단서로 모아야 할 것은 무엇인가요?',ARRAY['K4-1-u1-X07']::text[],false,'{"seq":9,"concept":"K4-1-u1-C8","difficulty":2,"kind":"mc","stem":"은채의 성격을 알아보려고 해요. 은채의 단서로 모아야 할 것은 무엇인가요?","options":[{"t":"⑤ \"네가 구령을 붙여 주면 어때?\"","correct":true},{"t":"③ \"민호 너는 빠지는 게 낫겠어.\"","mis":"K4-1-u1-X07"},{"t":"⑧ \"네 구령 덕분이야.\"","mis":"K4-1-u1-X07"},{"t":"④ 고개를 숙이고 줄 밖으로 걸어 나갔다","mis":"K4-1-u1-X07"}],"explanation":["누가 한 말인가요?","은채가 한 말만","⑤예요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#10','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C10',2,'ox','auto','수아와 민호의 관계는 이야기가 흐르면서 바뀌었어요.',ARRAY['K4-1-u1-X08']::text[],false,'{"seq":10,"concept":"K4-1-u1-C10","difficulty":2,"kind":"ox","stem":"수아와 민호의 관계는 이야기가 흐르면서 바뀌었어요.","answer":"O","reason_options":[{"t":"③에서는 빠지라고 했지만 ⑧에서는 고맙다고 했기 때문에","correct":true},{"t":"처음 관계가 끝까지 그대로 이어지기 때문에","mis":"K4-1-u1-X08"}],"mis":"K4-1-u1-X08","explanation":["③과 ⑧을 견줘요.","수아의 말이 달라졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#11','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C18',2,'mc','auto','「긴 줄넘기 연습」의 흐름에 꼭 필요한 일은 무엇인가요?',ARRAY['K4-1-u1-X14']::text[],false,'{"seq":11,"concept":"K4-1-u1-C18","difficulty":2,"kind":"mc","stem":"「긴 줄넘기 연습」의 흐름에 꼭 필요한 일은 무엇인가요?","options":[{"t":"⑤ 은채가 민호에게 구령을 붙이자고 했다","correct":true},{"t":"줄넘기 줄의 색깔","mis":"K4-1-u1-X14"},{"t":"대회가 열린 날의 날씨","mis":"K4-1-u1-X14"},{"t":"수아가 신은 신발","mis":"K4-1-u1-X14"}],"explanation":["빠지면 이어지나요?","구령이 있어야 발이 맞아요.","⑤가 꼭 필요해요."],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#12','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C21',2,'mc','auto','「눈이 어두운 두더지 무루」의 일을 일어난 차례대로 놓은 것은 무엇인가요?',ARRAY['K4-1-u1-X15']::text[],false,'{"seq":12,"concept":"K4-1-u1-C21","difficulty":2,"kind":"mc","stem":"「눈이 어두운 두더지 무루」의 일을 일어난 차례대로 놓은 것은 무엇인가요?","options":[{"t":"무루가 밀려남 → 마루가 굴 파는 법을 알려 줌 → 큰비 온 밤 떨림을 느낌 → 모두를 언덕 위로 이끎","correct":true},{"t":"마루가 굴 파는 법을 알려 줌 → 큰비 온 밤 떨림을 느낌 → 무루가 밀려남 → 모두를 언덕 위로 이끎","mis":"K4-1-u1-X15"},{"t":"무루가 밀려남 → 큰비 온 밤 떨림을 느낌 → 모두를 언덕 위로 이끎 → 마루가 굴 파는 법을 알려 줌","mis":"K4-1-u1-X15"},{"t":"큰비 온 밤 떨림을 느낌 → 무루가 밀려남 → 마루가 굴 파는 법을 알려 줌 → 모두를 언덕 위로 이끎","mis":"K4-1-u1-X15"}],"explanation":["①부터 따라가요.","큰비는 뒤에 와요.","이끈 일이 마지막이에요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#13','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C40',2,'mc','auto','「돌다리를 놓은 아이」의 내용을 짐작하는 데 도움이 되는 질문은 무엇인가요?',ARRAY['K4-1-u1-X34','K4-1-u1-X35']::text[],false,'{"seq":13,"concept":"K4-1-u1-C40","difficulty":2,"kind":"mc","stem":"「돌다리를 놓은 아이」의 내용을 짐작하는 데 도움이 되는 질문은 무엇인가요?","options":[{"t":"마을 사람들은 왜 동이를 보고 웃었을까?","correct":true},{"t":"이 이야기는 모두 몇 줄일까?","mis":"K4-1-u1-X34"},{"t":"「돌」이라는 글자는 몇 번 나올까?","mis":"K4-1-u1-X34"},{"t":"동이가 나른 것은 무엇이었나요?","mis":"K4-1-u1-X35"}],"explanation":["세는 질문은 빼요.","답이 그대로 있는 질문보다","「왜?」를 물어요."],"asset":{"type":"passage","lines":["① 옛날 어느 산골 마을 사람들은 개울을 건너야 장터에 갈 수 있었어요.","② 비가 오면 개울물이 불어 사람들은 며칠씩 장에 가지 못했어요.","③ 동이는 날마다 개울에서 넓적한 돌을 하나씩 날라 놓았어요.","④ \"그걸로 언제 다리를 만드니?\" 마을 사람들은 웃었어요.","⑤ 동이네 집 마당에는 감나무가 한 그루 서 있었어요.","⑥ 여름이 가고 겨울이 오도록 동이는 돌 나르기를 멈추지 않았어요.","⑦ 이듬해 봄, 개울에 튼튼한 돌다리가 놓였어요.","⑧ 그 뒤로는 비가 와도 마을 사람들이 장에 갈 수 있었어요."],"title":"돌다리를 놓은 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#14','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C42',2,'mc','auto','「눈이 어두운 두더지 무루」라는 제목을 보고 짐작한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X04','K4-1-u1-X37']::text[],false,'{"seq":14,"concept":"K4-1-u1-C42","difficulty":2,"kind":"mc","stem":"「눈이 어두운 두더지 무루」라는 제목을 보고 짐작한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"눈이 어두운 두더지가 겪는 일에 대한 이야기일 것이다","correct":true},{"t":"두더지 굴을 파는 방법을 알려 주는 글일 것이다","mis":"K4-1-u1-X04"},{"t":"두더지의 종류를 늘어놓은 글일 것이다","mis":"K4-1-u1-X04"},{"t":"제목은 건너뛰고 본문부터 읽으면 된다","mis":"K4-1-u1-X37"}],"explanation":["제목에 누가 나오나요?","「눈이 어두운」 두더지","그 두더지의 이야기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#15','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C57',2,'mc','auto','「잔디」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-1-u1-X48']::text[],false,'{"seq":15,"concept":"K4-1-u1-C57","difficulty":2,"kind":"mc","stem":"「잔디」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[잔디]","correct":true},{"t":"[잔지]","mis":"K4-1-u1-X48"},{"t":"[잔치]","mis":"K4-1-u1-X48"},{"t":"[잗이]","mis":"K4-1-u1-X48"}],"explanation":["ㄷ이 받침인가요?","첫소리예요.","그대로 [잔디]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#16','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C59',2,'blank','auto','「친구가 약속을 잊어버리고 오지 않아서 (   ).」의 빈칸에 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X03']::text[],false,'{"seq":16,"concept":"K4-1-u1-C59","difficulty":2,"kind":"blank","stem":"「친구가 약속을 잊어버리고 오지 않아서 (   ).」의 빈칸에 가장 알맞은 것은 무엇인가요?","options":[{"t":"서운했다","correct":true},{"t":"즐거웠다","mis":"K4-1-u1-X03"},{"t":"기뻤다","mis":"K4-1-u1-X03"},{"t":"신났다","mis":"K4-1-u1-X03"}],"explanation":["무슨 일을 겪었나요?","기대가 어긋났어요.","서운했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#17','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C16',3,'mc','auto','「긴 줄넘기 연습」을 가장 잘 정리한 것은 무엇인가요?',ARRAY['K4-1-u1-X13','K4-1-u1-X12','K4-1-u1-X17']::text[],false,'{"seq":17,"concept":"K4-1-u1-C16","difficulty":3,"kind":"mc","stem":"「긴 줄넘기 연습」을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"줄에 자꾸 걸리던 민호가 구령을 맡아 모두의 발을 맞추어, 대회에서 끝까지 걸리지 않았다.","correct":true},{"t":"줄넘기를 했다.","mis":"K4-1-u1-X13"},{"t":"우리 반은 대회에 나가려고 날마다 연습했고, 민호는 줄에 걸렸고, 수아는 한숨을 쉬었고⋯⋯","mis":"K4-1-u1-X12"},{"t":"수아가 한숨을 쉬었다.","mis":"K4-1-u1-X17"}],"explanation":["너무 짧지 않게","너무 자세하지 않게","중요한 일을 차례대로"],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#18','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C31',3,'mc','auto','「미술 시간에 생긴 일」에서 전하고 싶은 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X25','K4-1-u1-X26']::text[],false,'{"seq":18,"concept":"K4-1-u1-C31","difficulty":3,"kind":"mc","stem":"「미술 시간에 생긴 일」에서 전하고 싶은 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"겉으로 보이는 한 가지로 친구를 판단하지 말자","correct":true},{"t":"깃발은 하늘색으로 칠해야 한다","mis":"K4-1-u1-X25"},{"t":"미술 시간에는 그림을 잘 그려야 한다","mis":"K4-1-u1-X25"},{"t":"그림을 못 그리면 색칠만 하는 것이 맞다","mis":"K4-1-u1-X26"}],"explanation":["작은 사실에서 찾지 않아요.","흐름 전체를 봐요.","하준이의 다른 재주"],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#19','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C48',3,'mc','auto','제목만 보고 「아이가 하루 만에 다리를 놓았을 것이다」라고 짐작했어요. 글과 견준 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X41','K4-1-u1-X40']::text[],false,'{"seq":19,"concept":"K4-1-u1-C48","difficulty":3,"kind":"mc","stem":"제목만 보고 「아이가 하루 만에 다리를 놓았을 것이다」라고 짐작했어요. 글과 견준 것으로 알맞은 것은 무엇인가요?","options":[{"t":"다리를 놓은 것은 같고, 한 해 넘게 날마다 돌을 날랐다는 점이 다르다","correct":true},{"t":"짐작과 글의 쪽수가 같다","mis":"K4-1-u1-X41"},{"t":"짐작이 틀렸으니 이 글은 잘못 쓴 글이다","mis":"K4-1-u1-X40"},{"t":"짐작과 글에 나온 그림 수를 견준다","mis":"K4-1-u1-X41"}],"explanation":["내용끼리 견줘요.","③ · ⑥ · ⑦을 봐요.","같은 점 · 다른 점"],"asset":{"type":"passage","lines":["① 옛날 어느 산골 마을 사람들은 개울을 건너야 장터에 갈 수 있었어요.","② 비가 오면 개울물이 불어 사람들은 며칠씩 장에 가지 못했어요.","③ 동이는 날마다 개울에서 넓적한 돌을 하나씩 날라 놓았어요.","④ \"그걸로 언제 다리를 만드니?\" 마을 사람들은 웃었어요.","⑤ 동이네 집 마당에는 감나무가 한 그루 서 있었어요.","⑥ 여름이 가고 겨울이 오도록 동이는 돌 나르기를 멈추지 않았어요.","⑦ 이듬해 봄, 개울에 튼튼한 돌다리가 놓였어요.","⑧ 그 뒤로는 비가 와도 마을 사람들이 장에 갈 수 있었어요."],"title":"돌다리를 놓은 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#20','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C41',3,'mc','auto','「눈이 어두운 두더지 무루」를 더 깊이 보게 하는 질문은 무엇인가요?',ARRAY['K4-1-u1-X35','K4-1-u1-X36']::text[],false,'{"seq":20,"concept":"K4-1-u1-C41","difficulty":3,"kind":"mc","stem":"「눈이 어두운 두더지 무루」를 더 깊이 보게 하는 질문은 무엇인가요?","options":[{"t":"두더지들은 왜 처음에 무루의 다른 재주를 알아보지 못했을까?","correct":true},{"t":"무루는 소리를 질러 누구를 깨웠나요?","mis":"K4-1-u1-X35"},{"t":"큰비는 언제 쏟아졌나요?","mis":"K4-1-u1-X35"},{"t":"두더지 질문은 많이 만들수록 좋을까?","mis":"K4-1-u1-X36"}],"explanation":["답이 그대로 있나요?","빈 곳을 메워요.","「왜?」를 물어요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#21','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C50',3,'mc','auto','비 오는 날 장면 카드 네 장을 가장 자연스러운 차례로 놓은 것은 무엇인가요?',ARRAY['K4-1-u1-X15']::text[],false,'{"seq":21,"concept":"K4-1-u1-C50","difficulty":3,"kind":"mc","stem":"비 오는 날 장면 카드 네 장을 가장 자연스러운 차례로 놓은 것은 무엇인가요?","options":[{"t":"㉯ → ㉱ → ㉰ → ㉮","correct":true},{"t":"㉮ → ㉯ → ㉱ → ㉰","mis":"K4-1-u1-X15"},{"t":"㉱ → ㉯ → ㉮ → ㉰","mis":"K4-1-u1-X15"},{"t":"㉯ → ㉰ → ㉮ → ㉱","mis":"K4-1-u1-X15"}],"explanation":["하늘이 먼저 어두워지고","비가 와야 우산을 펴요.","접는 것은 마지막이에요."],"asset":{"type":"passage","lines":["㉮ 젖은 우산을 접는다","㉯ 하늘이 어두워진다","㉰ 우산을 펼쳐 든다","㉱ 빗방울이 떨어진다"],"title":"장면 카드 네 장 — 비 오는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#22','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C25',3,'mc','auto','「미술 시간에 생긴 일」에서 하준이와 태오의 관계가 바뀌는 마디는 어디인가요?',ARRAY['K4-1-u1-X27']::text[],false,'{"seq":22,"concept":"K4-1-u1-C25","difficulty":3,"kind":"mc","stem":"「미술 시간에 생긴 일」에서 하준이와 태오의 관계가 바뀌는 마디는 어디인가요?","options":[{"t":"⑦ 깃발을 걸자 아이들이 색이 좋다고 했다","correct":true},{"t":"① 하준이는 늘 뒤로 물러섰다","mis":"K4-1-u1-X27"},{"t":"③ 붓만 만지작거렸다","mis":"K4-1-u1-X27"},{"t":"⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다","mis":"K4-1-u1-X27"}],"explanation":["언제부터 달라졌나요?","깃발을 본 뒤","⑦이 마디예요."],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#23','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C10',4,'essay','teacher','「눈이 어두운 두더지 무루」에서 무루와 마을 두더지들의 관계가 처음과 끝에 어떻게 달라졌는지 쓰고, 관계가 바뀐 마디가 어디인지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u1-C10","difficulty":4,"kind":"essay","stem":"「눈이 어두운 두더지 무루」에서 무루와 마을 두더지들의 관계가 처음과 끝에 어떻게 달라졌는지 쓰고, 관계가 바뀐 마디가 어디인지 쓰세요.","answer_guide":{"answer":"예: 처음에는 두더지들이 눈이 어둡다고 무루를 밀어내 갈등하는 관계였다. 큰비 온 밤 무루가 흙의 떨림을 느껴 모두를 언덕 위로 이끈 일(⑦)이 마디가 되어, 끝에는 서로 다른 재주를 귀하게 여기는 관계가 되었다.","scoring_points":["처음의 관계를 썼는가","끝의 관계를 썼는가","관계가 바뀐 마디를 썼는가"]},"explanation":["처음 장면","끝 장면","어디서 바뀌었나요?"],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#24','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C17',4,'essay','teacher','「석봉과 어머니」의 흐름을 장소의 변화(한양 → 고향집 → 한양)에 따라 세 부분으로 나누어 정리하세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u1-C17","difficulty":4,"kind":"essay","stem":"「석봉과 어머니」의 흐름을 장소의 변화(한양 → 고향집 → 한양)에 따라 세 부분으로 나누어 정리하세요.","answer_guide":{"answer":"예: 한양 — 석봉은 3년 동안 글씨 공부를 했다. 고향집 — 명필이 되었다며 돌아온 석봉을 어머니가 어둠 속에서 시험했고, 떡은 고른데 글씨는 제각각이었다. 한양 — 꾸중을 들은 석봉은 부끄러워하며 다시 공부에 힘썼다.","scoring_points":["장소의 변화에 따라 세 부분으로 나누었는가","부분마다 중요한 일을 썼는가","일이 일어난 차례를 지켰는가"]},"explanation":["어디에서?","무슨 일이?","차례대로"],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_b#25','kor',4,1,'u1','','g4_1_kor_u1_review_b','unit_review','K4-1-u1-C40',4,'essay','teacher','「우리 반 텃밭 일기」의 제목과 차례를 보고 내용을 짐작하는 데 도움이 되는 질문 두 개를 쓰고, 도움이 되지 않는 질문의 예를 하나 들어 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u1-C40","difficulty":4,"kind":"essay","stem":"「우리 반 텃밭 일기」의 제목과 차례를 보고 내용을 짐작하는 데 도움이 되는 질문 두 개를 쓰고, 도움이 되지 않는 질문의 예를 하나 들어 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 도움이 되는 질문 — 「빈 땅을 고른 까닭은 무엇일까?」 「물을 나누어 주기로 한 약속은 지켜졌을까?」 도움이 되지 않는 질문 — 「이 책은 모두 몇 쪽일까?」 쪽수는 내용과 상관이 없어서 무슨 이야기인지 짐작하는 데 도움이 되지 않는다.","scoring_points":["도움이 되는 질문 두 개를 썼는가","도움이 되지 않는 질문의 예를 들었는가","그 질문이 내용과 상관없다는 까닭을 썼는가"]},"explanation":["내용을 묻는 질문","세는 질문","까닭도 써요."],"asset":{"type":"passage","lines":["제목: 우리 반 텃밭 일기","차례 1. 빈 땅을 고른 날","차례 2. 싹이 나지 않는 두 줄","차례 3. 물을 나누어 주기로 한 약속","차례 4. 함께 거둔 상추"],"title":"읽기 전 — 우리 반이 만든 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#1','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C53',1,'mc','auto','글을 읽기 전과 읽는 중에 질문을 만들면 무엇을 할 수 있나요?',ARRAY['K4-1-u1-X34','K4-1-u1-X01','K4-1-u1-X29']::text[],false,'{"seq":1,"concept":"K4-1-u1-C53","difficulty":1,"kind":"mc","stem":"글을 읽기 전과 읽는 중에 질문을 만들면 무엇을 할 수 있나요?","options":[{"t":"내용을 짐작할 수 있다","correct":true},{"t":"글자를 더 빨리 셀 수 있다","mis":"K4-1-u1-X34"},{"t":"낱말을 모두 외울 수 있다","mis":"K4-1-u1-X01"},{"t":"글을 다 읽은 뒤에만 쓸모가 있다","mis":"K4-1-u1-X29"}],"explanation":["스무고개처럼","질문이 길을 보여 줘요.","내용을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#2','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C3',1,'mc','auto','「눈이 어두운 두더지 무루」에서 무루와 도와주는 관계인 인물은 누구인가요?',ARRAY['K4-1-u1-X02','K4-1-u1-X11']::text[],false,'{"seq":2,"concept":"K4-1-u1-C3","difficulty":1,"kind":"mc","stem":"「눈이 어두운 두더지 무루」에서 무루와 도와주는 관계인 인물은 누구인가요?","options":[{"t":"마루","correct":true},{"t":"또래 두더지들","mis":"K4-1-u1-X02"},{"t":"호들갑을 떤 마을 두더지들","mis":"K4-1-u1-X02"},{"t":"아무도 없다","mis":"K4-1-u1-X11"}],"explanation":["④를 봐요.","굴 파는 법을 알려 주었어요.","엄마 마루예요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#3','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C14',1,'mc','auto','이야기의 흐름을 따라가며 읽으면 좋은 점은 무엇인가요?',ARRAY['K4-1-u1-X34','K4-1-u1-X01']::text[],false,'{"seq":3,"concept":"K4-1-u1-C14","difficulty":1,"kind":"mc","stem":"이야기의 흐름을 따라가며 읽으면 좋은 점은 무엇인가요?","options":[{"t":"이야기의 내용을 훨씬 잘 이해할 수 있다","correct":true},{"t":"이야기의 글자 수를 빨리 셀 수 있다","mis":"K4-1-u1-X34"},{"t":"인물의 이름을 모두 외울 수 있다","mis":"K4-1-u1-X01"},{"t":"이야기의 쪽수를 알 수 있다","mis":"K4-1-u1-X34"}],"explanation":["흐름은 나아가는 길","길을 따라가면","내용이 잘 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#4','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C38',1,'mc','auto','「나도 상추를 길러 본 적이 있는데, 이 책 속 아이들도 그랬을까?」는 어떤 갈래의 질문인가요?',ARRAY['K4-1-u1-X33','K4-1-u1-X34']::text[],false,'{"seq":4,"concept":"K4-1-u1-C38","difficulty":1,"kind":"mc","stem":"「나도 상추를 길러 본 적이 있는데, 이 책 속 아이들도 그랬을까?」는 어떤 갈래의 질문인가요?","options":[{"t":"자신의 경험과 관련지은 질문","correct":true},{"t":"낱말의 뜻을 짐작하는 질문","mis":"K4-1-u1-X33"},{"t":"이어질 내용을 짐작하는 질문","mis":"K4-1-u1-X33"},{"t":"쪽수를 세는 질문","mis":"K4-1-u1-X34"}],"explanation":["「나도 ~ 본 적이 있는데」","내가 겪은 일","경험 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#5','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C55',1,'mc','auto','「묻히다」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-1-u1-X47']::text[],false,'{"seq":5,"concept":"K4-1-u1-C55","difficulty":1,"kind":"mc","stem":"「묻히다」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[무치다]","correct":true},{"t":"[무지다]","mis":"K4-1-u1-X47"},{"t":"[무디다]","mis":"K4-1-u1-X47"},{"t":"[묻히다]","mis":"K4-1-u1-X47"}],"explanation":["받침 ㄷ 뒤에 히","[ㅊ]으로 바뀌어요.","[무치다]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#6','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C56',1,'mc','auto','[구치다]로 소리 나는 낱말을 바르게 쓴 것은 무엇인가요?',ARRAY['K4-1-u1-X46']::text[],false,'{"seq":6,"concept":"K4-1-u1-C56","difficulty":1,"kind":"mc","stem":"[구치다]로 소리 나는 낱말을 바르게 쓴 것은 무엇인가요?","options":[{"t":"굳히다","correct":true},{"t":"구치다","mis":"K4-1-u1-X46"},{"t":"굿히다","mis":"K4-1-u1-X46"},{"t":"굳이다","mis":"K4-1-u1-X46"}],"explanation":["「굳다」에서 왔어요.","굳 + 히다","굳히다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#7','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C58',1,'mc','auto','「쓸쓸하다」와 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K4-1-u1-X49']::text[],false,'{"seq":7,"concept":"K4-1-u1-C58","difficulty":1,"kind":"mc","stem":"「쓸쓸하다」와 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"외롭다","correct":true},{"t":"기쁘다","mis":"K4-1-u1-X49"},{"t":"즐겁다","mis":"K4-1-u1-X49"},{"t":"신나다","mis":"K4-1-u1-X49"}],"explanation":["혼자인 느낌","외로움끼리","외롭다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#8','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C27',1,'mc','auto','「호들갑을 떨다」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X21','K4-1-u1-X22']::text[],false,'{"seq":8,"concept":"K4-1-u1-C27","difficulty":1,"kind":"mc","stem":"「호들갑을 떨다」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"가볍고 야단스럽게 굴다","correct":true},{"t":"몸을 부르르 떨다","mis":"K4-1-u1-X21"},{"t":"큰 충격으로 정신이 아찔하다","mis":"K4-1-u1-X22"},{"t":"슬픔 때문에 큰 고통을 받다","mis":"K4-1-u1-X22"}],"explanation":["몸이 떨리는 것일까요?","두더지들이 떠들었어요.","야단스럽게 굴다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#9','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C7',2,'mc','auto','「석봉과 어머니」에서 어머니의 성격이 가장 잘 드러난 결정적인 장면은 무엇인가요?',ARRAY['K4-1-u1-X07','K4-1-u1-X06']::text[],false,'{"seq":9,"concept":"K4-1-u1-C7","difficulty":2,"kind":"mc","stem":"「석봉과 어머니」에서 어머니의 성격이 가장 잘 드러난 결정적인 장면은 무엇인가요?","options":[{"t":"③ 호롱불을 끄고 어둠 속에서 글씨를 써 보라고 했다","correct":true},{"t":"① 석봉이 한양에서 3년 동안 공부했다","mis":"K4-1-u1-X07"},{"t":"어머니는 나이가 많았을 것이라는 짐작","mis":"K4-1-u1-X06"},{"t":"⑦ 석봉이 자신을 부끄러워했다","mis":"K4-1-u1-X07"}],"explanation":["어머니가 한 말과 행동","결정적인 장면","③이에요."],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#10','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C10',2,'mc','auto','마을 두더지들과 무루의 관계는 어떻게 바뀌었나요?',ARRAY['K4-1-u1-X08','K4-1-u1-X11']::text[],false,'{"seq":10,"concept":"K4-1-u1-C10","difficulty":2,"kind":"mc","stem":"마을 두더지들과 무루의 관계는 어떻게 바뀌었나요?","options":[{"t":"무루를 밀어내다가 무루 덕분에 서로 다른 재주를 귀하게 여기게 되었다","correct":true},{"t":"끝까지 무루를 밀어냈다","mis":"K4-1-u1-X08"},{"t":"처음부터 무루를 귀하게 여겼다","mis":"K4-1-u1-X08"},{"t":"두더지들과 무루는 서로 상관이 없었다","mis":"K4-1-u1-X11"}],"explanation":["③과 ⑧을 견줘요.","무엇이 계기였나요?","관계가 바뀌었어요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#11','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C18',2,'mc','auto','「눈이 어두운 두더지 무루」에서 빠지면 이야기가 이어지지 않는 일은 무엇인가요?',ARRAY['K4-1-u1-X14']::text[],false,'{"seq":11,"concept":"K4-1-u1-C18","difficulty":2,"kind":"mc","stem":"「눈이 어두운 두더지 무루」에서 빠지면 이야기가 이어지지 않는 일은 무엇인가요?","options":[{"t":"⑤ 무루가 앞발 끝으로 흙의 떨림을 느꼈다","correct":true},{"t":"두더지 굴의 입구가 몇 개였는지","mis":"K4-1-u1-X14"},{"t":"그날 밤 구름의 모양","mis":"K4-1-u1-X14"},{"t":"마루의 털 색깔","mis":"K4-1-u1-X14"}],"explanation":["떨림을 못 느꼈다면?","모두를 구할 수 없어요.","⑤가 꼭 필요해요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#12','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C21',2,'mc','auto','「미술 시간에 생긴 일」의 일을 일어난 차례대로 놓은 것은 무엇인가요?',ARRAY['K4-1-u1-X15']::text[],false,'{"seq":12,"concept":"K4-1-u1-C21","difficulty":2,"kind":"mc","stem":"「미술 시간에 생긴 일」의 일을 일어난 차례대로 놓은 것은 무엇인가요?","options":[{"t":"태오가 색칠만 하라고 함 → 서아가 색을 맡김 → 하준이가 바탕을 칠함 → 태오가 하준이를 인정함","correct":true},{"t":"서아가 색을 맡김 → 태오가 색칠만 하라고 함 → 태오가 하준이를 인정함 → 하준이가 바탕을 칠함","mis":"K4-1-u1-X15"},{"t":"태오가 색칠만 하라고 함 → 하준이가 바탕을 칠함 → 서아가 색을 맡김 → 태오가 하준이를 인정함","mis":"K4-1-u1-X15"},{"t":"태오가 하준이를 인정함 → 태오가 색칠만 하라고 함 → 서아가 색을 맡김 → 하준이가 바탕을 칠함","mis":"K4-1-u1-X15"}],"explanation":["②부터 따라가요.","색을 맡아야 칠해요.","인정은 마지막이에요."],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#13','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C40',2,'mc','auto','「눈이 어두운 두더지 무루」의 내용을 짐작하는 데 도움이 되는 질문은 무엇인가요?',ARRAY['K4-1-u1-X34','K4-1-u1-X35']::text[],false,'{"seq":13,"concept":"K4-1-u1-C40","difficulty":2,"kind":"mc","stem":"「눈이 어두운 두더지 무루」의 내용을 짐작하는 데 도움이 되는 질문은 무엇인가요?","options":[{"t":"무루는 어떻게 앞발로 흙의 떨림을 느낄 수 있었을까?","correct":true},{"t":"이 글은 모두 몇 글자일까?","mis":"K4-1-u1-X34"},{"t":"「무루」라는 이름은 몇 번 나올까?","mis":"K4-1-u1-X34"},{"t":"무루의 엄마 이름은 무엇인가요?","mis":"K4-1-u1-X35"}],"explanation":["세는 질문은 빼요.","답이 그대로 있는 질문보다","「어떻게?」를 물어요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#14','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C43',2,'mc','auto','「우리 반 텃밭 일기」의 차례 4 「함께 거둔 상추」로 짐작한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X04','K4-1-u1-X37']::text[],false,'{"seq":14,"concept":"K4-1-u1-C43","difficulty":2,"kind":"mc","stem":"「우리 반 텃밭 일기」의 차례 4 「함께 거둔 상추」로 짐작한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"반 아이들이 텃밭을 끝까지 가꾸어 상추를 함께 거두었을 것이다","correct":true},{"t":"상추를 파는 가게의 이야기일 것이다","mis":"K4-1-u1-X04"},{"t":"차례 4는 앞 차례와 상관이 없을 것이다","mis":"K4-1-u1-X37"},{"t":"상추가 모두 시들어 버렸을 것이다","mis":"K4-1-u1-X04"}],"explanation":["「함께 거둔」","앞 차례와 이어요.","끝까지 가꾸었어요."],"asset":{"type":"passage","lines":["제목: 우리 반 텃밭 일기","차례 1. 빈 땅을 고른 날","차례 2. 싹이 나지 않는 두 줄","차례 3. 물을 나누어 주기로 한 약속","차례 4. 함께 거둔 상추"],"title":"읽기 전 — 우리 반이 만든 책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#15','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C57',2,'mc','auto','글자와 소리가 다른 낱말은 무엇인가요?',ARRAY['K4-1-u1-X48']::text[],false,'{"seq":15,"concept":"K4-1-u1-C57","difficulty":2,"kind":"mc","stem":"글자와 소리가 다른 낱말은 무엇인가요?","options":[{"t":"해돋이","correct":true},{"t":"어디","mis":"K4-1-u1-X48"},{"t":"마디","mis":"K4-1-u1-X48"},{"t":"잔디","mis":"K4-1-u1-X48"}],"explanation":["받침 ㄷ 뒤에 ㅣ가 오나요?","해돋이만 받침이에요.","[해도지]로 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#16','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C13',2,'mc','auto','④에서 마루는 어떤 마음이었나요?',ARRAY['K4-1-u1-X03']::text[],false,'{"seq":16,"concept":"K4-1-u1-C13","difficulty":2,"kind":"mc","stem":"④에서 마루는 어떤 마음이었나요?","options":[{"t":"무루가 밀려나는 것을 보며 몹시 괴로웠다","correct":true},{"t":"무루가 밀려나서 기뻤다","mis":"K4-1-u1-X03"},{"t":"아무렇지 않았다","mis":"K4-1-u1-X03"},{"t":"또래 두더지들이 고마웠다","mis":"K4-1-u1-X03"}],"explanation":["「가슴이 찢어질 듯」","무엇을 보았나요?","몹시 괴로웠어요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#17','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C16',3,'mc','auto','「석봉과 어머니」를 가장 잘 정리한 것은 무엇인가요?',ARRAY['K4-1-u1-X13','K4-1-u1-X12','K4-1-u1-X17']::text[],false,'{"seq":17,"concept":"K4-1-u1-C16","difficulty":3,"kind":"mc","stem":"「석봉과 어머니」를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"명필이 되었다며 돌아온 석봉이 어머니가 낸 시험에서 모자람을 깨닫고 다시 공부하러 떠났다.","correct":true},{"t":"석봉이 글씨를 썼다.","mis":"K4-1-u1-X13"},{"t":"석봉은 한양에서 3년 동안 공부하고 고향집으로 돌아와서 어머니께 인사를 했는데 어머니는⋯⋯","mis":"K4-1-u1-X12"},{"t":"어머니가 떡을 썰었다.","mis":"K4-1-u1-X17"}],"explanation":["너무 짧지 않게","너무 자세하지 않게","중요한 일을 차례대로"],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#18','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C31',3,'mc','auto','⑧ 「서로 다른 재주를 귀하게 여기게 되었다」가 알려 주는 것은 무엇인가요?',ARRAY['K4-1-u1-X25','K4-1-u1-X26']::text[],false,'{"seq":18,"concept":"K4-1-u1-C31","difficulty":3,"kind":"mc","stem":"⑧ 「서로 다른 재주를 귀하게 여기게 되었다」가 알려 주는 것은 무엇인가요?","options":[{"t":"무루 덕분에 다른 것을 존중하게 된 마을의 변화","correct":true},{"t":"큰비가 그쳤다는 것","mis":"K4-1-u1-X25"},{"t":"두더지들이 굴을 버리고 떠났다는 것","mis":"K4-1-u1-X25"},{"t":"눈이 어두운 두더지는 쓸모가 없다는 것","mis":"K4-1-u1-X26"}],"explanation":["처음과 견줘요.","무엇이 바뀌었나요?","존중하게 되었어요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#19','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C49',3,'mc','auto','「숨 쉬는 그릇」을 읽기 전에 「구멍이 커서 숨을 쉴 것이다」라고 짐작했어요. 글을 읽은 뒤 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X40','K4-1-u1-X41']::text[],false,'{"seq":19,"concept":"K4-1-u1-C49","difficulty":3,"kind":"mc","stem":"「숨 쉬는 그릇」을 읽기 전에 「구멍이 커서 숨을 쉴 것이다」라고 짐작했어요. 글을 읽은 뒤 알맞은 것은 무엇인가요?","options":[{"t":"구멍이 있다는 점은 같지만 아주 작은 구멍이라는 것을 새로 알았다","correct":true},{"t":"구멍이 크다고 짐작했으니 글이 틀렸다","mis":"K4-1-u1-X40"},{"t":"짐작을 지우고 아무것도 적지 않는다","mis":"K4-1-u1-X40"},{"t":"짐작과 글의 그림 수가 같은지 견준다","mis":"K4-1-u1-X41"}],"explanation":["②를 봐요.","같은 점도, 다른 점도","다른 점 = 새로 안 것"],"asset":{"type":"passage","lines":["① 옹기는 흙으로 만든 우리나라 고유의 그릇이다.","② 옹기에는 아주 작은 구멍이 촘촘히 나 있어 공기가 드나든다.","③ 그래서 음식을 오래 보관할 수 있어 「숨 쉬는 그릇」이라고 부른다.","④ 옹기는 허리가 불룩해 여러 개를 모아 두면 옹기 사이에 틈이 생긴다.","⑤ 그 틈으로 바람이 지나가 옹기의 위와 아래가 비슷한 온도를 유지한다.","⑥ 우리나라는 옹기를 만드는 기술자인 옹기장을 무형유산으로 지정했다."],"title":"숨 쉬는 그릇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#20','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C41',3,'mc','auto','「돌다리를 놓은 아이」를 더 깊이 보게 하는 질문은 무엇인가요?',ARRAY['K4-1-u1-X35','K4-1-u1-X36']::text[],false,'{"seq":20,"concept":"K4-1-u1-C41","difficulty":3,"kind":"mc","stem":"「돌다리를 놓은 아이」를 더 깊이 보게 하는 질문은 무엇인가요?","options":[{"t":"사람들이 웃었는데도 동이는 왜 돌 나르기를 멈추지 않았을까?","correct":true},{"t":"돌다리는 언제 놓였나요?","mis":"K4-1-u1-X35"},{"t":"사람들은 어디에 가려고 개울을 건넜나요?","mis":"K4-1-u1-X35"},{"t":"「돌」로 질문을 열 개 넘게 만들까?","mis":"K4-1-u1-X36"}],"explanation":["답이 그대로 있나요?","빈 곳을 메워요.","「왜?」를 물어요."],"asset":{"type":"passage","lines":["① 옛날 어느 산골 마을 사람들은 개울을 건너야 장터에 갈 수 있었어요.","② 비가 오면 개울물이 불어 사람들은 며칠씩 장에 가지 못했어요.","③ 동이는 날마다 개울에서 넓적한 돌을 하나씩 날라 놓았어요.","④ \"그걸로 언제 다리를 만드니?\" 마을 사람들은 웃었어요.","⑤ 동이네 집 마당에는 감나무가 한 그루 서 있었어요.","⑥ 여름이 가고 겨울이 오도록 동이는 돌 나르기를 멈추지 않았어요.","⑦ 이듬해 봄, 개울에 튼튼한 돌다리가 놓였어요.","⑧ 그 뒤로는 비가 와도 마을 사람들이 장에 갈 수 있었어요."],"title":"돌다리를 놓은 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#21','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C51',3,'mc','auto','비 오는 날 장면 카드로 쓴 이야기 가운데 이야기가 가장 살아나는 것은 무엇인가요?',ARRAY['K4-1-u1-X43','K4-1-u1-X15']::text[],false,'{"seq":21,"concept":"K4-1-u1-C51","difficulty":3,"kind":"mc","stem":"비 오는 날 장면 카드로 쓴 이야기 가운데 이야기가 가장 살아나는 것은 무엇인가요?","options":[{"t":"하늘이 어두워지더니 빗방울이 톡 떨어졌다. \"우산 챙기길 잘했다!\" 나는 얼른 우산을 펼쳐 들었다.","correct":true},{"t":"하늘. 비. 우산. 접기.","mis":"K4-1-u1-X43"},{"t":"우산을 접었다. 그다음 하늘이 어두워졌다.","mis":"K4-1-u1-X15"},{"t":"비가 왔다. 끝.","mis":"K4-1-u1-X43"}],"explanation":["차례를 지켜요.","말과 행동을 넣어요.","이야기가 살아나요."],"asset":{"type":"passage","lines":["㉮ 젖은 우산을 접는다","㉯ 하늘이 어두워진다","㉰ 우산을 펼쳐 든다","㉱ 빗방울이 떨어진다"],"title":"장면 카드 네 장 — 비 오는 날"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#22','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C25',3,'mc','auto','「눈이 어두운 두더지 무루」에서 무루와 마을 두더지들의 관계가 바뀌는 마디는 어디인가요?',ARRAY['K4-1-u1-X27']::text[],false,'{"seq":22,"concept":"K4-1-u1-C25","difficulty":3,"kind":"mc","stem":"「눈이 어두운 두더지 무루」에서 무루와 마을 두더지들의 관계가 바뀌는 마디는 어디인가요?","options":[{"t":"⑦ 무루가 앞장서서 모두를 언덕 위로 이끌었다","correct":true},{"t":"② 마을 두더지들이 호들갑을 떨었다","mis":"K4-1-u1-X27"},{"t":"③ 또래 두더지들이 무루를 밀어냈다","mis":"K4-1-u1-X27"},{"t":"① 무루는 눈이 훨씬 어두웠다","mis":"K4-1-u1-X27"}],"explanation":["언제부터 달라졌나요?","모두를 구한 뒤","⑦이 마디예요."],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#23','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C28',4,'essay','teacher','「긴 줄넘기 연습」에서 은채가 한 말을 근거로 은채의 성격과 역할을 쓰고, 은채와 민호는 어떤 관계인지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u1-C28","difficulty":4,"kind":"essay","stem":"「긴 줄넘기 연습」에서 은채가 한 말을 근거로 은채의 성격과 역할을 쓰고, 은채와 민호는 어떤 관계인지 쓰세요.","answer_guide":{"answer":"예: 은채는 「네가 구령을 붙여 주면 어때? 목소리가 크잖아」라고 말했다. 친구의 잘하는 점을 찾아 주는 따뜻한 성격이고, 민호가 다시 함께할 수 있게 돕는 역할을 했다. 은채와 민호는 도와주는 관계이다.","scoring_points":["은채가 한 말을 근거로 들었는가","은채의 성격과 역할을 썼는가","은채와 민호의 관계를 썼는가"]},"explanation":["⑤를 봐요.","성격과 역할","어떤 관계?"],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#24','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C18',4,'essay','teacher','「긴 줄넘기 연습」에서 흐름에 꼭 필요한 일 세 가지를 골라 차례대로 쓰고, 그 일들을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u1-C18","difficulty":4,"kind":"essay","stem":"「긴 줄넘기 연습」에서 흐름에 꼭 필요한 일 세 가지를 골라 차례대로 쓰고, 그 일들을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 수아가 줄에 자꾸 걸리는 민호에게 빠지라고 했다 → 은채가 민호에게 구령을 붙이자고 했다 → 민호의 구령으로 모두의 발이 맞아 대회에서 끝까지 걸리지 않았다. 이 일들이 빠지면 민호와 수아의 관계가 왜 바뀌었는지 이어지지 않기 때문이다.","scoring_points":["꼭 필요한 일 세 가지를 골랐는가","일이 일어난 차례대로 썼는가","빠지면 이야기가 이어지지 않는다는 까닭을 썼는가"]},"explanation":["빠지면 끊기는 일","차례대로","고른 까닭"],"asset":{"type":"passage","lines":["① 우리 반은 긴 줄넘기 대회에 나가려고 날마다 연습했다.","② 민호는 줄에 자꾸 발이 걸려 연습이 번번이 멈추었다.","③ \"민호 너는 빠지는 게 낫겠어.\" 수아가 한숨을 쉬며 말했다.","④ 민호는 고개를 숙이고 줄 밖으로 걸어 나갔다.","⑤ 은채가 말했다. \"민호야, 네가 구령을 붙여 주면 어때? 목소리가 크잖아.\"","⑥ 민호가 \"하나, 둘!\" 하고 외치자 모두의 발이 착착 맞았다.","⑦ 대회 날, 우리 반은 끝까지 한 번도 걸리지 않았다.","⑧ 수아가 민호에게 말했다. \"네 구령 덕분이야. 아까는 미안해.\""],"title":"긴 줄넘기 연습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_c#25','kor',4,1,'u1','','g4_1_kor_u1_review_c','unit_review','K4-1-u1-C39',4,'essay','teacher','「눈이 어두운 두더지 무루」를 읽고 낱말의 뜻 · 자신의 경험 · 더 궁금한 점 가운데 두 갈래를 골라 질문을 하나씩 만들고, 갈래 이름을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u1-C39","difficulty":4,"kind":"essay","stem":"「눈이 어두운 두더지 무루」를 읽고 낱말의 뜻 · 자신의 경험 · 더 궁금한 점 가운데 두 갈래를 골라 질문을 하나씩 만들고, 갈래 이름을 쓰세요.","answer_guide":{"answer":"예: 「호들갑을 떨다는 무슨 뜻일까?」 — 낱말의 뜻을 짐작하는 질문. 「나도 남과 달라서 속상했던 적이 있는데, 무루는 어떤 마음이었을까?」 — 자신의 경험과 관련지은 질문.","scoring_points":["서로 다른 두 갈래로 질문을 만들었는가","질문이 글의 내용과 이어지는가","갈래 이름을 바르게 썼는가"]},"explanation":["갈래를 골라요.","내용과 이어지게","갈래 이름도"],"asset":{"type":"passage","lines":["① 언덕 마을의 두더지 무루는 다른 두더지보다 눈이 훨씬 어두웠다.","② \"저래서야 굴길을 어떻게 찾아다니겠어?\" 마을 두더지들은 호들갑을 떨었다.","③ \"넌 앞도 못 보잖아. 저리 가!\" 또래 두더지들이 무루를 밀어냈다.","④ 엄마 마루는 가슴이 찢어질 듯 아팠지만 무루에게 굴 파는 법을 알려 주었다.","⑤ 큰비가 쏟아지던 밤, 무루는 앞발 끝으로 흙이 잘게 떨리는 것을 느꼈다.","⑥ 무루는 하늘이 노래지도록 소리를 질러 두더지들을 깨웠다.","⑦ 무루가 앞장서서 흙의 떨림을 따라 모두를 언덕 위로 이끌었다.","⑧ 그 뒤로 언덕 마을에서는 서로 다른 재주를 귀하게 여기게 되었다."],"title":"눈이 어두운 두더지 무루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#1','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C1',1,'mc','auto','「깊이 있게 읽어요」에서 배운 것으로만 묶은 것은 무엇인가요?',ARRAY['K4-1-u1-X01','K4-1-u1-X34']::text[],false,'{"seq":1,"concept":"K4-1-u1-C1","difficulty":1,"kind":"mc","stem":"「깊이 있게 읽어요」에서 배운 것으로만 묶은 것은 무엇인가요?","options":[{"t":"관계 파악하기 · 흐름 파악하기 · 질문 만들기","correct":true},{"t":"자음자 외우기 · 흐름 파악하기 · 질문 만들기","mis":"K4-1-u1-X01"},{"t":"관계 파악하기 · 두 자리 수 더하기 · 질문 만들기","mis":"K4-1-u1-X01"},{"t":"관계 파악하기 · 흐름 파악하기 · 쪽수 세기","mis":"K4-1-u1-X34"}],"explanation":["인물 · 흐름 · 질문","셋 다 깊이 읽는 방법","모두 맞는 묶음을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#2','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C2',1,'mc','auto','도와주는 관계와 갈등하는 관계를 가르는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X06','K4-1-u1-X11']::text[],false,'{"seq":2,"concept":"K4-1-u1-C2","difficulty":1,"kind":"mc","stem":"도와주는 관계와 갈등하는 관계를 가르는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"서로 거들어 주는지, 부딪히거나 밀어내는지","correct":true},{"t":"두 인물의 키가 비슷한지","mis":"K4-1-u1-X06"},{"t":"두 인물의 이름이 비슷한지","mis":"K4-1-u1-X06"},{"t":"두 인물 가운데 한 인물만 보면 된다","mis":"K4-1-u1-X11"}],"explanation":["두 인물 사이를 봐요.","무엇을 해 주었나요?","거드나, 밀어내나"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#3','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C21',1,'mc','auto','「개미와 비둘기」에서 가장 먼저 일어난 일은 무엇인가요?',ARRAY['K4-1-u1-X15']::text[],false,'{"seq":3,"concept":"K4-1-u1-C21","difficulty":1,"kind":"mc","stem":"「개미와 비둘기」에서 가장 먼저 일어난 일은 무엇인가요?","options":[{"t":"개미가 물에 빠졌다","correct":true},{"t":"개미가 사냥꾼의 발을 물었다","mis":"K4-1-u1-X15"},{"t":"사냥꾼이 그물을 던졌다","mis":"K4-1-u1-X15"},{"t":"비둘기가 나뭇잎을 떨어뜨렸다","mis":"K4-1-u1-X15"}],"explanation":["①을 봐요.","「어느 날」이 처음이에요.","물에 빠졌어요."],"asset":{"type":"passage","lines":["① 어느 날, 개미가 물을 마시러 갔다가 발을 헛디뎌 물에 빠졌다.","② 나무 위에 있던 비둘기가 이를 보고 나뭇잎 하나를 떨어뜨려 개미를 구해 주었다.","③ 며칠 뒤, 사냥꾼이 비둘기를 잡으려고 그물을 던졌다.","④ 그 순간 개미가 사냥꾼의 발을 물어 비둘기를 구해 주었다."],"title":"개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#4','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C38',1,'mc','auto','「씨앗 말고도 오래 지켜야 할 것이 또 있을까?」는 어떤 갈래의 질문인가요?',ARRAY['K4-1-u1-X33','K4-1-u1-X34']::text[],false,'{"seq":4,"concept":"K4-1-u1-C38","difficulty":1,"kind":"mc","stem":"「씨앗 말고도 오래 지켜야 할 것이 또 있을까?」는 어떤 갈래의 질문인가요?","options":[{"t":"더 궁금한 점을 묻는 질문","correct":true},{"t":"낱말의 뜻을 짐작하는 질문","mis":"K4-1-u1-X33"},{"t":"자신의 경험과 관련지은 질문","mis":"K4-1-u1-X33"},{"t":"글자 수를 세는 질문","mis":"K4-1-u1-X34"}],"explanation":["「또 있을까?」","글 너머가 궁금해요.","더 궁금한 점 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#5','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C54',1,'mc','auto','「맏이」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-1-u1-X45','K4-1-u1-X47']::text[],false,'{"seq":5,"concept":"K4-1-u1-C54","difficulty":1,"kind":"mc","stem":"「맏이」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[마지]","correct":true},{"t":"[마디]","mis":"K4-1-u1-X45"},{"t":"[마치]","mis":"K4-1-u1-X47"},{"t":"[맏이]","mis":"K4-1-u1-X45"}],"explanation":["받침 ㄷ 뒤에 ㅣ","[ㅈ]으로 바뀌어요.","[마지]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#6','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C56',1,'mc','auto','[바치]로 소리 나는 낱말을 넣어 바르게 쓴 문장은 무엇인가요?',ARRAY['K4-1-u1-X46']::text[],false,'{"seq":6,"concept":"K4-1-u1-C56","difficulty":1,"kind":"mc","stem":"[바치]로 소리 나는 낱말을 넣어 바르게 쓴 문장은 무엇인가요?","options":[{"t":"밭이 넓다.","correct":true},{"t":"바치 넓다.","mis":"K4-1-u1-X46"},{"t":"받이 넓다.","mis":"K4-1-u1-X46"},{"t":"밧이 넓다.","mis":"K4-1-u1-X46"}],"explanation":["소리는 [바치]","쓸 때는 글자 그대로","밭이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#7','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C58',1,'mc','auto','「즐겁다」와 뜻이 비슷한 낱말은 무엇인가요?',ARRAY['K4-1-u1-X49']::text[],false,'{"seq":7,"concept":"K4-1-u1-C58","difficulty":1,"kind":"mc","stem":"「즐겁다」와 뜻이 비슷한 낱말은 무엇인가요?","options":[{"t":"기쁘다","correct":true},{"t":"서운하다","mis":"K4-1-u1-X49"},{"t":"외롭다","mis":"K4-1-u1-X49"},{"t":"쓸쓸하다","mis":"K4-1-u1-X49"}],"explanation":["좋은 마음이에요.","기쁨끼리","기쁘다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#8','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C46',1,'mc','auto','「활용하다」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X20']::text[],false,'{"seq":8,"concept":"K4-1-u1-C46","difficulty":1,"kind":"mc","stem":"「활용하다」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"충분히 잘 이용하다","correct":true},{"t":"어떤 일을 자꾸 되풀이하다","mis":"K4-1-u1-X20"},{"t":"어떤 것에 자격을 주다","mis":"K4-1-u1-X20"},{"t":"어떤 상태를 변함없이 이어 가다","mis":"K4-1-u1-X20"}],"explanation":["모은 씨앗을 연구에","잘 써요.","잘 이용하다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#9','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C8',2,'mc','auto','태오의 성격을 알아보려고 해요. 태오의 단서로 모아야 할 것은 무엇인가요?',ARRAY['K4-1-u1-X07']::text[],false,'{"seq":9,"concept":"K4-1-u1-C8","difficulty":2,"kind":"mc","stem":"태오의 성격을 알아보려고 해요. 태오의 단서로 모아야 할 것은 무엇인가요?","options":[{"t":"⑤ 못마땅한 얼굴로 팔짱을 꼈다","correct":true},{"t":"④ \"네가 고른 색이 늘 예쁘던데.\"","mis":"K4-1-u1-X07"},{"t":"③ 아무 말도 못 하고 붓만 만지작거렸다","mis":"K4-1-u1-X07"},{"t":"⑦ 아이들이 \"저 색 정말 좋다!\" 하고 말했다","mis":"K4-1-u1-X07"}],"explanation":["태오가 한 행동","서아 · 하준 · 아이들은 빼요.","⑤예요."],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#10','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C10',2,'mc','auto','하준이와 태오의 관계가 바뀐 계기는 무엇인가요?',ARRAY['K4-1-u1-X08','K4-1-u1-X10','K4-1-u1-X17']::text[],false,'{"seq":10,"concept":"K4-1-u1-C10","difficulty":2,"kind":"mc","stem":"하준이와 태오의 관계가 바뀐 계기는 무엇인가요?","options":[{"t":"하준이가 고른 색으로 칠한 깃발을 보고 아이들이 좋다고 한 일","correct":true},{"t":"태오가 처음부터 하준이를 믿은 일","mis":"K4-1-u1-X08"},{"t":"서아가 태오와 다툰 일","mis":"K4-1-u1-X10"},{"t":"미술 시간이 끝난 일","mis":"K4-1-u1-X17"}],"explanation":["⑥ · ⑦을 봐요.","깃발을 본 반응","그 뒤 태오가 인정했어요."],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#11','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C18',2,'mc','auto','「석봉과 어머니」에서 빠지면 이야기가 이어지지 않는 일은 무엇인가요?',ARRAY['K4-1-u1-X14']::text[],false,'{"seq":11,"concept":"K4-1-u1-C18","difficulty":2,"kind":"mc","stem":"「석봉과 어머니」에서 빠지면 이야기가 이어지지 않는 일은 무엇인가요?","options":[{"t":"⑤ 떡은 고른데 석봉의 글씨는 제각각이었다","correct":true},{"t":"석봉이 고향으로 올 때 탄 것","mis":"K4-1-u1-X14"},{"t":"호롱불의 모양","mis":"K4-1-u1-X14"},{"t":"어머니가 입은 옷의 색","mis":"K4-1-u1-X14"}],"explanation":["이것이 없으면?","석봉이 부끄러워할 까닭이 없어요.","⑤가 꼭 필요해요."],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#12','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C21',2,'mc','auto','「개미와 비둘기」의 일을 일어난 차례대로 놓은 것은 무엇인가요?',ARRAY['K4-1-u1-X15']::text[],false,'{"seq":12,"concept":"K4-1-u1-C21","difficulty":2,"kind":"mc","stem":"「개미와 비둘기」의 일을 일어난 차례대로 놓은 것은 무엇인가요?","options":[{"t":"개미가 물에 빠짐 → 비둘기가 개미를 구함 → 사냥꾼이 그물을 던짐 → 개미가 비둘기를 구함","correct":true},{"t":"사냥꾼이 그물을 던짐 → 개미가 물에 빠짐 → 비둘기가 개미를 구함 → 개미가 비둘기를 구함","mis":"K4-1-u1-X15"},{"t":"개미가 물에 빠짐 → 개미가 비둘기를 구함 → 사냥꾼이 그물을 던짐 → 비둘기가 개미를 구함","mis":"K4-1-u1-X15"},{"t":"비둘기가 개미를 구함 → 개미가 물에 빠짐 → 개미가 비둘기를 구함 → 사냥꾼이 그물을 던짐","mis":"K4-1-u1-X15"}],"explanation":["「어느 날」이 처음","「며칠 뒤」가 그다음","「그 순간」이 끝이에요."],"asset":{"type":"passage","lines":["① 어느 날, 개미가 물을 마시러 갔다가 발을 헛디뎌 물에 빠졌다.","② 나무 위에 있던 비둘기가 이를 보고 나뭇잎 하나를 떨어뜨려 개미를 구해 주었다.","③ 며칠 뒤, 사냥꾼이 비둘기를 잡으려고 그물을 던졌다.","④ 그 순간 개미가 사냥꾼의 발을 물어 비둘기를 구해 주었다."],"title":"개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#13','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C40',2,'mc','auto','「석봉과 어머니」의 내용을 짐작하는 데 도움이 되는 질문은 무엇인가요?',ARRAY['K4-1-u1-X34','K4-1-u1-X35']::text[],false,'{"seq":13,"concept":"K4-1-u1-C40","difficulty":2,"kind":"mc","stem":"「석봉과 어머니」의 내용을 짐작하는 데 도움이 되는 질문은 무엇인가요?","options":[{"t":"어머니는 왜 하필 어둠 속에서 떡을 썰었을까?","correct":true},{"t":"이 이야기는 몇 쪽일까?","mis":"K4-1-u1-X34"},{"t":"석봉은 몇 년 동안 공부했나요?","mis":"K4-1-u1-X35"},{"t":"「어머니」라는 낱말은 몇 번 나올까?","mis":"K4-1-u1-X34"}],"explanation":["세는 질문은 빼요.","답이 그대로 있는 질문보다","「왜?」를 물어요."],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#14','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C34',2,'mc','auto','「긴 줄넘기 연습」이라는 제목과 줄넘기 그림만 보았을 때 만들 수 있는 질문은 무엇인가요?',ARRAY['K4-1-u1-X30','K4-1-u1-X34']::text[],false,'{"seq":14,"concept":"K4-1-u1-C34","difficulty":2,"kind":"mc","stem":"「긴 줄넘기 연습」이라는 제목과 줄넘기 그림만 보았을 때 만들 수 있는 질문은 무엇인가요?","options":[{"t":"누가 왜 긴 줄넘기를 연습했을까?","correct":true},{"t":"「구령」은 무슨 뜻일까?","mis":"K4-1-u1-X30"},{"t":"은채는 민호에게 무엇이라고 말했을까?","mis":"K4-1-u1-X30"},{"t":"이 글은 모두 몇 줄일까?","mis":"K4-1-u1-X34"}],"explanation":["아직 본문을 안 읽었어요.","구령 · 은채는 본문에 나와요.","제목에서 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#15','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C57',2,'mc','auto','「느티나무」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-1-u1-X48']::text[],false,'{"seq":15,"concept":"K4-1-u1-C57","difficulty":2,"kind":"mc","stem":"「느티나무」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[느티나무]","correct":true},{"t":"[느치나무]","mis":"K4-1-u1-X48"},{"t":"[늗이나무]","mis":"K4-1-u1-X48"},{"t":"[느지나무]","mis":"K4-1-u1-X48"}],"explanation":["ㅌ이 받침인가요?","첫소리예요.","그대로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#16','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C13',2,'mc','auto','⑦의 말을 들은 하준이는 어떤 마음이었을까요?',ARRAY['K4-1-u1-X03']::text[],false,'{"seq":16,"concept":"K4-1-u1-C13","difficulty":2,"kind":"mc","stem":"⑦의 말을 들은 하준이는 어떤 마음이었을까요?","options":[{"t":"기쁘고 뿌듯했을 것이다","correct":true},{"t":"서운했을 것이다","mis":"K4-1-u1-X03"},{"t":"쓸쓸했을 것이다","mis":"K4-1-u1-X03"},{"t":"화가 났을 것이다","mis":"K4-1-u1-X03"}],"explanation":["무슨 말을 들었나요?","내 색이 좋다고 했어요.","기쁘고 뿌듯해요."],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#17','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C16',3,'mc','auto','「미술 시간에 생긴 일」을 가장 잘 정리한 것은 무엇인가요?',ARRAY['K4-1-u1-X13','K4-1-u1-X12','K4-1-u1-X17']::text[],false,'{"seq":17,"concept":"K4-1-u1-C16","difficulty":3,"kind":"mc","stem":"「미술 시간에 생긴 일」을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"색칠만 맡은 하준이가 서아 덕분에 색을 정해 깃발을 멋지게 칠하고 태오의 인정을 받았다.","correct":true},{"t":"깃발을 만들었다.","mis":"K4-1-u1-X13"},{"t":"하준이는 뒤로 물러서는 아이였고, 태오가 말했고, 하준이는 붓을 만지작거렸고, 서아가⋯⋯","mis":"K4-1-u1-X12"},{"t":"태오가 팔짱을 꼈다.","mis":"K4-1-u1-X17"}],"explanation":["너무 짧지 않게","너무 자세하지 않게","중요한 일을 차례대로"],"asset":{"type":"passage","lines":["① 하준이는 그림을 잘 못 그린다며 늘 뒤로 물러서는 아이였다.","② \"하준이는 색칠만 해. 그림은 우리가 그릴게.\" 태오가 말했다.","③ 하준이는 아무 말도 못 하고 붓만 만지작거렸다.","④ 서아가 말했다. \"하준아, 네가 고른 색이 늘 예쁘던데. 색은 네가 정해 줘.\"","⑤ 태오는 못마땅한 얼굴로 팔짱을 꼈다.","⑥ 하준이는 하늘색에 노란색을 조금 섞어 깃발의 바탕을 칠했다.","⑦ 깃발을 교실 앞에 걸자 아이들이 \"저 색 정말 좋다!\" 하고 말했다.","⑧ 태오는 멋쩍게 웃으며 말했다. \"네 눈이 나보다 낫네.\""],"title":"미술 시간에 생긴 일 — 모둠 깃발"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#18','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C31',3,'mc','auto','「나와 좀 다르다고 틀린 것은 아니에요.」라는 문장과 가장 잘 어울리는 장면은 무엇인가요?',ARRAY['K4-1-u1-X25','K4-1-u1-X26']::text[],false,'{"seq":18,"concept":"K4-1-u1-C31","difficulty":3,"kind":"mc","stem":"「나와 좀 다르다고 틀린 것은 아니에요.」라는 문장과 가장 잘 어울리는 장면은 무엇인가요?","options":[{"t":"눈이 어두운 무루가 앞발로 흙의 떨림을 느껴 모두를 구한 장면","correct":true},{"t":"석봉이 어둠 속에서 글씨를 쓴 장면","mis":"K4-1-u1-X25"},{"t":"개미가 물에 빠진 장면","mis":"K4-1-u1-X25"},{"t":"또래 두더지들이 무루를 밀어낸 장면","mis":"K4-1-u1-X26"}],"explanation":["다른 점이 힘이 된 장면","무루의 앞발","모두를 구했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#19','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C48',3,'mc','auto','읽기 전에 「씨앗은 냉동실에 잘 넣어 두면 지킬 수 있을 것이다」라고 짐작했어요. 글과 다른 점으로 알맞은 것은 무엇인가요?',ARRAY['K4-1-u1-X41','K4-1-u1-X40']::text[],false,'{"seq":19,"concept":"K4-1-u1-C48","difficulty":3,"kind":"mc","stem":"읽기 전에 「씨앗은 냉동실에 잘 넣어 두면 지킬 수 있을 것이다」라고 짐작했어요. 글과 다른 점으로 알맞은 것은 무엇인가요?","options":[{"t":"냉동실만으로는 끝내 힘을 잃고 심고 거두기를 거듭해야 한다는 점","correct":true},{"t":"짐작한 글자 수와 실제 글자 수가 달랐다","mis":"K4-1-u1-X41"},{"t":"짐작이 달랐으니 이 글은 잘못 쓴 글이다","mis":"K4-1-u1-X40"},{"t":"짐작과 글의 글자 크기가 달랐다","mis":"K4-1-u1-X41"}],"explanation":["⑤ · ⑥을 봐요.","내용끼리 견줘요.","거듭해야 해요."],"asset":{"type":"passage","lines":["① 토종 씨앗은 본디부터 우리 땅에서 자라 온 식물에서 얻은 씨앗이다.","② 조상들은 아무리 어려워도 씨앗만은 남겼다. 씨앗에 농사의 지혜가 담겼기 때문이다.","③ 오늘날에는 농가에서 재배하는 채소 씨앗도 밖에서 사 오는 일이 많다.","④ 씨앗이 사라지면 그 씨앗에 담긴 우리의 역사도 함께 사라진다.","⑤ 냉동실에 넣어 두면 얼마 동안은 지킬 수 있다.","⑥ 그러나 심고 거두기를 거듭하지 않으면 씨앗은 끝내 힘을 잃는다.","⑦ 여러 사람과 씨앗을 나누고 정성껏 심고 거두는 것이 씨앗을 되살리는 길이다.","⑧ 씨앗을 나누는 모임에서는 모은 씨앗을 새 농사 연구에도 활용한다."],"title":"씨앗을 지키는 사람들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#20','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C41',3,'mc','auto','「개미와 비둘기」를 더 깊이 보게 하는 질문은 무엇인가요?',ARRAY['K4-1-u1-X35','K4-1-u1-X36']::text[],false,'{"seq":20,"concept":"K4-1-u1-C41","difficulty":3,"kind":"mc","stem":"「개미와 비둘기」를 더 깊이 보게 하는 질문은 무엇인가요?","options":[{"t":"작은 개미는 왜 사냥꾼의 발을 물 생각을 했을까?","correct":true},{"t":"비둘기는 무엇을 떨어뜨렸나요?","mis":"K4-1-u1-X35"},{"t":"개미는 무엇을 하러 갔다가 빠졌나요?","mis":"K4-1-u1-X35"},{"t":"개미 질문을 많이 만들기만 하면 될까?","mis":"K4-1-u1-X36"}],"explanation":["답이 그대로 있나요?","빈 곳을 메워요.","「왜?」를 물어요."],"asset":{"type":"passage","lines":["① 어느 날, 개미가 물을 마시러 갔다가 발을 헛디뎌 물에 빠졌다.","② 나무 위에 있던 비둘기가 이를 보고 나뭇잎 하나를 떨어뜨려 개미를 구해 주었다.","③ 며칠 뒤, 사냥꾼이 비둘기를 잡으려고 그물을 던졌다.","④ 그 순간 개미가 사냥꾼의 발을 물어 비둘기를 구해 주었다."],"title":"개미와 비둘기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#21','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C52',3,'mc','auto','누구일까 놀이에서 친구가 좀처럼 맞히지 못해요. 알맞게 한 것은 무엇인가요?',ARRAY['K4-1-u1-X44']::text[],false,'{"seq":21,"concept":"K4-1-u1-C52","difficulty":3,"kind":"mc","stem":"누구일까 놀이에서 친구가 좀처럼 맞히지 못해요. 알맞게 한 것은 무엇인가요?","options":[{"t":"차례를 한 줄 더 보여 주며 실마리를 준다","correct":true},{"t":"책의 마지막 쪽을 펴서 이름을 보여 준다","mis":"K4-1-u1-X44"},{"t":"정답을 바로 말해 준다","mis":"K4-1-u1-X44"},{"t":"다음부터는 이름을 가리지 않는다","mis":"K4-1-u1-X44"}],"explanation":["짐작하는 놀이예요.","실마리를 더 줘요.","정답은 끝까지 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#22','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C30',3,'mc','auto','「석봉과 어머니」의 흐름을 두 인물의 관계를 중심으로 바르게 정리한 것은 무엇인가요?',ARRAY['K4-1-u1-X16','K4-1-u1-X15','K4-1-u1-X27']::text[],false,'{"seq":22,"concept":"K4-1-u1-C30","difficulty":3,"kind":"mc","stem":"「석봉과 어머니」의 흐름을 두 인물의 관계를 중심으로 바르게 정리한 것은 무엇인가요?","options":[{"t":"어머니가 돌아온 석봉을 반기지 않음 → 어머니가 시험함 → 꾸짖어 돌려보냄 → 석봉이 부끄러워하며 다시 공부함","correct":true},{"t":"어머니가 돌아온 석봉을 크게 반김 → 함께 떡을 나누어 먹음","mis":"K4-1-u1-X16"},{"t":"어머니가 시험함 → 석봉이 돌아옴 → 석봉이 다시 공부함 → 꾸짖어 돌려보냄","mis":"K4-1-u1-X15"},{"t":"석봉이 돌아옴 → 석봉이 다시 공부함","mis":"K4-1-u1-X27"}],"explanation":["두 인물 사이를 따라가요.","차례를 지켜요.","바뀐 마디를 넣어요."],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#23','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C28',4,'essay','teacher','「석봉과 어머니」에서 어머니가 한 말과 행동을 근거로 어머니의 성격과 역할을 쓰고, 어머니와 석봉은 어떤 관계인지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-1-u1-C28","difficulty":4,"kind":"essay","stem":"「석봉과 어머니」에서 어머니가 한 말과 행동을 근거로 어머니의 성격과 역할을 쓰고, 어머니와 석봉은 어떤 관계인지 쓰세요.","answer_guide":{"answer":"예: 어머니는 돌아온 석봉을 반가워하지 않고 호롱불을 끈 채 글씨를 써 보라고 했으며, 글씨가 제각각이자 꾸짖어 돌려보냈다. 자식이 제대로 배우기를 바라는 엄한 성격이고, 석봉이 자만을 깨닫게 하는 역할을 했다. 겉으로는 부딪히는 것 같지만 석봉을 바르게 이끄는 관계이다.","scoring_points":["어머니의 말이나 행동을 근거로 들었는가","어머니의 성격과 역할을 썼는가","어머니와 석봉의 관계를 썼는가"]},"explanation":["③ · ⑥을 봐요.","성격과 역할","어떤 관계?"],"asset":{"type":"passage","lines":["① 석봉은 한양에서 3년 동안 글씨 공부를 하고 고향집으로 돌아왔다.","② \"어머니, 제가 명필이 되어 돌아왔습니다.\" 그러나 어머니는 반가워하지 않았다.","③ 어머니는 호롱불을 훅 끄고 말했다. \"어둠 속에서 글씨를 써 보아라.\"","④ 어둠 속에서 석봉은 글씨를 쓰고, 어머니는 떡을 썰었다.","⑤ 불을 켜 보니 떡은 고른데, 석봉의 글씨는 크기도 모양도 제각각이었다.","⑥ 어머니는 석봉을 꾸짖어 그날로 한양에 돌려보냈다.","⑦ 석봉은 자만했던 자신을 부끄러워하며 다시 공부에 힘썼다."],"title":"석봉과 어머니"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#24','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C21',4,'essay','teacher','「돌다리를 놓은 아이」의 흐름을 시간의 변화를 알려 주는 말(날마다 · 여름이 가고 겨울이 오도록 · 이듬해 봄)을 넣어 정리하세요.','{}'::text[],false,'{"seq":24,"concept":"K4-1-u1-C21","difficulty":4,"kind":"essay","stem":"「돌다리를 놓은 아이」의 흐름을 시간의 변화를 알려 주는 말(날마다 · 여름이 가고 겨울이 오도록 · 이듬해 봄)을 넣어 정리하세요.","answer_guide":{"answer":"예: 비가 오면 마을 사람들은 장에 가지 못했다. 동이는 날마다 개울에 돌을 하나씩 날라 놓았고, 사람들이 웃어도 여름이 가고 겨울이 오도록 멈추지 않았다. 이듬해 봄, 개울에 돌다리가 놓여 비가 와도 장에 갈 수 있게 되었다.","scoring_points":["시간의 변화를 알려 주는 말을 넣었는가","중요한 일만 골랐는가","일이 일어난 차례대로 썼는가"]},"explanation":["날마다","여름 → 겨울","이듬해 봄"],"asset":{"type":"passage","lines":["① 옛날 어느 산골 마을 사람들은 개울을 건너야 장터에 갈 수 있었어요.","② 비가 오면 개울물이 불어 사람들은 며칠씩 장에 가지 못했어요.","③ 동이는 날마다 개울에서 넓적한 돌을 하나씩 날라 놓았어요.","④ \"그걸로 언제 다리를 만드니?\" 마을 사람들은 웃었어요.","⑤ 동이네 집 마당에는 감나무가 한 그루 서 있었어요.","⑥ 여름이 가고 겨울이 오도록 동이는 돌 나르기를 멈추지 않았어요.","⑦ 이듬해 봄, 개울에 튼튼한 돌다리가 놓였어요.","⑧ 그 뒤로는 비가 와도 마을 사람들이 장에 갈 수 있었어요."],"title":"돌다리를 놓은 아이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_kor_u1_review_d#25','kor',4,1,'u1','','g4_1_kor_u1_review_d','unit_review','K4-1-u1-C49',4,'essay','teacher','「바람이 드나드는 종이」라는 제목만 보고 내용을 짐작해 한 문장으로 쓰고, 글을 읽은 뒤 짐작과 같은 점과 새로 안 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-1-u1-C49","difficulty":4,"kind":"essay","stem":"「바람이 드나드는 종이」라는 제목만 보고 내용을 짐작해 한 문장으로 쓰고, 글을 읽은 뒤 짐작과 같은 점과 새로 안 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 짐작 — 바람이 잘 통하는 종이를 소개하는 글일 것이다. 같은 점 — 한지는 종이 사이로 바람이 잘 드나든다. 새로 안 점 — 한지는 닥나무 껍질로 만들고 질겨서 잘 찢어지지 않아 옛날 사람들이 문에 발라 썼다.","scoring_points":["제목을 보고 짐작한 내용을 썼는가","짐작과 같은 점을 썼는가","짐작과 달라 새로 안 점을 썼는가"]},"explanation":["제목에서 짐작","같은 점","새로 안 점"],"asset":{"type":"passage","lines":["① 한지는 닥나무 껍질로 만든 우리 종이이다.","② 한지는 질겨서 잘 찢어지지 않는다.","③ 또 종이 사이로 바람이 잘 드나든다.","④ 그래서 옛날 사람들은 한지를 문에 발라 썼다."],"title":"바람이 드나드는 종이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
